const e=[{id:1,code:"FACT-101",icon:"HardHat",accent:"#ea580c",title:"کەرەستەکانی خۆپاراستن (PPE)",subtitle:"Personal Protective Equipment",summary:"ناسینی کەرەستەکانی خۆپاراستن و بەکارهێنانی دروستیان",blocks:[{body:"کەرەستەکانی خۆپاراستنی کەسی (PPE) دوایین هێڵی بەرگرین دژی برینداربوون: پێش ئەوان، دەبێت مەترسی بە ڕێگا ئەندازیارییەکان و ڕێکارەکانی کار لاببرێت یان کەم بکرێتەوە (Hierarchy of Controls). لە کارگەکاندا بەکارهێنانی PPE ئارەزوومەندانە نییە، بەڵکو ناچارییە."},{heading:"١. جۆرە سەرەکییەکانی PPE",body:"بۆ هەر ئەندامێکی لەش کەرەستەیەکی تایبەت هەیە:",points:["سەر: کڵاوی پاراستن (Hard Hat) — پاراستن دژی کەوتنی شتەکان و لێدان.","چاو: چاویلکەی سەلامەتی (Safety Glasses) — پاراستن دژی تۆز، ماددە کیمیاییەکان و پڕیشک.","گوێ: پارێزەری گوێ (Earmuffs / Earplugs) — دژی دەنگی بەرزی ئامێرەکان (٨٥ dB(A) و زیاتر).","دەست: دەستکێش — دژی بڕین، گەرما و ماددە کیمیاییەکان.","پێ: پێڵاوی سەلامەتی بە سەری ئاسنین (Steel Toe) — دژی پلیشانەوە و کەوتنی شتی قورس.","لەش: جلی ئاشکرا (Hi-Vis) بە ڕەنگی گەش — بۆ ئەوەی شۆفێران و کرێکارانی تر بتبینن."]}],media:[{kind:"video",src:"media/videos/ppe_tutorial.mp4",title:"PPE",description:"ڕێگای دروستی لەبەرکردن"}],quiz:[{question:"بەپێی ستانداردە ئەوروپییەکان، کەی بەکارهێنانی پارێزەری گوێ ناچاری دەبێت؟",options:[{text:"٥٠ dB",correct:!1},{text:"٧٠ dB",correct:!1},{text:"٨٥ dB(A) و زیاتر (تێکڕای ٨ کاتژمێری کار)",correct:!0},{text:"١٢٠ dB",correct:!1}],explanation:"بەپێی ڕێنماییی ئەوروپی 2003/10/EC، کاتێک تێکڕای دەنگ لە ٨ کاتژمێری کاردا دەگاتە ٨٥ dB(A)، دەبێت پارێزەری گوێ بەکاربهێنرێت. OSHA یش لە ٨٥ dBA داوای بەرنامەی پاراستنی بیستن دەکات."},{question:"کەرەستەکانی خۆپاراستن (PPE) دوایین هێڵی بەرگرین دژی برینداربوون. دەبێت چی پێش ئەوان بکرێت؟",options:[{text:"کڕینی کەرەستەی پاراستنی گرانبەهاتر",correct:!1},{text:"لابردن یان کەمکردنەوەی مەترسی",correct:!0},{text:"داواکردن لە کرێکاران کە خێراتر کار بکەن تا ماوەی مەترسی کەم ببێتەوە",correct:!1},{text:"چاوەڕوانی تا برینداربوونێک شوێنی مەترسییەکە دیار بکات",correct:!1}],explanation:"پێش PPE، دەبێت مەترسی بە ڕێگا ئەندازیارییەکان و ڕێکارەکانی کار لاببرێت یان کەم بکرێتەوە (Hierarchy of Controls)؛ PPE دوایین هێڵی بەرگرین و لە کارگەکاندا بەکارهێنانیان هەر ناچارییە."},{question:"بۆچی کرێکاران جلی ئاشکرا (Hi-Vis) بە ڕەنگی گەش لەبەر دەکەن؟",options:[{text:"بۆ پاراستنی پێست لە ماددە کیمیاییەکان و گەرما",correct:!1},{text:"بۆ ئەوەی دیار بێت هەر کرێکارێک سەر بە کام بەشە",correct:!1},{text:"بۆ ئەوەی لەش لە کارگە ساردەکاندا گەرم ڕابگرن",correct:!1},{text:"بۆ ئەوەی شۆفێران و کرێکارانی تر بیانبینن",correct:!0}],explanation:"جلی ئاشکرا بە ڕەنگی گەش کرێکار دیار دەکات بۆ ئەوەی شۆفێران و کرێکارانی تر بیبینن؛ پاراستن لە ماددە کیمیاییەکان و گەرما کاری کەرەستەی ترە، وەک دەستکێش."}]},{id:2,code:"FACT-102",icon:"Cog",accent:"#2563eb",title:"سەلامەتیی ئامێرەکان",subtitle:"Machine Safety & Guarding",summary:"پاراستنی کرێکاران لە بەشە جووڵاوەکانی ئامێرەکان",blocks:[{body:"ئامێرە پیشەسازییەکان هێزێکی زۆریان هەیە و دەتوانن لە چرکەیەکدا برینی سەخت یان لەدەستدانی ئەندامێکی لەش دروست بکەن."},{heading:"١. پارێزەرەکانی ئامێر (Machine Guards)",body:"دەبێت ئەم پاراستنانە لەسەر هەموو ئامێرە مەترسیدارەکان هەبن:",points:["پارێزەری جێگیر: بۆ داپۆشینی قایش و چەرخە دەندانەدارە جووڵاوەکان.","دوگمەی وەستاندنی تەنگانە (E-Stop): دەبێت نزیکی دەستی کرێکار بێت و بە ڕەنگی سوور لەسەر بنکەیەکی زەرد بێت.","هەستەوەرەکانی وەستاندن: ئامێرەکە دەوەستێت ئەگەر دەست یان لەش لە شوێنی مەترسیدار نزیک ببێتەوە."]},{heading:"٢. یاسا زێڕینەکان",body:"پێش کار و لە کاتی کاردا:",points:["هەرگیز پارێزەری ئامێر لامەبە کاتێک ئامێرەکە کار دەکات.","جلی شل، زنجیر و ئەنگوستیلە لەبەر مەکە و قژی درێژ ببەستەوە، بۆ ئەوەی نەکەونە ناو ئامێرەکەوە.","ئەگەر ئامێرەکە تێکچوو، یەکسەر بە دوگمەی E-Stop بیوەستێنە و بەبێ ڕێکاری LOTO دەستت مەخە ناو ئامێرەکەوە."]}],media:[{kind:"image",src:"media/images/machine_guard.png",title:"پارێزەرەکانی ئامێر",description:"نموونەی پارێزەرێکی دروست"}],quiz:[{question:"ئایا دروستە پارێزەری ئامێر لاببرێت کاتێک ئامێرەکە کار دەکات؟",options:[{text:"بەڵێ، ئەگەر پێویست بوو",correct:!1},{text:"نەخێر، بە هیچ شێوەیەک دروست نییە",correct:!0},{text:"تەنها بۆ پاککردنەوە",correct:!1},{text:"هەموو وەڵامەکان دروستن",correct:!1}],explanation:"لابردنی پارێزەری ئامێر لە کاتی کارکردنیدا یەکێکە لە مەترسیدارترین ڕەفتارەکان. پاککردنەوە و چاککردنەوە تەنها دوای وەستاندن و قوفڵکردنی ئامێرەکە (LOTO) ئەنجام دەدرێن."},{question:"ئەگەر ئامێرەکە لە کاتی کاردا تێکچوو، چی دەکەیت؟",options:[{text:"یەکسەر بە دوگمەی E-Stop دەیوەستێنم",correct:!0},{text:"بە خێرایی دەستم دەخەمە ناوی و شتە گیراوەکە بە دەست دەردەهێنم",correct:!1},{text:"دەهێڵم کار بکات و دواتر بەرپرس ئاگادار دەکەمەوە",correct:!1},{text:"پارێزەری ئامێرەکە لادەبەم بۆ ئەوەی ببینم چی تێکچووە",correct:!1}],explanation:"ئەگەر ئامێرەکە تێکچوو، یەکسەر بە دوگمەی E-Stop بیوەستێنە و بەبێ ڕێکاری LOTO دەستت مەخە ناو ئامێرەکەوە."},{question:"بۆچی نابێت جلی شل، زنجیر یان ئەنگوستیلە لە نزیک ئامێرەکان لەبەر بکەیت؟",options:[{text:"چونکە خوێندنەوەی دوگمەکانی ئامێرەکە قورس دەکەن",correct:!1},{text:"تەنها چونکە دژی ڕێساکانی جلوبەرگی کارگەکەن",correct:!1},{text:"چونکە دەتوانن بکەونە ناو ئامێرەکەوە",correct:!0},{text:"چونکە دەتوانن پارێزەرەکانی ئامێر تێکبدەن",correct:!1}],explanation:"جلی شل، زنجیر، ئەنگوستیلە و قژی درێژ دەتوانن بکەونە ناو ئامێرەکەوە، و ئامێر دەتوانێت لە چرکەیەکدا برینی سەخت دروست بکات؛ بۆیە قژی درێژیش ببەستەوە."}]},{id:3,code:"FACT-103",icon:"PlugZap",accent:"#ca8a04",title:"سەلامەتیی کارەبا",subtitle:"Industrial Electrical Safety (LOTO)",summary:"مەترسییەکانی کارەبا و سیستەمی قوفڵکردن و نیشانەکردن (LOTO)",blocks:[{body:"کارەبا لە کارگەکاندا بە ڤۆڵتیەی بەرز کار دەکات؛ کارەبالێدان دەتوانێت ببێتە هۆی مردن یان سووتانی سەخت."},{heading:"١. سیستەمی قوفڵکردن و نیشانەکردن (Lockout/Tagout — LOTO)",body:"ئەمە گرنگترین ڕێکارە پێش چاککردنەوە یان پاککردنەوەی ئامێرەکان:",points:["قوفڵکردن (Lockout): سەرچاوەی سەرەکیی کارەبا ببڕە و قوفڵێکی کەسیی لێ بدە.",'نیشانەکردن (Tagout): کارتێکی پێوە هەڵبواسە کە لەسەری نووسرابێت: "کاری لەسەر دەکرێت — هەڵیمەکە"، لەگەڵ ناوی خۆت و بەروار.',"کلیلەکە تەنها لە دەستی ئەو کەسەدا بێت کە چاککردنەوەکە دەکات؛ و پێش دەستپێکردن دڵنیا ببەوە کە ئامێرەکە بەڕاستی بێ وزەیە (Verify)."]},{heading:"٢. پشکنینی کێبڵەکان",body:"هەمیشە بپشکنە:",points:["کێبڵی بڕاو یان ئەو کێبڵانەی وایەرەکانیان دیارە بەکارمەهێنە.","کارەبا و ئاو دوژمنی یەکترن؛ لە شوێنی تەڕدا ئامێری کارەبایی بەکارمەهێنە."]}],media:[{kind:"video",src:"media/videos/loto_safety.mp4",title:"LOTO",description:"چۆن قوفڵ بەکاردەهێنین؟"}],quiz:[{question:"مەبەست لە LOTO چییە؟",options:[{text:"پاککردنەوە",correct:!1},{text:"بڕین و قوفڵکردنی وزە پێش چاککردنەوە",correct:!0},{text:"زیادکردنی خێرایی ئامێرەکە",correct:!1},{text:"هیچ کامیان نییە",correct:!1,fixed:!0}],explanation:"سیستەمی LOTO بەکاردەهێنرێت بۆ ئەوەی کەس کارەبا هەڵنەکاتەوە کاتێک کرێکار لەسەر ئامێرەکە کار دەکات (OSHA 29 CFR 1910.147)."},{question:"قوفڵە کەسییەکەت لێدا و کارتەکەت پێوە هەڵواسی. پێش دەستپێکردنی چاککردنەوە دەبێت چی بکەیت؟",options:[{text:"کلیلەکە بدەمە هاوڕێیەکم بۆ ئەوەی بیپارێزێت",correct:!1},{text:"ئامێرەکە بۆ ماوەیەکی کورت هەڵبکەم بۆ تاقیکردنەوەی قوفڵەکە",correct:!1},{text:"دڵنیا ببمەوە کە ئامێرەکە بەڕاستی بێ وزەیە",correct:!0},{text:"یەکسەر دەست پێ بکەم، چونکە تەنها قوفڵەکە بەسە بۆ سەلامەتی",correct:!1}],explanation:"پێش دەستپێکردن دڵنیا ببەوە کە ئامێرەکە بەڕاستی بێ وزەیە (Verify)؛ کلیلەکە تەنها لە دەستی ئەو کەسەدا دەمێنێتەوە کە چاککردنەوەکە دەکات، بۆ ئەوەی کەس کارەبا هەڵنەکاتەوە."},{question:"ئەگەر کێبڵێکی بڕاوت بینی کە وایەرەکانی دیارن، چی دەکەیت؟",options:[{text:"تەنها لە شوێنی وشکدا بەکاری دەهێنم",correct:!1},{text:"بەکاری ناهێنم",correct:!0},{text:"بە شریتی لکێنەر دەیپێچم و بەردەوام بەکاری دەهێنم",correct:!1},{text:"تەنها بۆ ئامێری سووک بەکاری دەهێنم",correct:!1}],explanation:"کێبڵی بڕاو یان ئەو کێبڵانەی وایەرەکانیان دیارە بەکارمەهێنە؛ کارەبالێدان دەتوانێت ببێتە هۆی مردن یان سووتانی سەخت."}]},{id:4,code:"FIRE-104",icon:"FireExtinguisher",accent:"#dc2626",title:"ئاگرکوژێنەرەوە — ڕاهێنانی تەواو",subtitle:"Fire Extinguisher — Complete Training (PASS)",summary:"ناسینی جۆرەکانی ئاگرکوژێنەرەوە، پۆلەکانی ئاگر و ڕێکاری PASS بە وردی",blocks:[{body:"ئاگرکوژێنەرەوە (Fire Extinguisher) ئامێرێکی سەرەکییە بۆ کوژاندنەوەی ئاگری بچووک لە قۆناغی سەرەتاییدا. لە کارگەکاندا هەر کارمەندێک دەبێت بزانێت چۆن بە خێرایی و بە دروستی ئاگرکوژێنەرەوە بەکاربهێنێت. زانینی جۆرەکانی ئاگرکوژێنەرەوە و پۆلەکانی ئاگر ژیانی خۆت و هاوڕێکانت دەپارێزێت. ئاگرکوژێنەرەوەی دەستی تەنها چەند چرکەیەک کار دەکات، بۆیە دەبێت بە دروستی ئاراستە بکرێت. ئەگەر ئاگرەکە گەورە بوو یان دووکەڵ زۆر بوو، ئاگرکوژێنەرەوەکە جێبهێڵە، دەربچۆ و پەیوەندی بە ١١٥ بکە."},{heading:"١. پۆلەکانی ئاگر بەپێی NFPA (Fire Classes)",body:"بەپێی سیستەمی ئەمریکی (NFPA)، ئاگر دابەش دەبێت بۆ ٥ پۆل و هەر پۆلێک پێویستی بە ئاگرکوژێنەرەوەیەکی گونجاو هەیە. پۆلەکانی ئاگر لێرەدا بە پیتەکانی NFPA 10 نووسراون وەک سەرچاوەی پرۆژە؛ سیستەمی فەرمیی دهۆک هێشتا پشتڕاست نەکراوەتەوە. هاوتاکانی EN 2: NFPA A = EN A؛ NFPA B (شلە) = EN B؛ NFPA B (گاز) = EN C؛ NFPA C (ئامێری کارەبایی کە کارەبای تێدایە) هیچ پۆلێکی EN ی نییە؛ NFPA D = EN D؛ NFPA K = EN F.",points:["پۆلی A (کەرەستەی ڕەق): دار، کاغەز، قوماش، پلاستیک. ئاگرکوژێنەرەوە: ئاو، کەف، تۆزی ABC.","پۆلی B (شلەمەنی و گازە ئاگرگرەکان): بەنزین، نەوت، ڕۆن، ئەلکهول، گاز. شلەمەنی: CO₂، تۆزی ABC یان کەف؛ بۆ ئەلکهول و شلە جەمسەرییەکانی تر (polar solvents): CO₂، تۆزی وشک یان کەفی بەرگەگری ئەلکهول (AR foam)، چونکە کەفی ئاسایی لەسەریان تێکدەچێت. گاز: یەکەمجار گازەکە ڕابگرە ئەگەر سەلامەت بوو؛ هەرگیز ئاگری گاز مەکوژێنەرەوە ئەگەر نەتوانیت گازەکە ڕابگریت. (هەرگیز ئاو بەکارمەهێنە!)","پۆلی C (ئەو ئامێرە کارەباییانەی کارەبایان تێدایە): سویچ، ترانسفۆرمەر، تابلۆ، مۆلیدە (جەنەڕەیتەر). ئاگرکوژێنەرەوە: CO₂، تۆزی ABC، Clean Agent. (ئاو و کەف بەکارمەهێنە مەگەر لەیبڵەکە پۆلی C یان نیشانەی تاقیکردنەوەی کارەبایی نیشان بدات، وەک هەندێک ئاگرکوژێنەرەوەی تەمی ئاو (water mist)!)","پۆلی D (کانزاکان): کانزا ئاگرگرەکان — مەگنیسیۆم، تیتانیۆم، سۆدیۆم و تۆزی ئەلەمنیۆم. ئاگرکوژێنەرەوە: تەنها ئاگرکوژێنەرەوەیەکی پۆلی D یان ماددەیەک کە ناوی ئەو کانزایە لەسەر لەیبڵەکەی هاتبێت؛ ماددەکە لە کانزایەکەوە بۆ یەکێکی تر جیاوازە. (ئاو دەتوانێت تەقینەوە دروست بکات!)","پۆلی K (چێشتخانە): ڕۆن و چەورییەکانی چێشتلێنان. ئاگرکوژێنەرەوە: Wet Chemical. (ئاو ڕۆنی داغ بڵاو دەکاتەوە!) — لە EN 2 دا ئەمە پۆلی F ە."]},{heading:"٢. جۆرەکانی ئاگرکوژێنەرەوە لە کارگەکاندا",body:"ڕەنگ پۆلی ئاگر نییە. بەپێی BS EN 3، لەشی ئاگرکوژێنەرەوە سوورە؛ لە بەریتانیا پارچەیەکی ڕەنگکراو (BS 7863) ماددەکە نیشان دەدات. وڵاتانی تر ڕەنگی تر بەکاردەهێنن و ڕەنگەکانی دهۆک هێشتا پشتڕاست نەکراونەتەوە، بۆیە هەمیشە لەیبڵ و نیشانەکانی پۆل بخوێنەرەوە. پۆلەکانی خوارەوە بە پیتەکانی NFPA ن:",points:["ئاگرکوژێنەرەوەی ئاو (Water): هەمووی سوور، بێ پارچەی ڕەنگکراو — تەنها بۆ پۆلی A (دار، کاغەز). هەرگیز بۆ کارەبا یان ڕۆن بەکاری مەهێنە!","ئاگرکوژێنەرەوەی CO₂: پارچەی ڕەش لە بەریتانیا — بۆ پۆلی B و ئامێرە کارەباییەکان کە کارەبایان تێدایە (B و C بەپێی NFPA؛ بەپێی EN 2، C گازە و CO₂ بۆ ئاگری گاز نییە). گازێکی زۆر سارد دەردەچێت و لوولەکە (Horn) زۆر سارد دەبێت؛ تەنها دەسکەکە بگرە و هەرگیز دەست بە لوولەکەوە مەگرە، دەستت بە سەرما دەسووتێت! مەودای CO₂ کورتە و بۆ ئاگری قووڵی دار و کاغەز نییە: لەو دوورییەوە دەست پێبکە کە لەسەر لەیبڵەکەی هاتووە و تەنها کاتێک ئاگرەکە بچووک دەبێتەوە نزیکتر ببەوە. لە ژووری بچووکدا دوای بەکارهێنان دەربچۆ و هەوا بگۆڕە، چونکە CO₂ ئۆکسجین کەم دەکاتەوە.","ئاگرکوژێنەرەوەی تۆزی ABC (Dry Powder): پارچەی شین لە بەریتانیا — بۆ پۆلەکانی A، B و C (نەک بۆ D و K). بڵاوترین جۆرە. تۆزێکی سپی دەردەچێت؛ کەموکووڕییەکەی: بینین کەم دەکاتەوە و ئامێرەکان پیس دەکات.","ئاگرکوژێنەرەوەی کەف (Foam/AFFF): پارچەی کرێمی لە بەریتانیا — بۆ پۆلەکانی A و B. کەفەکە لەسەر شلەمەنییەکە ڕادەخات و ئۆکسجینی لێ دەبڕێت. بۆ کارەبا بەکاری مەهێنە!","ئاگرکوژێنەرەوەی Clean Agent: پۆلەکانی بەپێی مۆدێل جیاوازن، بۆیە لەیبڵەکە بخوێنەرەوە (زۆرجار B و C بە پیتەکانی NFPA؛ هەندێک مۆدێل بۆ A یش) — بۆ ئامێرە هەستیارەکان و ژووری سێرڤەرەکان. پاشماوە بەجێناهێڵێت و زیان بە ئامێرە ئەلیکترۆنییەکان ناگەیەنێت.","ئاگرکوژێنەرەوەی تایبەت (Class D): بۆ کانزا ئاگرگرەکان لە کارگەکاندا — دەبێت ناوی ئەو کانزایەی لەوێ بەکاردێت لەسەر لەیبڵەکەی هاتبێت. هەرگیز ئاو مەکە سەر کانزای ئاگرگرتوو!"]},{heading:"٣. ڕێکاری PASS — بە وردی",body:"پێش بەکارهێنانی ئاگرکوژێنەرەوە، دەبێت هەموو وەڵامەکان «بەڵێ» بن: ئاگرەکە بچووک و تازە دەستی پێکردبێت، ئاگرکوژێنەرەوەکە گونجاو بێت، ڕێگای دەرچوون لە پشتتەوە بێت، ئاگادارکردنەوە درابێت و پەیوەندی بە ١١٥ەوە کرابێت، تۆ ڕاهێنراو بیت، و هیچ دووکەڵ یان گەرمایەک ڕێگات نەگرێت. ئەگەر ئاگرەکە یەکسەر نەکوژایەوە، دەربچۆ و دەرگاکە دابخە. PASS ڕێکاری گشتییە بۆ زۆربەی ئاگرکوژێنەرەوە دەستییەکان؛ ئاگرکوژێنەرەوەکانی Class D، Wet Chemical، Clean Agent و ئەوانەی لەسەر تایەن: بەپێی لەیبڵ و ڕێنماییەکانی کۆمپانیای دروستکەر بەکاریان بهێنە:",points:["P = Pull (دەریبکێشە): سنجاقی سەلامەتی (Safety Pin) دەربکێشە. ئەم سنجاقە ڕێگە نادات ئاگرکوژێنەرەوەکە بە هەڵە کار بکات.","A = Aim (ئاراستەی بکە): لوولەی ئاگرکوژێنەرەوەکە ئاراستەی بنکەی ئاگرەکە بکە — نەک سەری بڵێسەکە! سووتەمەنیی ئاگرەکە لە بنەوەیە.","S = Squeeze (بیگوشە): دەسکەکانی ئاگرکوژێنەرەوەکە بە هێز بگوشە بۆ ئەوەی ماددەکە دەربچێت.","S = Sweep (بیجووڵێنە): لوولەکە بە چەپ و ڕاستدا لەسەر بنکەی ئاگرەکە بجووڵێنە تا ئاگرەکە بە تەواوی دەکوژێتەوە؛ پاشان چاودێریی شوێنەکە بکە بۆ ئەوەی ئاگرەکە دووبارە هەڵنەگیرسێتەوە."]},{heading:"٤. پشکنینی مانگانەی ئاگرکوژێنەرەوەکان",body:"پشکنینی چاوی هەموو مانگێک، لەلایەن کەسی بەرپرسەوە (NFPA 10):",points:["پەستانی ناو ئاگرکوژێنەرەوەکە (Pressure Gauge)، ئەگەر هەبێت: دەبێت دەرزییەکە لە ناوچەی سەوزدا بێت. ئاگرکوژێنەرەوەی CO₂ پەستانپێوی نییە: هەڵیبگرە بۆ ئەوەی هەست بکەیت پڕە.","سنجاقی سەلامەتی و مۆرەکەی: دەبێت لە شوێنی خۆیاندا بن و نەشکێنرابن.","لوولە (Nozzle): نابێت شکاو یان گیراو بێت.","لەشی ئاگرکوژێنەرەوەکە: نابێت ژەنگاوی، درزدار یان زیانلێکەوتوو بێت.","کارتی پشکنین و لەیبڵ: دەبێت بەرواری دوایین پشکنین لەسەر کارتەکە بێت؛ لەیبڵەکە بخوێنرێتەوە و ڕووی لە دەرەوە بێت؛ ئاگرکوژێنەرەوەکە لە شوێنی خۆیدا بێت، دیار بێت و بە ئاسانی بگاتێ.","تێبینی: ئەمانە لێک جیا بکەرەوە. پشکنین و چاکسازیی ساڵانە لەلایەن کەسێکی شارەزاوە؛ پڕکردنەوە (Recharge) دوای هەر بەکارهێنانێک، تەنانەت ئەگەر کورتیش بێت؛ چاکسازیی ٦ ساڵە: ئاگرکوژێنەرەوەکانی تۆزی وشکی پەستانی هەڵگیراو (stored-pressure) کە پێویستیان بە تاقیکردنەوەی هایدرۆستاتیکیی ١٢ ساڵە هەیە، هەر ٦ ساڵ جارێک بەتاڵ دەکرێنەوە و ناوەوەیان دەپشکنرێت؛ تاقیکردنەوەی هایدرۆستاتیکی (Hydrostatic Test، تاقیکردنەوەی پەستانی لەشەکەی) هەر ٥ ساڵ بۆ ئاگرکوژێنەرەوەکانی ئاو، کەف (AFFF)، CO₂ و تۆزی وشکی ستێنلێس ستیل (stainless steel)، و هەر ١٢ ساڵ بۆ ئاگرکوژێنەرەوەکانی تۆزی وشکی پەستانی هەڵگیراو کە لەشیان لە پۆڵای ئاسایی (mild steel)، بڕنجی لەحیمکراو (brazed brass) یان ئەلەمنیۆمە. کاتی تاقیکردنەوە کاتی گۆڕین نییە. ڕێساکانی دهۆک هێشتا پشتڕاست نەکراونەتەوە."]},{heading:"٥. مەترسییە تایبەتەکان لە کارگەکاندا",body:"کارگە شوێنێکی هەستیارە لەبەر ئەم هۆکارانە:",points:["ماددە کیمیاییەکان: سۆڵڤێنت، ئەلکهول، تینەر — هەموویان پۆلی B ن.","کارەبای ڤۆڵتیەی بەرز: تابلۆ و ترانسفۆرمەر — پۆلی C (NFPA).","تۆزی دار و ئارد: لە هەندێک کارگەدا دەتوانێت تەقینەوەی تۆز (Dust Explosion) دروست بکات.","لەحیمکردن و بڕین: پڕیشکی لەحیمکردن دەتوانێت ئاگری پۆلەکانی A و B دروست بکات.","کۆگای سووتەمەنی: دەبێت لە ژوورێکی تایبەت یان لە دەرەوەی بیناکە بێت، و ئاگرکوژێنەرەوەی گونجاو (کەف یان تۆز) لە نزیکیەوە بێت.","شوێنی دانان: ئاگرکوژێنەرەوەکان لە نزیک دەرگا و ڕاڕەوەکان دابنێ؛ دووریی گەیشتن بە ئاگرکوژێنەرەوەی پۆلی A نابێت لە ٢٣ مەتر (٧٥ پێ) زیاتر بێت، و بۆ شلەمەنییەکان ٩-١٥ مەتر (NFPA 10)."],critical:!0}],media:[{kind:"video",src:"media/videos/fire_ext_factory.mp4",title:"ئاگرکوژێنەرەوە لە کارگەکاندا",description:"ڕێکاری PASS و جۆرەکانی ئاگرکوژێنەرەوە بە ڤیدیۆ"}],quiz:[{question:"بە پیتەکانی NFPA، ئاگرکوژێنەرەوەی CO₂ بۆ کام پۆلەکانی ئاگر گونجاوە؟",options:[{text:"A و D",correct:!1},{text:"B و C",correct:!0},{text:"A و K",correct:!1},{text:"D و K",correct:!1}],explanation:"CO₂ بۆ شلەمەنییە ئاگرگرەکان (B) و ئامێرە کارەباییەکان (C) گونجاوە، چونکە پاشماوە بەجێناهێڵێت و کارەبا ناگوازێتەوە. بەپێی EN 2، C ئاگری گازە و CO₂ بۆ ئەوان نییە."},{question:"لە ڕێکاری PASS دا، دەبێت لوولەی ئاگرکوژێنەرەوەکە بەرەو کوێ بێت؟",options:[{text:"سەری بڵێسەکە",correct:!1},{text:"بنکەی ئاگرەکە",correct:!0},{text:"دوور لە ئاگرەکە",correct:!1},{text:"بنمیچی ژوورەکە",correct:!1}],explanation:"هەمیشە لوولەکە بەرەو بنکەی ئاگرەکە ئاراستە بکە، چونکە سووتەمەنیی ئاگرەکە لەوێیە."},{question:"بۆچی ئاو ناکرێتە سەر ئاگری ڕۆن (پۆلی K)؟",options:[{text:"هیچ کارێک ناکات",correct:!1},{text:"ئاو ڕۆنی سووتاو بڵاو دەکاتەوە و بڵێسەیەکی گەورە دروست دەکات",correct:!0},{text:"ڕۆن ئاوەکە هەڵدەمژێت",correct:!1},{text:"ئاو خۆی دەسووتێت",correct:!1}],explanation:"ئاو لەسەر ڕۆنی داغ یەکسەر دەکوڵێت و ڕۆنی سووتاو فڕێ دەداتە ناو هەوا، و تۆپێکی ئاگرینی گەورە (Fireball) دروست دەبێت. ئاگرکوژێنەرەوەی Wet Chemical یان سەرپۆشێک بەکاربهێنە و گەرماکە ببڕە."}]},{id:5,code:"AID-105",icon:"HeartPulse",accent:"#db2777",title:"فریاکەوتنی سەرەتایی و CPR",subtitle:"First Aid & CPR — Complete Training",summary:"ڕاهێنانی تەواو لەسەر فریاکەوتنی سەرەتایی، CPR و هەڵسوکەوت لە کاتی تەنگانەدا لە کارگەکاندا",blocks:[{body:"فریاکەوتنی سەرەتایی (First Aid) ئەو یارمەتییە سەرەتاییەیە کە پێش گەیشتنی تیمە پزیشکییەکان بە کەسی بریندار یان نەخۆش دەدرێت. لە کارگەکاندا مەترسیی برینداربوون زۆر بەرزە — لە بڕین و سووتانەوە تا کارەبالێدان و کەوتنەخوارەوە لە شوێنی بەرز. هەر کارمەندێک دەبێت بزانێت چۆن پەیوەندی بە ئەمبولانسەوە (١٢٢) بکات، CPR بکات، خوێنبەربوون ڕابگرێت و بریندار بپارێزێت تا ئەمبولانس دەگات. ئەم وانەیە بەپێی ڕێنماییەکانی AHA 2025 و Stop the Bleed ئامادە کراوە."},{heading:"١. پەستانی سنگ و هەناسەدان (CPR) — بە وردی",body:"CPR ڕێکارێکی ڕزگارکردنی ژیانە کاتێک دڵی مرۆڤ دەوەستێت و هەناسەدانی ئاسایی نامێنێت. بەپێی ئەم هەنگاوانە کار بکە:",points:["١. سەلامەتیی شوێن: پێش هەموو شتێک دڵنیا ببەوە کە شوێنەکە سەلامەتە (کارەبا، ئاگر یان گاز نییە)، بۆ ئەوەی تۆ نەبیتە قوربانیی دووەم.",'٢. وەڵامدانەوە: شانەکانی بریندارەکە بە هێز ڕاوەشێنە و بە دەنگی بەرز بپرسە: "باشیت؟ گوێت لێمە؟".',"٣. پەیوەندیکردن: ئەگەر وەڵامی نەدایەوە و هەناسەی نەدا یان تەنها هەناسەی نائاسایی دا، یەکسەر پەیوەندی بە ١٢٢ بکە (یان کەسێک ڕابسپێرە پەیوەندی بکات) و داوا بکە ئامێری AED بهێنرێت.","٤. پەستانی سنگ (Compressions): پاژنەی دەستێک لەسەر ناوەڕاستی سنگ دابنێ (نیوەی خوارەوەی ئێسکی سنگ) و دەستەکەی تر بخە سەری. ٣٠ پەستانی بەهێز و خێرا بدە: قووڵیی ٥-٦ سم، خێرایی ١٠٠-١٢٠ پەستان لە خولەکێکدا، و ڕێگە بدە سنگ بە تەواوی بگەڕێتەوە باری خۆی.","٥. هەناسەدان: سەری بەرەو دواوە ببە و چەناگەی بەرز بکەرەوە، لووتی بگرە و ٢ هەناسە بدە (هەر یەکەیان نزیکەی ١ چرکە، تا سنگ بەرز دەبێتەوە). ئەگەر نەتتوانی یان نەتویست هەناسە بدەیت، تەنها پەستانی سنگ بەردەوام بکە.","٦. بەردەوامی (٣٠:٢): لەسەر ٣٠ پەستان و ٢ هەناسە بەردەوام بە تا ئەمبولانس دەگات، AED ئامادە دەبێت، یان بریندارەکە دەست بە هەناسەدانی ئاسایی دەکات.","٧. بەکارهێنانی AED: هەر کە گەیشت، بیکەرەوە، پەدەکان (Pads) بە سنگی ڕووتەوە بنووسێنە و فەرمانە دەنگییەکانی ئامێرەکە جێبەجێ بکە؛ لە کاتی دانی شۆکدا دەست لە بریندارەکە مەدە."]},{heading:"٢. کۆنترۆڵکردنی خوێنبەربوون (Stop the Bleed)",body:"خوێنبەربوونی توند دەتوانێت لە ماوەیەکی کورتدا مرۆڤ بکوژێت، بۆیە پەیوەندی بە ١٢٢ بکە و بە خێرایی ئەم هەنگاوانە بنێ:",points:["پەستانی ڕاستەوخۆ: پارچە قوماشێکی پاک لەسەر برینەکە دابنێ و بە هەردوو دەست بە هێز پەستان بدە. ئەگەر قوماشەکە پڕ بوو لە خوێن، لای مەبە؛ پارچەیەکی تر بخە سەری و پەستانەکە بەردەوام بکە.","پڕکردنەوەی برین (Wound Packing): ئەگەر برینەکە قووڵ بوو (وەک لە ڕان، بنباڵ یان مل)، قوماشی پاک یان پەڕۆی برینپێچی خوێنوەستێنەر بخە ناو برینەکەوە و پڕی بکەرەوە و بە هێز پەستان بدە. ئەندامی بریندار بەرز مەکەرەوە و بە دوای خاڵەکانی پەستاندا (Pressure Points) مەگەڕێ.","تۆرنیکە (Tourniquet): ئەگەر خوێنبەربوونی دەست یان قاچ مەترسیی لەسەر ژیان هەبوو، زوو تۆرنیکە ٥-٧ سم لە سەرووی برینەکەوە (بەرەو لەش) توند ببەستە، کاتەکەی بنووسە، و هەرگیز شلی مەکەرەوە.","شتی چەقیو: ئەگەر ئاسن یان شووشە لە ناو برینەکەدا چەقیبوو، هەرگیز دەری مەهێنە! خوێنبەربوونەکە زیاد دەکات. پەستان لە دەوروبەری بدە و جێگیری بکە."]},{heading:"٣. چارەسەرکردنی سووتان",body:"سووتان لە کارگەکاندا مەترسیدارە؛ بەم شێوەیە مامەڵەی لەگەڵ بکە، و بۆ سووتانی گەورە یان سووتانی دەموچاو و دەستەکان پەیوەندی بە ١٢٢ بکە:",points:["سووتانی گەرمی: یەکسەر ئاوی فێنکی ڕەوان (نەک ئاوی سەهۆڵ) بۆ ماوەی ٢٠ خولەک بەسەر سووتانەکەدا بکە. ئەنگوستیلە و کاتژمێر زوو دابکەنە پێش ئەوەی ئەندامەکە بئاوسێت.","سووتانی کیمیایی: جلە پیسبووەکان دابکەنە و پێست بە ئاوێکی زۆری ڕەوان بۆ ماوەی ٢٠ خولەک یان زیاتر بشۆ، و پەڕەی SDS ی ماددەکە بپشکنە.","سووتانی کارەبا: یەکەم کار کارەبا ببڕە! پاشان سووتانەکە وەک سووتانی گەرمی سارد بکەرەوە و پەیوەندی بە ١٢٢ بکە، چونکە کارەبا دەتوانێت زیان بە دڵ و ناو لەش بگەیەنێت.","ئاگاداری: بڵقی سووتان مەتەقێنە، و سەهۆڵ، چەوری، هەویری ددان یان مەرهەم بەبێ ڕێنماییی پزیشکی بەکارمەهێنە."]},{heading:"٤. شکان و برینداربوونی بڕبڕەی پشت",body:"لە کاتی کەوتنەخوارەوە لە شوێنی بەرز یان گومانی شکان:",points:["جێگیرکردن (Splinting): ئەگەر گومانی شکان هەبوو، ئەندامی بریندار مەجووڵێنە. وەک خۆی، بە دارێک یان کارتۆنێک جێگیری بکە بۆ ئەوەی ئازارەکە کەم ببێتەوە.","پاراستنی پشت و مل: ئەگەر کەسێک لە شوێنێکی بەرز کەوتە خوارەوە، مەیجووڵێنە مەگەر شوێنەکە مەترسیدار بێت (وەک ئاگر)، چونکە جووڵاندن دەتوانێت ببێتە هۆی ئیفلیجبوون. سەری جێگیر ڕابگرە و پەیوەندی بە ١٢٢ بکە.","ساردکردنەوە: بۆ کەمکردنەوەی ئاوسان (Swelling)، سەهۆڵ لە پارچە قوماشێکدا بپێچە و بۆ ماوەی ٢٠ خولەک لەسەر شوێنی ئازارەکە دابنێ؛ سەهۆڵ ڕاستەوخۆ لەسەر پێست دامەنێ."]},{heading:"٥. کارەبالێدان و ڕزگارکردن",body:"کارەبا دەتوانێت دڵ بوەستێنێت؛ ئەم ڕێکارانە جێبەجێ بکە:",points:["یەکسەر کارەبا ببڕە: تا کارەبا نەبڕدرێت دەست لە بریندارەکە مەدە، چونکە کارەبا تۆش دەگرێت.","جیاکردنەوەی سەلامەت: ئەگەر نەتتوانی کارەبا ببڕیت و ڤۆڵتیە نزم بوو، بە دارێکی وشک یان پلاستیک وایەرەکە لە بریندارەکە دوور بخەرەوە و لەسەر شتێکی وشک بوەستە. لە هێڵەکانی ڤۆڵتیەی بەرز نزیک مەبەرەوە و پەیوەندی بە ١١٥ بکە.","پشکنینی پزیشکی: هەموو ئەو کەسانەی کارەبایان لێداوە، تەنانەت ئەگەر هەست بە باشی بکەن، دەبێت بچنە نەخۆشخانە بۆ پشکنینی دڵ؛ پەیوەندی بە ١٢٢ بکە."],critical:!0}],media:[{kind:"video",src:"media/videos/cpr_factory.mp4",title:"CPR و فریاکەوتنی سەرەتایی",description:"ڕاهێنانی CPR و یارمەتیدانی بریندارەکان لە کارگەکاندا"}],quiz:[{question:"لە CPR دا، دەبێت خێرایی پەستانی سنگ لە خولەکێکدا چەند بێت؟",options:[{text:"٥٠-٧٠",correct:!1},{text:"٨٠-٩٠",correct:!1},{text:"١٠٠-١٢٠",correct:!0},{text:"١٥٠+",correct:!1}],explanation:"بەپێی AHA 2025، خێرایی پەستان ١٠٠-١٢٠ پەستانە لە خولەکێکدا، بە قووڵیی ٥-٦ سم بۆ گەورەساڵان، بۆ ئەوەی خوێن بگاتە مێشک."},{question:"ئەگەر شتێکی تیژ لە ناو برینێکدا چەقیبوو، چی دەکەیت؟",options:[{text:"دەری دەهێنم",correct:!1},{text:"لە شوێنی خۆی دەیهێڵمەوە و پەیوەندی بە ١٢٢ دەکەم",correct:!0},{text:"دەستم لێی دوور دەخەمەوە و هیچ ناکەم",correct:!1},{text:"بە ئاو دەیشۆم",correct:!1}],explanation:"دەرهێنانی شتەکە خوێنبەربوونەکە زیاد دەکات. دەبێت لە شوێنی خۆی بمێنێتەوە و جێگیر بکرێت تا پزیشک لە نەخۆشخانە دەری دەهێنێت."},{question:"ئەگەر کارەبا کەسێکی گرتبوو، یەکەم کار کە دەیکەیت چییە؟",options:[{text:"دەستی دەگرم",correct:!1},{text:"CPR دەکەم",correct:!1},{text:"کارەبا دەبڕم",correct:!0},{text:"ئاوی بەسەردا دەکەم",correct:!1}],explanation:"دەبێت یەکەم جار سەرچاوەی کارەبا ببڕدرێت بۆ ئەوەی کارەبا تۆش نەگرێت؛ پاشان پەیوەندی بە ١٢٢ بکە و ئەگەر پێویست بوو دەست بە CPR بکە."}]},{id:6,code:"CHEM-106",icon:"FlaskConical",accent:"#16a34a",title:"ماددە کیمیاییەکان (SDS)",subtitle:"Chemical Safety & Labelling",summary:"مامەڵەکردن لەگەڵ ماددە کیمیاییەکان و ناسینی مەترسییەکانیان",blocks:[{body:"ماددە کیمیاییەکان لە کارگەکاندا دەتوانن ببنە هۆی سووتانی پێست، ژەهراویبوون، ئاگر یان تەقینەوە."},{heading:"١. پەڕەی SDS چییە؟",body:"پەڕەی زانیاریی سەلامەتی (Safety Data Sheet — SDS) زانیاریی هەر ماددەیەک لە ١٦ بەشدا دەدات، لەوانە:",points:["پێکهاتەی ماددەکە و مەترسییەکانی.","کام PPE پێویستە (دەمامک، دەستکێش، چاویلکە).","فریاکەوتنی سەرەتایی ئەگەر ماددەکە بەر لەش کەوت، و ڕێگاکانی کوژاندنەوەی ئاگر."]},{heading:"٢. هێماکانی GHS",body:"هەندێک لە نیشانەکانی سەر قوتوو و دەبەکان:",points:["بڵێسە (Flame): ماددەی ئاگرگر.","کەللەسەر و ئێسک (Skull and Crossbones): ماددەی ژەهراویی کوشندە.","داخوران (Corrosion): ماددەی ترش (ئەسید) یان ئەلکالی کە پێست و کانزاکان دەخوات."]}],media:[{kind:"image",src:"media/images/ghs_pictograms.png",title:"SDS",description:"نیشانەکانی مەترسیی GHS"}],quiz:[{question:"لە کوێ دەتوانین بزانین کام دەمامک بۆ ماددەیەکی کیمیایی پێویستە؟",options:[{text:"لە نیشانەکانی سەر دیوار",correct:!1},{text:"لە پەڕەی SDS دا",correct:!0},{text:"لە هاوڕێکەت بپرسە",correct:!1},{text:"پێویستی بە دەمامک نییە",correct:!1}],explanation:"پەڕەی SDS هەموو زانیارییەکانی پاراستنی تایبەت بەو ماددەیە دەدات، لەوانە جۆری PPE ی پێویست (بەشی ٨)."},{question:"هێمای کەللەسەر و ئێسک (Skull and Crossbones) لەسەر قوتوویەک واتای چییە؟",options:[{text:"ماددەیەکی ئاگرگر کە بە ئاسانی ئاگر دەگرێت",correct:!1},{text:"ماددەیەکی ژەهراویی کوشندە",correct:!0},{text:"ماددەیەکی ترش یان ئەلکالی کە پێست و کانزاکان دەخوات",correct:!1},{text:"ماددەیەک کە تەنها زیان بە ژینگە دەگەیەنێت",correct:!1}],explanation:"کەللەسەر و ئێسک نیشانەی ماددەی ژەهراویی کوشندەیە؛ بڵێسە (Flame) نیشانەی ماددەی ئاگرگرە، و داخوران (Corrosion) نیشانەی ماددەی ترش (ئەسید) یان ئەلکالییە."},{question:"جگە لە مەترسییەکان و PPE ی پێویست، پەڕەی SDS چ زانیارییەکی تر دەدات؟",options:[{text:"نرخی ماددەکە و ناوی فرۆشیارەکەی",correct:!1},{text:"کاتەکانی پاککردنەوەی کۆگای ماددە کیمیاییەکان",correct:!1},{text:"ناوی ئەو کرێکارانەی دەتوانن بەکاری بهێنن",correct:!1},{text:"فریاکەوتنی سەرەتایی و ڕێگاکانی کوژاندنەوەی ئاگر",correct:!0}],explanation:"پەڕەی SDS زانیاریی هەر ماددەیەک لە ١٦ بەشدا دەدات، لەوانە: مەترسییەکان، PPE ی پێویست، فریاکەوتنی سەرەتایی ئەگەر ماددەکە بەر لەش کەوت، و ڕێگاکانی کوژاندنەوەی ئاگر."}]},{id:7,code:"HGHT-107",icon:"Construction",accent:"#0284c7",title:"کارکردن لە شوێنی بەرز",subtitle:"Fall Protection & Ladders",summary:"ڕێگرتن لە کەوتنەخوارەوە لە داربەست، بان و پەیژە",blocks:[{body:"کەوتنەخوارەوە لە شوێنی بەرز یەکێکە لە هۆکارە سەرەکییەکانی مردن لە کارگە و شوێنەکانی بیناسازیدا."},{heading:"١. پاراستن دژی کەوتنەخوارەوە",body:"هەر کارێک لە بەرزیدا (OSHA: لە ١٫٢ مەترەوە لە کارگەکاندا و لە ١٫٨ مەترەوە لە بیناسازیدا) پێویستی بەم شتانە هەیە:",points:["هارنەس (Full Body Harness): بە دروستی و توندی لەبەرکردنی.","پەتی سەلامەتی (Lanyard): دەبێت بە خاڵێکی بەستنەوەی پتەوەوە (Anchor Point) بەسترابێت.","ڕێلی پاراستن (Guardrails): لە دەوروبەری داربەست، بان و لێوارە کراوەکاندا."]},{heading:"٢. سەلامەتیی پەیژە (Ladders)",body:"یاسای ٣ خاڵی پەیوەندی:",points:["هەمیشە دەبێت ٣ ئەندامی لەش (دوو پێ و دەستێک، یان دوو دەست و پێیەک) لەسەر پەیژەکە بن.","گۆشەی دانانی پەیژە دەبێت ٤:١ بێت (بۆ هەر ٤ مەتر بەرزی، بنی پەیژەکە مەترێک لە دیوارەکە دوور بێت)."]}],media:[{kind:"video",src:"media/videos/fall_protection.mp4",title:"کارکردن لە بەرزیدا",description:"بەکارهێنانی هارنەس"}],quiz:[{question:"یاسای ٣ خاڵ لەسەر پەیژە واتای چییە؟",options:[{text:"٣ کەس پێکەوە لەسەری بن",correct:!1},{text:"٣ خولەک لەسەری بمێنەوە",correct:!1},{text:"هەمیشە ٣ ئەندامی لەش بە پەیژەکەوە بن",correct:!0},{text:"پەیژەکە بە ٣ پەت ببەستەوە",correct:!1}],explanation:"یاسای ٣ خاڵ بۆ ئەوەیە کە کرێکار هاوسەنگیی خۆی لەدەست نەدات و نەکەوێتە خوارەوە."},{question:"پەیژەیەک ٤ مەتر بەسەر دیوارێکدا بەرز دەبێتەوە. دەبێت بنەکەی چەند لە دیوارەکە دوور بێت؟",options:[{text:"نیو مەتر",correct:!1},{text:"١ مەتر",correct:!0},{text:"٢ مەتر",correct:!1},{text:"٤ مەتر",correct:!1}],explanation:"گۆشەی دانانی پەیژە دەبێت ٤:١ بێت: بۆ هەر ٤ مەتر بەرزی، بنی پەیژەکە مەترێک لە دیوارەکە دوور بێت."},{question:"پەتی سەلامەتی (Lanyard)ی هارنەس دەبێت بە چییەوە ببەسترێت؟",options:[{text:"بە پشتێنی ئامرازەکانی خودی کرێکارەکەوە",correct:!1},{text:"بەو پەیژەیەوە کە کرێکارەکە لەسەری وەستاوە",correct:!1},{text:"بە خاڵێکی بەستنەوەی پتەوەوە (Anchor Point)",correct:!0},{text:"بە هەر بۆری یان کێبڵێکی نزیکەوە",correct:!1}],explanation:"پەتی سەلامەتی دەبێت بە خاڵێکی بەستنەوەی پتەوەوە (Anchor Point) بەسترابێت، و هارنەس دەبێت بە دروستی و توندی لەبەر بکرێت."}]},{id:8,code:"CONF-108",icon:"Container",accent:"#9333ea",title:"شوێنە تەسک و داخراوەکان",subtitle:"Confined Space Safety",summary:"کارکردن لە ناو تانکی، بۆری و مەنهۆڵەکاندا",blocks:[{body:"شوێنە داخراوەکان مەترسیدارن چونکە هەوا تێیاندا ناگۆڕدرێت، ئۆکسجین دەتوانێت کەم ببێتەوە و گازە کوشندەکان تێیاندا کۆ دەبنەوە."},{heading:"١. مەترسییە سەرەکییەکان",body:"پێش ئەوەی بچیتە ژوورەوە، بزانە:",points:["کەمیی ئۆکسجین (کەمتر لە ١٩٫٥٪): دەبێتە هۆی خنکان.","گازە ژەهراوییەکانی وەک CO (بێ بۆن) و H₂S (کە لە چڕیی بەرزدا هەستی بۆنکردن پەک دەخات).","مەترسیی ئاگر و تەقینەوە ئەگەر گاز یان هەڵمی ئاگرگر هەبێت."]},{heading:"٢. ڕێکارەکانی چوونە ژوورەوە",body:"دەبێت ئەم مەرجانە هەبن:",points:["پشکنینی هەوا بە ئامێری پێوانی گاز (Gas Monitor) پێش چوونە ژوورەوە و لە کاتی کاردا.","بوونی چاودێرێک (Attendant) کە لە دەرەوە بمێنێتەوە، چاوی لەسەر کرێکاری ناوەوە بێت، و بە هیچ شێوەیەک نەچێتە ژوورەوە.","مۆڵەتی کار (Permit)، ئامرازەکانی پەیوەندی و پلانی ڕزگارکردن دەبێت ئامادە بن."]}],media:[{kind:"image",src:"media/images/confined_entry.png",title:"شوێنە داخراوەکان",description:"پشکنینی هەوا"}],quiz:[{question:"ئایا دروستە چاودێری دەرەوە بەبێ ئامێر بچێتە ژوورەوە بۆ ڕزگارکردنی هاوڕێکەی؟",options:[{text:"بەڵێ، لەبەر مرۆڤایەتی",correct:!1},{text:"نەخێر، چونکە ئەویش دەخنکێت",correct:!0},{text:"بەڵێ، ئەگەر هەناسەی خۆی ڕابگرێت",correct:!1},{text:"هیچ کامیان نییە",correct:!1,fixed:!0}],explanation:"بەپێی لێکۆڵینەوەکانی NIOSH، بەشێکی گەورە لە مردنەکانی شوێنە داخراوەکان ئەو کەسانەن کە بەبێ ئامێر و ڕاهێنان چوونەتە ژوورەوە بۆ ڕزگارکردن. چاودێر دەبێت پەیوەندی بە تیمی ڕزگارکردن و ١١٥ ەوە بکات."},{question:"کەی دەبێت هەوای شوێنی داخراو بە ئامێری پێوانی گاز (Gas Monitor) بپشکنرێت؟",options:[{text:"تەنها یەک جار، لە یەکەم ڕۆژی کارەکەدا",correct:!1},{text:"تەنها ئەگەر کەسێک بۆنی شتێکی نائاسایی کرد",correct:!1},{text:"دوای تەواوبوونی کارەکە",correct:!1},{text:"پێش چوونە ژوورەوە و لە کاتی کاردا",correct:!0}],explanation:"پشکنینی هەوا پێش چوونە ژوورەوە و لە کاتی کاردا دەکرێت، چونکە ئۆکسجین دەتوانێت کەم ببێتەوە و گازە کوشندەکان کۆ ببنەوە؛ CO بێ بۆنە، بۆیە بۆنکردن پشکنین نییە."},{question:"لە ناو تانکییەکدا، کرێکارێک لەناکاو بۆنی H₂S ناکات. ئەمە دەتوانێت مانای چی بێت؟",options:[{text:"گازەکە ڕۆیشتووە و هەوا بۆ هەناسەدان سەلامەتە",correct:!1},{text:"گازەکە هەستی بۆنکردنی پەک خستبێت",correct:!0},{text:"پانکەی هەواگۆڕین بە دروستی کار دەکات",correct:!1},{text:"گازەکە بووەتە هەڵمی ئاوی بێ زیان",correct:!1}],explanation:"H₂S لە چڕیی بەرزدا هەستی بۆنکردن پەک دەخات، بۆیە بۆن نەکردن مانای ئەوە نییە کە گازەکە ڕۆیشتووە؛ تەنها ئامێری پێوانی گاز (Gas Monitor) پیشان دەدات کە هەوا سەلامەتە یان نا."}]},{id:9,code:"NOIS-109",icon:"Ear",accent:"#db2777",title:"دەنگ و پاراستنی گوێ",subtitle:"Hearing Conservation",summary:"پاراستن دژی ژاوەژاوی ئامێرە گەورەکان",blocks:[{body:"کەڕبوون یان کەمبوونەوەی بیستن بەهۆی دەنگی کارگەکانەوە هێواش هێواش ڕوودەدات و چارەسەر نابێت."},{heading:"١. ئاستەکانی دەنگ",body:"کەی دەنگ دەبێتە مەترسی؟",points:["٨٥ dB(A): سنووری دەستپێکردنی مەترسی بۆ ٨ کاتژمێری کار.","١٠٠ dB(A): بەبێ پاراستن تەنها بۆ ١٥ خولەک لە ڕۆژێکدا سەلامەتە (NIOSH).","نیشانە: ئەگەر دوای کار هەستت بە زرنگانەوە (Tinnitus) لە گوێکانتدا کرد، دەنگەکە زۆر بەرز بووە."]},{heading:"٢. کەرەستەکانی پاراستن",body:"کەرەستەکانی پاراستنی گوێ (Hearing Protection Devices — HPD):",points:["پارێزەری ناو گوێ (Earplugs): ئەگەر بە دروستی دابنرێن، پاراستنێکی باش دەدەن.","پارێزەری سەر گوێ (Earmuffs): بە ئاسانی لەبەر دەکرێن و بۆ دەنگی بەرز گونجاون.","بەکارهێنانی هەردووکیان پێکەوە لە شوێنە زۆر بەدەنگەکاندا."]}],media:[{kind:"video",src:"media/videos/hearing_protection.mp4",title:"دەنگ",description:"چۆن پارێزەری گوێ بەکاردەهێنیت؟"}],quiz:[{question:"ئەگەر دەنگ گەیشتە ١٠٠ dB(A)، بەپێی NIOSH چەند کات دەتوانیت بەبێ پارێزەری گوێ بمێنیتەوە؟",options:[{text:"١ کاتژمێر",correct:!1},{text:"١٥ خولەک",correct:!0},{text:"٤ کاتژمێر",correct:!1},{text:"هەموو ڕۆژەکە",correct:!1}],explanation:"بەپێی NIOSH، هەر ٣ dB زیادبوون کاتی سەلامەت دەکاتە نیوە: ٨٥ dB(A) بۆ ٨ کاتژمێر، و ١٠٠ dB(A) تەنها بۆ ١٥ خولەک."},{question:"دوای کار، هەستت بە زرنگانەوە (Tinnitus) لە گوێکانتدا کرد. ئەمە مانای چییە؟",options:[{text:"گوێکانت لەسەر دەنگ ڕاهاتوون",correct:!1},{text:"دەنگەکە زۆر بەرز بووە",correct:!0},{text:"پارێزەری ناو گوێکەت زۆر تەسک بووە",correct:!1},{text:"ئاساییە و هیچ مانایەکی نییە",correct:!1}],explanation:"زرنگانەوەی گوێ دوای کار نیشانەیە کە دەنگەکە زۆر بەرز بووە؛ کەمبوونەوەی بیستن هێواش هێواش ڕوودەدات و چارەسەر نابێت، بۆیە پارێزەری گوێ بەکاربهێنە."},{question:"لە شوێنە زۆر بەدەنگەکاندا، پاراستنی گوێ دەبێت چۆن بێت؟",options:[{text:"لۆکە لە جیاتی پارێزەری گوێ",correct:!1},{text:"بەبێ پاراستن، بەڵام بە پشووی کورت",correct:!1},{text:"پارێزەری ناو گوێ و سەر گوێ پێکەوە",correct:!0},{text:"دانانی دەست لەسەر گوێ کاتێک دەنگ بەرز دەبێت",correct:!1}],explanation:"لە شوێنە زۆر بەدەنگەکاندا هەردووکیان پێکەوە بەکاربهێنە: پارێزەری ناو گوێ ئەگەر بە دروستی دابنرێت پاراستنێکی باش دەدات، و پارێزەری سەر گوێ بە ئاسانی لەبەر دەکرێت و بۆ دەنگی بەرز گونجاوە."}]},{id:10,code:"ERGO-110",icon:"Package",accent:"#0d9488",title:"هەڵگرتنی بار (Ergonomics)",subtitle:"Safe Lifting Techniques",summary:"ڕێگرتن لە ئازاری پشت و ماسولکەکان",blocks:[{body:"برینداربوونی پشت یەکێکە لە بڵاوترین برینەکان لە کارگەکاندا، بەهۆی هەڵگرتنی هەڵەی بارەوە."},{heading:"١. ڕێگای دروستی هەڵگرتن",body:"جێبەجێکردنی ئەم هەنگاوانە پشت دەپارێزێت:",points:["ئەژنۆکانت بچەمێنەوە: هێزی قاچەکانت بەکاربهێنە، نەک هی پشت.","بارەکە لە لەشت نزیک بکەرەوە: هەتا بارەکە لێت دوورتر بێت، پەستان لەسەر پشت زیاتر دەبێت.","پشتت ڕاست ڕابگرە: کاتێک شتێکی قورس هەڵدەگریت، پشتت مەچەمێنەوە.","لەشت با مەدە: ئەگەر ویستت بارەکە بەرەو لایەک ببەیت، بە پێکانت هەموو لەشت بسووڕێنە."]}],media:[{kind:"image",src:"media/images/safe_lifting.png",title:"هەڵگرتنی بار",description:"شێوازی دروست"}],quiz:[{question:"لە کاتی هەڵگرتنی شتێکی قورسدا، دەبێت هێز لەسەر چی بێت؟",options:[{text:"پشت",correct:!1},{text:"ماسولکەکانی قاچ",correct:!0},{text:"شان",correct:!1},{text:"تەنها دەست",correct:!1}],explanation:"ماسولکەکانی قاچ بەهێزترن و پشت لە برینداربوون دەپارێزن."},{question:"لە کاتی هەڵگرتنی بارێکی قورسدا، دەبێت بارەکە لە کوێ بێت؟",options:[{text:"بە درێژایی باسک، دوور لە لەشت",correct:!1},{text:"لە سەرووی سەرتەوە",correct:!1},{text:"لە لایەکی لەشتەوە",correct:!1},{text:"نزیک لە لەشت",correct:!0}],explanation:"بارەکە لە لەشت نزیک بکەرەوە: هەتا بارەکە لێت دوورتر بێت، پەستان لەسەر پشت زیاتر دەبێت."},{question:"پێویستە بارەکە بەرەو لایەک ببەیت. چۆن دەسووڕێیتەوە؟",options:[{text:"لەشم با دەدەم و پێکانم لە جێی خۆیان دەهێڵمەوە",correct:!1},{text:"بە پێکانم هەموو لەشم دەسووڕێنم",correct:!0},{text:"پشتم بەرەو شوێنە نوێیەکە دەچەمێنمەوە",correct:!1},{text:"بارەکە بە خێرایی فڕێ دەدەمە لای تر بۆ ئەوەی هێزی کەمتر بەکاربهێنم",correct:!1}],explanation:"لەشت با مەدە: ئەگەر ویستت بارەکە بەرەو لایەک ببەیت، بە پێکانت هەموو لەشت بسووڕێنە و پشتت ڕاست ڕابگرە."}]},{id:11,code:"GAS-111",icon:"Wind",accent:"#0891b2",title:"گاز و هەواگۆڕین",subtitle:"Ventilation & Toxic Gases",summary:"کۆنترۆڵکردنی هەوا و گازە ژەهراوییەکان",blocks:[{body:"هەواگۆڕینی دروست لە کارگەدا گرنگە بۆ ڕێگرتن لە کۆبوونەوەی تۆز و ئەو گازانەی دەبنە هۆی نەخۆشییەکانی هەناسە."},{heading:"١. مۆنۆکسیدی کاربۆن (CO)",body:"گازی کوشندەی بێدەنگ:",points:["بێ ڕەنگ و بێ بۆنە.","لە سووتانی سووتەمەنی و بزوێنەرەکانی بەنزین و دیزڵەوە (وەک مۆلیدە و فۆرکلیفت) دروست دەبێت.","نیشانەکان: سەرئێشە، سەرگێژخواردن، دڵتێکهەڵهاتن و بێهۆشبوون. ئەگەر هەستت بەم نیشانانە کرد، یەکسەر بچۆ دەرەوە و پەیوەندی بە ١٢٢ بکە."]},{heading:"٢. جۆرەکانی هەواگۆڕین",body:"هەوا چۆن دەگۆڕدرێت؟",points:["هەواگۆڕینی سروشتی: دەرگا و پەنجەرە کراوەکان.","هەواگۆڕینی دەستکرد: پانکە و سیستەمەکانی ڕاکێشانی هەوا (Local Exhaust).","پاراستنی کەسی: دەمامکی فلتەردار بەپێی SDS؛ بەڵام دەمامکی فلتەری دژی CO و کەمیی ئۆکسجین ناپارێزێت."]}],media:[{kind:"video",src:"media/videos/ventilation_safety.mp4",title:"گاز",description:"گازی CO"}],quiz:[{question:"بۆچی گازی CO مەترسیدارە؟",options:[{text:"چونکە بۆنەکەی ناخۆشە",correct:!1},{text:"چونکە نابینرێت و بۆنی ناکرێت",correct:!0},{text:"چونکە ڕەنگەکەی سوورە",correct:!1},{text:"چونکە تەنها بە شەو دروست دەبێت",correct:!1}],explanation:"لەبەر ئەوەی هەستی پێ ناکرێت، کرێکاران بێ ئەوەی بزانن ژەهراوی دەبن. ئامێری دۆزینەوەی CO (CO Detector) لەو شوێنانە دابنێ کە بزوێنەریان تێدا کار دەکات."},{question:"لە کاتی کار لە نزیک مۆلیدەیەک کە کار دەکات، تووشی سەرئێشە، سەرگێژخواردن و دڵتێکهەڵهاتن دەبیت. چی دەکەیت؟",options:[{text:"حەبێکی ئازارشکێن دەخۆم و کارەکەم بەردەوام دەکەم",correct:!1},{text:"لە نزیک مۆلیدەکە دادەنیشم و پشوو دەدەم",correct:!1},{text:"دەمامکێکی فلتەردار لەبەر دەکەم و دەمێنمەوە",correct:!1},{text:"یەکسەر دەچمە دەرەوە و پەیوەندی بە ١٢٢ دەکەم",correct:!0}],explanation:"سەرئێشە، سەرگێژخواردن و دڵتێکهەڵهاتن دەتوانن نیشانەی ژەهراویبوون بە CO بن؛ یەکسەر بچۆ دەرەوە و پەیوەندی بە ١٢٢ بکە، چونکە CO نابینرێت و بۆنی ناکرێت."},{question:"ئایا دەمامکی فلتەردار کرێکار لە گازی CO دەپارێزێت؟",options:[{text:"نەخێر، دژی CO ناپارێزێت",correct:!0},{text:"بەڵێ، هەر دەمامکێکی فلتەردار CO ڕادەگرێت",correct:!1},{text:"بەڵێ، ئەگەر کەمتر لە کاتژمێرێک لەبەر بکرێت",correct:!1},{text:"تەنها ئەگەر فلتەرەکە هەموو ڕۆژێک بگۆڕدرێت",correct:!1}],explanation:"دەمامکی فلتەردار بەپێی SDS هەڵدەبژێردرێت، بەڵام دژی CO و کەمیی ئۆکسجین ناپارێزێت؛ لەو شوێنانەی بزوێنەریان تێدا کار دەکات، هەواگۆڕین و ئامێری دۆزینەوەی CO پێویستن."}]},{id:12,code:"EVAC-112",icon:"Megaphone",accent:"#dc2626",title:"دەرچوونی بەپەلە (Evacuation)",subtitle:"Emergency Assembly Points",summary:"پلانی چوونە دەرەوە لە کاتی ئاگر یان کارەساتدا",blocks:[{body:"زانینی ڕێگای دەرچوون دەتوانێت جیاوازی لە نێوان ژیان و مردندا دروست بکات."},{heading:"١. یاساکانی دەرچوون",body:"کاتێک زەنگی مەترسی لێدەدات:",points:["بە هێمنی و خێرایی بڕۆ، ڕامەکە و ئاسانسۆر بەکارمەهێنە.","دەرگاکان لە دوای خۆتەوە دابخە بۆ ئەوەی ئاگر و دووکەڵ بڵاو نەبنەوە، بەڵام قوفڵیان مەکە.","بەرەو خاڵی کۆبوونەوە (Assembly Point) بڕۆ بۆ ئەوەی کارمەندان بژمێردرێن.","بە هیچ شێوەیەک مەگەڕێوە ژوورەوە تا بەرپرسی سەلامەتی یان تیمەکانی ١١٥ ڕێگە نەدەن."]}],media:[{kind:"video",src:"media/videos/evacuation_drill.mp4",title:"مەشقی دەرچوون",description:"ڕاهێنان لەسەر دەرچوون"}],quiz:[{question:"کاتێک زەنگی مەترسی لێدەدات، چی دەکەیت؟",options:[{text:"کۆکردنەوەی کەلوپەلەکانم",correct:!1},{text:"بە هێمنی بەرەو دەرچوون ڕۆیشتن",correct:!0},{text:"خۆشاردنەوە لە ژێر مێز",correct:!1},{text:"هاوارکردن",correct:!1}],explanation:"دەرچوونی هێمن و خێرا باشترین ڕێکارە بۆ پاراستنی ژیان."},{question:"لە کاتی دەرچووندا، چی لە دەرگاکان دەکەیت؟",options:[{text:"قوفڵیان دەکەم بۆ ئەوەی کەس نەگەڕێتەوە ژوورەوە",correct:!1},{text:"بە تەواوی کراوەیان دەهێڵم بۆ ئەوەی دووکەڵ دەربچێت",correct:!1},{text:"لە دوای خۆمەوە دایان دەخەم، بەڵام قوفڵیان ناکەم",correct:!0},{text:"بە شتێک کراوەیان ڕادەگرم بۆ ئەو تیمانەی دواتر دەگەن",correct:!1}],explanation:"دەرگاکان لە دوای خۆتەوە دابخە بۆ ئەوەی ئاگر و دووکەڵ بڵاو نەبنەوە، بەڵام قوفڵیان مەکە."},{question:"تۆ لە خاڵی کۆبوونەوەیت. کەی دەتوانیت بگەڕێیتەوە ژوورەوە؟",options:[{text:"هەر کە زەنگی مەترسی لە بیناکەدا وەستا",correct:!1},{text:"کاتێک بەرپرسی سەلامەتی یان تیمەکانی ١١٥ ڕێگە دەدەن",correct:!0},{text:"کاتێک هیچ دووکەڵێک لە پەنجەرەکانەوە دەرنەچێت",correct:!1},{text:"دوای ١٠ خولەک، ئەگەر هیچ ئاگرێک دیار نەبێت",correct:!1}],explanation:"بە هیچ شێوەیەک مەگەڕێوە ژوورەوە تا بەرپرسی سەلامەتی یان تیمەکانی ١١٥ ڕێگە نەدەن؛ لە خاڵی کۆبوونەوەدا کارمەندانیش دەژمێردرێن."}]},{id:13,code:"WELD-113",icon:"Sparkles",accent:"#2563eb",title:"سەلامەتیی لەحیمکردن",subtitle:"Welding & Cutting Hazards",summary:"پاراستن لە تیشک، گەرما و دووکەڵی لەحیمکردن",blocks:[{body:"کاری لەحیمکردن مەترسیی تیشکی سەروو وەنەوشەیی (UV)، سووتانی سەخت، و گاز و دووکەڵی ژەهراویی تێدایە."},{heading:"١. پاراستنی چاو و پێست",body:"پێداویستییەکانی لەحیمکاران:",points:["کڵاوی پاراستنی لەحیمکردن (Welding Helmet) بە فلتەری گونجاو: بۆ پاراستنی چاو لە تیشکی UV و ڕووناکیی توندی کەوانەی لەحیمکردن (Arc).","دەستکێشی چەرمی درێژ: بۆ پاراستن لە گەرما و پڕیشک.","پێشبەندی چەرمی (Apron): بۆ پاراستنی لەش."]},{heading:"٢. مەترسیی ئاگر (Hot Work)",body:"پێش دەستپێکردن مۆڵەتی کاری گەرم (Hot Work Permit) وەربگرە و:",points:["دەوروبەری شوێنی کار لە ماددە ئاگرگرەکان پاک بکەرەوە (NFPA 51B: بە دووریی ١١ مەتر / ٣٥ پێ)، یان بە پەردەی بەرگر دایانبپۆشە.","ئاگرکوژێنەرەوەیەکی گونجاو لە نزیک خۆت ئامادە بکە.","چاودێری ئاگر (Fire Watch): لە کاتی کاردا و لانیکەم ١ کاتژمێر دوای تەواوبوونی کار لە شوێنەکە دەمێنێتەوە؛ پاشان شوێنەکە تا ٣ کاتژمێری تر چاودێری دەکرێت، بەپێی بڕیاری بەرپرسی مۆڵەتەکە (NFPA 51B)."]}],media:[{kind:"image",src:"media/images/welding_safety.png",title:"لەحیمکردن",description:"لەبەرکردنی دروست"}],quiz:[{question:"بۆچی دوای لەحیمکردن چاودێری ئاگر لانیکەم ١ کاتژمێر لە شوێنەکە دەمێنێتەوە؟",options:[{text:"بۆ پاککردنەوە",correct:!1},{text:"بۆ ئەوەی ئاگرێکی شاراوە دروست نەبێت",correct:!0},{text:"بۆ ساردکردنەوەی ئاسنەکە",correct:!1},{text:"هیچ پێویست نییە",correct:!1}],explanation:"زۆر جار پڕیشک دەکەونە ناو درز و کەرەستەکانەوە و دوای ماوەیەک ئاگر دروست دەکەن. بەپێی NFPA 51B (چاپی ٢٠١٩ و دواتر)، چاودێری لانیکەم ١ کاتژمێر دوای کار بەردەوام دەبێت."},{question:"پێش دەستپێکردنی کاری گەرم (Hot Work)، دەبێت چی بە ماددە ئاگرگرەکانی دەوروبەری شوێنی کار بکرێت؟",options:[{text:"لە شوێنی خۆیان بمێنن، چونکە چاودێری ئاگر لەوێ دەبێت",correct:!1},{text:"لاببرێن یان بە پەردەی بەرگر دابپۆشرێن",correct:!0},{text:"یەک جار ئاویان پێدا بکرێت و یەکسەر لەحیمکردن دەست پێ بکات",correct:!1},{text:"لە پشت لەحیمکارەکەوە دابنرێن، دوور لە پڕیشکی ڕاستەوخۆ",correct:!1}],explanation:"پێش دەستپێکردن مۆڵەتی کاری گەرم (Hot Work Permit) وەربگرە و دەوروبەری شوێنی کار لە ماددە ئاگرگرەکان پاک بکەرەوە (NFPA 51B: بە دووریی ١١ مەتر / ٣٥ پێ)، یان بە پەردەی بەرگر دایانبپۆشە."},{question:"چی چاوی لەحیمکار لە تیشکی UV و ڕووناکیی توندی کەوانەی لەحیمکردن دەپارێزێت؟",options:[{text:"چاویلکەی سەلامەتیی ئاسایی، وەک ئەوەی بۆ تۆز",correct:!1},{text:"چاویلکەی ڕەشی خۆر لە ژێر کڵاوی پاراستن",correct:!1},{text:"کڵاوی پاراستنی لەحیمکردن بە فلتەری گونجاو",correct:!0},{text:"سەیرکردنی کەوانەکە تەنها بۆ چەند چرکەیەک",correct:!1}],explanation:"کڵاوی پاراستنی لەحیمکردن (Welding Helmet) بە فلتەری گونجاو چاو لە تیشکی UV و ڕووناکیی توندی کەوانەی لەحیمکردن دەپارێزێت؛ دەستکێشی چەرمی درێژ و پێشبەندی چەرمی دەست و لەش دەپارێزن."}]},{id:14,code:"FORK-114",icon:"Forklift",accent:"#475569",title:"ئامێرەکانی گواستنەوە",subtitle:"Forklift & Vehicle Safety",summary:"سەلامەتیی فۆرکلیفت و لێخوڕین لە کارگەدا",blocks:[{body:"فۆرکلیفت ئامێرێکی قورسە و مەترسیی پلیشاندنەوە و وەرگەڕانی هەیە ئەگەر بە دروستی لێنەخوڕدرێت."},{heading:"١. یاساکانی لێخوڕین",body:"بۆ شۆفێرانی فۆرکلیفت:",points:["تەنها کەسانی ڕاهێنراو و مۆڵەتدار دەتوانن فۆرکلیفت لێبخوڕن (OSHA 1910.178).","هەرگیز کەس لەسەر چنگاڵەکانی (Forks) فۆرکلیفت یان لە تەنیشت خۆت هەڵمەگرە.","بار لە توانای ئامێرەکە زیاتر مەکە بۆ ئەوەی وەرنەگەڕێت، و پشتێنی سەلامەتی ببەستە.","لە هەر سووچێک یان دەرگایەکدا خێرایی کەم بکەرەوە و هۆڕن (Horn) لێبدە."]},{heading:"٢. سەلامەتیی پیادەکان",body:"ئەگەر لە نزیک فۆرکلیفتەوە دەڕۆیت:",points:["چاوت لە شۆفێرەکە بێت (Eye Contact) و دوورییەکی سەلامەت بهێڵەوە.","لە ڕاڕەوە دیاریکراوەکانی پیادەدا بڕۆ."]}],media:[{kind:"video",src:"media/videos/forklift_safety.mp4",title:"فۆرکلیفت",description:"ناسینی خاڵە نادیارەکان (Blind Spots)"}],quiz:[{question:"ئەگەر شۆفێری فۆرکلیفت بارێکی بەرزی هەبێت و پێشی خۆی نەبینێت، چی دەکات؟",options:[{text:"بە خێرایی لێدەخوڕێت",correct:!1},{text:"بە پاشەوە (Reverse) لێدەخوڕێت",correct:!0},{text:"هۆڕن لێدەدات و چاوەکانی دەنووقێنێت",correct:!1},{text:"هیچ کامیان نییە",correct:!1,fixed:!0}],explanation:"کاتێک بار ڕێگری لە بینینی شۆفێر دەکات، دەبێت بە پاشەوە لێبخوڕێت بۆ ئەوەی ڕێگاکەی ببینێت (OSHA 1910.178)."},{question:"هاوڕێیەکت داوا دەکات لەسەر چنگاڵەکانی (Forks) فۆرکلیفتەکەت سوار ببێت. چی دەکەیت؟",options:[{text:"ڕێگەی دەدەم سوار ببێت ئەگەر بە هێواشی لێبخوڕم",correct:!1},{text:"ڕێگەی دەدەم لەسەر چنگاڵەکان بوەستێت و خۆی بە فۆرکلیفتەکەوە بگرێت",correct:!1},{text:"ڕێگەی دەدەم لە تەنیشتمەوە دابنیشێت لە جیاتی چنگاڵەکان",correct:!1},{text:"ڕەتی دەکەمەوە، چونکە نابێت کەس لەسەر چنگاڵەکان سوار ببێت",correct:!0}],explanation:"هەرگیز کەس لەسەر چنگاڵەکانی فۆرکلیفت یان لە تەنیشت خۆت هەڵمەگرە؛ فۆرکلیفت ئامێرێکی قورسە و مەترسیی پلیشاندنەوە و وەرگەڕانی هەیە."},{question:"تۆ لە نزیک فۆرکلیفتێکی جووڵاوەوە دەڕۆیت. دەبێت چی بکەیت؟",options:[{text:"چاوت لە شۆفێرەکە بێت و دوورییەکی سەلامەت بهێڵیتەوە",correct:!0},{text:"لە نزیکییەوە بڕۆیت بۆ ئەوەی شۆفێرەکە باشتر بتبینێت",correct:!1},{text:"بە خێرایی بە پێشیدا بپەڕیتەوە پێش ئەوەی بگاتە تۆ",correct:!1},{text:"دەست ڕابوەشێنیت و بەردەوام بیت، چونکە شۆفێر دەبێت بوەستێت",correct:!1}],explanation:"لە نزیک فۆرکلیفت، چاوت لە شۆفێرەکە بێت (Eye Contact)، دوورییەکی سەلامەت بهێڵەوە و لە ڕاڕەوە دیاریکراوەکانی پیادەدا بڕۆ؛ لەوانەیە شۆفێر لە خاڵە نادیارەکاندا (Blind Spots) نەتبینێت."}]},{id:15,code:"SIGN-115",icon:"AlertTriangle",accent:"#ea580c",title:"نیشانەکانی سەلامەتی",subtitle:"Safety Signs & Symbols",summary:"ناسینی ڕەنگ و هێماکانی سەلامەتی (ISO 7010)",blocks:[{body:"نیشانەکانی سەلامەتی بە زمانێکی جیهانی ئاگادارمان دەکەنەوە لە مەترسییەکان."},{heading:"١. واتای ڕەنگەکان (ISO 7010)",body:"هەر ڕەنگێک پەیامێکی تایبەت دەگەیەنێت:",points:["سوور: قەدەغەکردن یان ئامێرەکانی ئاگرکوژاندنەوە (نموونە: جگەرەکێشان قەدەغەیە).","زەرد: ئاگاداری و مەترسی (نموونە: مەترسیی کارەبا).","شین: ناچاری (نموونە: دەبێت کڵاوی پاراستن لەبەر بکەیت).","سەوز: سەلامەتی و دەرچوون (نموونە: دەرگای دەرچوون)."]}],media:[{kind:"image",src:"media/images/safety_signs.png",title:"نیشانەکانی سەلامەتی",description:"هێما ستانداردەکان"}],quiz:[{question:"نیشانەیەکی ڕەنگ زەرد واتای چییە؟",options:[{text:"قەدەغەکردن",correct:!1},{text:"ئاگاداری و مەترسی",correct:!0},{text:"شوێنی سەلامەت",correct:!1},{text:"بەکارهێنانی ئاو",correct:!1}],explanation:'ڕەنگی زەرد هەمیشە واتای "ئاگادار بە" یان "مەترسی هەیە".'},{question:"نیشانەیەکی شین لەبەردەم دەرگای کارگەکە وێنەی کڵاوی پاراستن پیشان دەدات. واتای چییە؟",options:[{text:"کڵاوی پاراستن لێرە قەدەغەیە",correct:!1},{text:"ئاگاداری: لەوانەیە شت لێرە بکەوێتە خوارەوە",correct:!1},{text:"دەبێت لێرە کڵاوی پاراستن لەبەر بکەیت",correct:!0},{text:"کڵاوی پاراستن لە پشت ئەم دەرگایەوە هەڵدەگیرێت",correct:!1}],explanation:"ڕەنگی شین واتای ناچارییە، وەک: دەبێت کڵاوی پاراستن لەبەر بکەیت؛ سوور قەدەغەکردن یان ئامێرەکانی ئاگرکوژاندنەوەیە، زەرد ئاگاداری و سەوز سەلامەتی و دەرچوون."},{question:"کام ڕەنگ بۆ سەلامەتی و دەرچوون بەکاردەهێنرێت، وەک دەرگای دەرچوون؟",options:[{text:"سوور",correct:!1},{text:"زەرد",correct:!1},{text:"شین",correct:!1},{text:"سەوز",correct:!0}],explanation:"ڕەنگی سەوز سەلامەتی و دەرچوون پیشان دەدات، وەک دەرگای دەرچوون؛ سوور بۆ قەدەغەکردن یان ئامێرەکانی ئاگرکوژاندنەوەیە."}]},{id:16,code:"HOUS-116",icon:"ClipboardCheck",accent:"#4f46e5",title:"پاکوخاوێنی (Housekeeping)",subtitle:"Order & Maintenance",summary:"ڕێکخستنی شوێنی کار بۆ کەمکردنەوەی مەترسییەکان",blocks:[{body:"شوێنی کاری پاک شوێنێکی سەلامەتە. زۆرێک لە ڕووداوەکان بەهۆی خلیسکان و پێهەڵکەوتن بە کەرەستە پەرشوبڵاوەکانەوە ڕوودەدەن."},{heading:"١. یاسا گشتییەکان",body:"بۆ هەموو کرێکاران:",points:["پاککردنەوەی ڕۆن یان ئاوی ڕژاو لە زووترین کاتدا.","کۆکردنەوەی پاشماوەکان لە سەبەتە تایبەتەکاندا.","هێشتنەوەی ڕاڕەو و دەرچوونەکان بە کراوەیی و بێ ڕێگر.","گەڕاندنەوەی هەر ئامێرێک بۆ شوێنی خۆی دوای تەواوبوونی کار."]}],media:[{kind:"image",src:"media/images/clean_factory.png",title:"پاکوخاوێنی",description:"نموونەی شوێنێکی پاک"}],quiz:[{question:"ئەگەر بینیت ڕۆن لەسەر زەوی ڕژاوە، چی دەکەیت؟",options:[{text:"جێی دەهێڵم تا پاککەرەوە دێت",correct:!1},{text:"پاکی دەکەمەوە یان نیشانەیەکی لێ دادەنێم و ئاگاداریان دەکەمەوە",correct:!0},{text:"بەسەریدا باز دەدەم",correct:!1},{text:"گوێی پێ نادەم",correct:!1}],explanation:"هەر کرێکارێک بەرپرسە لە پاکی و سەلامەتیی شوێنی کاری خۆی، بۆ ئەوەی کەس نەکەوێت."},{question:"دەبێت ڕاڕەو و دەرچوونەکان چۆن ڕابگیرێن؟",options:[{text:"کراوە و بێ ڕێگر",correct:!0},{text:"بۆ دانانی سندووق کاتێک کۆگاکە پڕ دەبێت",correct:!1},{text:"بۆ ماوەیەکی کورت لە کاتی کاردا داخراو",correct:!1},{text:"تەنها پێش سەردانی پشکنین کراوە",correct:!1}],explanation:"ڕاڕەو و دەرچوونەکان بە کراوەیی و بێ ڕێگر بهێڵەرەوە؛ زۆرێک لە ڕووداوەکان بەهۆی خلیسکان و پێهەڵکەوتن بە کەرەستە پەرشوبڵاوەکانەوە ڕوودەدەن."},{question:"کارەکەت تەواو کرد. چی لەو ئامێرانە دەکەیت کە بەکارتهێنان؟",options:[{text:"لەسەر زەوی جێیان دەهێڵم بۆ دەوامی دواتر",correct:!1},{text:"هەر ئامێرێک دەگەڕێنمەوە بۆ شوێنی خۆی",correct:!0},{text:"لەگەڵ پاشماوەکاندا دەیانخەمە ناو سەبەتەکەوە",correct:!1},{text:"لە ڕاڕەوەکەدا لە نزیک دەرچوون کۆیان دەکەمەوە",correct:!1}],explanation:"دوای تەواوبوونی کار هەر ئامێرێک بگەڕێنەوە بۆ شوێنی خۆی و پاشماوەکان لە سەبەتە تایبەتەکاندا کۆ بکەرەوە؛ کەرەستە پەرشوبڵاوەکان دەبنە هۆی خلیسکان و پێهەڵکەوتن."}]},{id:17,code:"QUAK-117",icon:"Activity",accent:"#d97706",title:"بوومەلەرزە لە کارگەکاندا",subtitle:"Earthquake Safety in Factories",summary:"سەلامەتیی کرێکاران لە کاتی بوومەلەرزە و دوای ئەو",blocks:[{body:"بوومەلەرزە لە کارگەکاندا مەترسییەکی دووقات دروست دەکات: هەم خودی لەرزینەکە، و هەم کەوتنی ئامێرە قورسەکان، ڕژانی ماددە کیمیاییەکان، شکانی بۆرییەکان و دزەکردنی گاز. دەبێت هەر کارگەیەک پلانێکی بوومەلەرزەی هەبێت."},{heading:"١. خۆت بدە بە زەویدا، خۆت بپارێزە، خۆت بگرە (Drop, Cover, Hold On)",body:"لە کاتی بوومەلەرزەدا:",points:["خۆت بدە بە زەویدا (Drop) و بچۆ ژێر مێزێک یان مێزی کارێکی (Workbench) پتەو — دوور لە ئامێرە قورسەکان، ڕەفەکان و شووشە.","ئەگەر مێز نەبوو، لە تەنیشت دیوارێکی ناوەوە لەسەر ئەژنۆ دابنیشە و سەر و ملت بە دەستەکانت داپۆشە (Cover).","مێزەکە توند بگرە (Hold On) تا لەرزینەکە بە تەواوی دەوەستێت.","ڕامەکە و مەچۆ ژێر ئامێرەکان یان لای ڕەفەکان! ئامێرە قورسەکان و ڕەفەکان دەتوانن بجووڵێن یان بکەونە سەرت."]},{heading:"٢. دوای بوومەلەرزە",body:"دوای ئەوەی لەرزینەکە وەستا:",points:["ئامێرەکان بۆ زیان بپشکنە، و ئامێرە زیانلێکەوتووەکان هەڵمەکە تا دەپشکنرێن.","بزانە ئایا ماددە کیمیاییەکان ڕژاون یان نا، و لێیان دوور بکەوەرەوە.","ئەگەر بۆنی گاز هات — بە خێرایی دەربچۆ، کارگەکە چۆڵ بکە، و لە دەرەوە پەیوەندی بە ١١٥ بکە.","تەنها کارمەندانی ڕاهێنراو و دەستنیشانکراو گاز دەبڕن، و تەنها ئەو کاتە کە بۆنی هات یان دەنگی دزەکردنی هات و گەیشتن بە سەمامەی گاز سەلامەت بوو، بەبێ چوونە ناو ئەو شوێنەی گازی تێدا کۆبووەتەوە و بەبێ دروستکردنی هیچ پریشکێک؛ کارەبا ببڕە ئەگەر زیان بە وایەر یان تابلۆکان گەیشتبێت.","پێش گەڕانەوە بۆ ژوورەوە، دەبێت ئەندازیارێک بینای کارگەکە بۆ درز بپشکنێت."]},{heading:"٣. ئامادەباشی",body:"پلانی پێشوەخت:",points:["بۆ هەر بەشێک پلانی بوومەلەرزە ئامادە بکە.","ئامێرە قورسەکان بە زنجیر یان بۆڵت جێگیر بکە.","دەبە و قوتووە کیمیاییەکان لەسەر ڕەفی نزم و جێگیر دابنێ.","ڕاڕەوەکانی دەرچوون هەمیشە کراوە بن.","هەر ٦ مانگ جارێک مەشق بکە."]}],media:[{kind:"image",src:"media/images/factory_earthquake.png",title:"بوومەلەرزە",description:"بوومەلەرزە لە کارگەدا"}],quiz:[{question:"لە کاتی بوومەلەرزەدا لە کارگەیەکدا، یەکەم کار چییە؟",options:[{text:"ڕاکردن بەرەو دەرەوە",correct:!1},{text:"خۆت بدە بە زەویدا و بچۆ ژێر مێزێکی پتەو",correct:!0},{text:"ئامێرەکان بکوژێنەرەوە",correct:!1},{text:"بچۆ نزیک پەنجەرەکان",correct:!1}],explanation:"خۆت بدە بە زەویدا، خۆت بپارێزە، خۆت بگرە — یەکەم ڕێکارە لە ناو بیناکاندا، دوور لە ئامێر، ڕەف و شووشە."},{question:"دوای بوومەلەرزە لە کارگەیەکی کیمیاییدا، یەکەم پشکنین چییە؟",options:[{text:"کارەبا",correct:!1},{text:"ڕژانی ماددە کیمیاییەکان",correct:!0},{text:"ئاو",correct:!1},{text:"تەلەفۆن",correct:!1}],explanation:"ڕژانی ماددە کیمیاییەکان مەترسییەکی گەورەیە دوای بوومەلەرزە و پێویستە بە خێرایی بپشکنرێت."},{question:"دوای ئەوەی لەرزینەکە وەستا، بۆنی گاز لە کارگەکەدا دەکەیت. چی دەکەیت؟",options:[{text:"دەچمە لای سەمامەی گاز و خۆم دەیبڕم",correct:!1},{text:"پانکەکانی ڕاکێشانی هەوا هەڵدەکەم بۆ ئەوەی گازەکە دەربچێت",correct:!1},{text:"بە خێرایی دەردەچم و لە دەرەوە پەیوەندی بە ١١٥ دەکەم",correct:!0},{text:"سەرەتا بە تەلەفۆنەکەم پەیوەندی بە ١١٥ دەکەم، دواتر دەردەچم",correct:!1}],explanation:"ئەگەر بۆنی گاز هات، بە خێرایی دەربچۆ، کارگەکە چۆڵ بکە و لە دەرەوە پەیوەندی بە ١١٥ بکە؛ تەنها کارمەندانی ڕاهێنراو و دەستنیشانکراو گاز دەبڕن، و تەنها ئەو کاتە کە گەیشتن بە سەمامەکە سەلامەت بێت، بەبێ چوونە ناو ئەو شوێنەی گازی تێدا کۆبووەتەوە و بەبێ دروستکردنی هیچ پریشکێک."}]},{id:18,code:"FLOOD-118",icon:"Waves",accent:"#2563eb",title:"لافاو و ئاوگرتن",subtitle:"Flood Emergency in Industrial Areas",summary:"پاراستنی کارگە و کرێکاران لە کاتی لافاودا",blocks:[{body:"لافاو دەتوانێت کارگەکان بە تەواوی وێران بکات: ئامێرەکان تێکبدات، ماددە کیمیاییەکان بڵاو بکاتەوە و کارەبا بکاتە مەترسی. ئەو کارگانەی لە نزیک ڕووبار و دۆڵەکانن زیاتر لە مەترسیدان."},{heading:"١. پێش لافاو",body:"ئامادەباشی:",points:["ئاگادارکردنەوەکانی کەشناسی (Meteorology) بەدواداچوون بۆ بکە.","کەرەستە گرنگەکان و ماددە کیمیاییەکان بگوازەرەوە بۆ شوێنێکی بەرز.","سیستەمی کارەبا بۆ بڕینی خۆکار (Auto-shutoff) ئامادە بکە.","کیسەی لم (Sandbags) لەبەردەم دەرگاکان و بناغەی کارگەکە دابنێ."]},{heading:"٢. لە کاتی لافاودا",body:"ڕێکارە بەپەلەکان:",points:["ئەگەر بە سەلامەتی توانیت و ئاو نەگەیشتبووە تابلۆکانی کارەبا، کارەبا و گاز ببڕە؛ لە ناو ئاودا دەست لە کارەبا مەدە!","مەچۆ ناو ئاوی لافاوەوە — ١٥ سم ئاوی خێرا دەتوانێت مرۆڤ بخات، و ٣٠ سم دەتوانێت ئۆتۆمبێل ببات.","بچۆ شوێنێکی بەرز — نهۆمی دووەم یان سەربان.","پەیوەندی بە ١١٥ بکە و لە شوێنی خۆت بمێنەوە تا تیمەکانی ڕزگارکردن دەگەن."]},{heading:"٣. دوای لافاو",body:"گەڕانەوە و پاککردنەوە:",points:["مەچۆ ناو کارگەکە تا ئەندازیار دڵنیا نەبێتەوە کە بیناکە سەلامەتە.","دەست لە ماددە کیمیاییە ئاوتێکەوتووەکان مەدە — لە ڕێگەی ١١٥ ەوە داوای تیمی ماددە مەترسیدارەکان (HazMat) بکە.","کارەبا هەڵمەکە تا سیستەمەکە لەلایەن کارەباچییەکی شارەزاوە دەپشکنرێت.","وێنەی هەموو زیانەکان بگرە بۆ بیمە و ڕاپۆرت."]}],media:[{kind:"image",src:"media/images/factory_flood.png",title:"لافاو",description:"لافاو لە کارگەدا"}],quiz:[{question:"لە کاتی لافاودا لە کارگەیەکدا، یەکەم کار چییە؟",options:[{text:"ئامێرەکان بپارێزە",correct:!1},{text:"کارەبا و گاز ببڕە، ئەگەر بە سەلامەتی توانیت",correct:!0},{text:"بڕۆ بۆ ماڵەوە",correct:!1},{text:"ئاوەکە بە پەمپ دەربکێشە",correct:!1}],explanation:"کارەبا و گاز یەکەم مەترسییەکانن لە کاتی لافاودا؛ بەڵام ئەگەر ئاو گەیشتبووە تابلۆکان، نزیک مەبەرەوە و بچۆ شوێنێکی بەرز."},{question:"چەند ئاوی خێرا دەتوانێت مرۆڤ بخات؟",options:[{text:"٥٠ سم",correct:!1},{text:"٧٥ سم",correct:!1},{text:"١٥ سم",correct:!0},{text:"١ مەتر",correct:!1}],explanation:"مەچۆ ناو ئاوی لافاوەوە: ١٥ سم ئاوی خێرا دەتوانێت مرۆڤ بخات، و ٣٠ سم دەتوانێت ئۆتۆمبێل ببات. بچۆ شوێنێکی بەرز و پەیوەندی بە ١١٥ بکە."},{question:"دوای لافاو، دەبەی ماددە کیمیاییەکانت بینی کە ئاوی لافاو گەیشتبووە پێیان. چی دەکەیت؟",options:[{text:"بە ئاوی پاک دەیانشۆم و دەیانگەڕێنمەوە سەر ڕەفەکە",correct:!1},{text:"دەستیان لێ نادەم و لە ڕێگەی ١١٥ ەوە داوای تیمی HazMat دەکەم",correct:!0},{text:"بە دەستی خۆم دەیانبەمە دەرەوە پێش ئەوەی ئاو دیسان بەرز ببێتەوە",correct:!1},{text:"دەیانکەمەوە بۆ ئەوەی ببینم ئاو چووەتە ناویان یان نا",correct:!1}],explanation:"دەست لە ماددە کیمیاییە ئاوتێکەوتووەکان مەدە — لە ڕێگەی ١١٥ ەوە داوای تیمی ماددە مەترسیدارەکان (HazMat) بکە."}]},{id:19,code:"FACT-119",icon:"Siren",accent:"#dc2626",title:"وەڵامدانەوەی بەرگریی شارستانی لە کارگەکاندا",subtitle:"Industrial CD Response & Multi-Agency Coordination",summary:"پێکهێنانی تیمی وەڵامدانەوەی کارگە لە کاتی ڕووداوەکاندا و هەماهەنگی لەگەڵ ١١٥",blocks:[{body:"کارگە گەورەکان (نەوت، گاز، کیمیا، پۆڵا) دەبێت تیمی تایبەتی خۆیان بۆ وەڵامدانەوەی تەنگانە هەبێت کە پێش گەیشتنی تیمەکانی ١١٥ کار بکەن. ستانداردی NFPA 600 (Facility Fire Brigades) ڕێکخستن، ڕاهێنان و ئامێرەکانی تیمەکانی ئاگرکوژاندنەوەی کارگەکان دیاری دەکات. یەکەم خولەکەکانی ڕووداو زۆر گرنگن، بۆیە تیمی کارگە دەبێت ئامادە و ڕاهێنراو بێت."},{heading:"١. پێکهێنانی تیمی وەڵامدانەوەی کارگە (ERT)",body:"بنەما سەرەکییەکانی تیمی وەڵامدانەوەی تەنگانە (Emergency Response Team):",points:["قەبارەی تیم: بەپێی هەڵسەنگاندنی مەترسییەکانی کارگە و ئەرکەکانی تیم دیاری دەکرێت؛ NFPA 600 ڕێژەیەکی جێگیری ئەندامان بەرامبەر ژمارەی کارمەندان دیاری ناکات.","ڕاهێنان: بەپێی ئەرکەکانی هەر ئەندامێک، لەگەڵ ڕاهێنانی نوێکردنەوە (Refresher) لانیکەم ساڵی جارێک.","فەرماندەی ڕووداو (Incident Commander — IC): تەنها یەک کەس فەرمان دەدات، بۆ ئەوەی فەرمانەکان تێکەڵ نەبن.","ئەرکە سەرەکییەکان: کوژاندنەوەی ئاگر، ڕزگارکردن، فریاکەوتنی سەرەتایی و چۆڵکردنی بینا.","پەیوەندی: بێتەل (Radio) بە کەناڵێکی تایبەت، و مۆبایل وەک ڕێگای یەدەگ.","کاتی وەڵامدانەوە: لە پلانەکەدا دیاری بکە، بە مەشق بیپێوە و باشتری بکە.","پێشنیار: خولەکانی ICS-100 و ICS-200 (FEMA) بۆ فێربوونی سیستەمی فەرماندەیی ڕووداو."]},{heading:"٢. پلانی وەڵامدانەوەی تەنگانە (ERP)",body:"پلانی وەڵامدانەوەی تەنگانە (Emergency Response Plan) بەپێی ستانداردەکان:",points:["پلانی کاری تەنگانە دەبێت نووسراو بێت و لە کارگەدا بەردەست بێت؛ ئەو کارگانەی ١٠ کارمەند یان کەمتریان هەیە دەتوانن بە زارەکی ڕایبگەیەنن (OSHA 29 CFR 1910.38).","بەشە سەرەکییەکان: ئەرک، ڕێکار، ڕێگاکانی دەرچوون، پەیوەندی، سەرچاوەکان، مەشق و هەڵسەنگاندنی دوای ڕووداو.","خاڵەکانی کۆبوونەوە (Assembly Points): یەکێکی سەرەکی و یەکێکی یەدەگ، لە شوێنێکی سەلامەت و دوور لە بینا و ڕێگای ئۆتۆمبێلەکانی تەنگانە.","ڕێگاکانی دەرچوون: بە گشتی لانیکەم ٢ ڕێگا لە هەر نهۆمێک (NFPA 101، لەگەڵ هەندێک ئاوارتە).","زەنگی ئاگر (Alarm): دەبێت لە هەموو شوێنەکانی بینادا ببیسترێت یان ببینرێت (NFPA 72).","تیمی فریاکەوتنی سەرەتایی: لە هەر دەوامێکدا (Shift) کارمەندی ڕاهێنراو لەسەر فریاکەوتنی سەرەتایی و CPR هەبن.","مەشق (Drill): بە ڕێکوپێکی، و ئەنجامی هەر مەشقێک تۆمار بکرێت.","هەڵسەنگاندنی دوای ڕووداو (Post-Response Critique): لە زووترین کاتدا دوای هەر ڕووداوێک."]},{heading:"٣. هەماهەنگی لەگەڵ بەرگریی شارستانی (١١٥)",body:"کاتێک ڕووداو ڕوودەدات و تیمەکانی ١١٥ دەگەن، دەبێت ERT ئەم هەنگاوانە بنێت:",points:["١. یەکسەر پەیوەندی بە ١١٥ بکە، و بە ١٢٢ ئەگەر بریندار هەبوو.","٢. زانیارییە سەرەکییەکان بدە: شوێن، جۆری ڕووداو، ژمارەی بریندارەکان، ماددە مەترسیدارەکان و ڕێگای گەیشتن.","٣. نەخشەی کارگە (Site Map) لەبەردەم دەرگا ئامادە بکە، لەگەڵ شوێنەکانی مەترسی و شوێنەکانی بڕینی کارەبا و گاز.","٤. کەسی پەیوەندی (Liaison Officer): تەنها یەک کەس پەیوەندی لەگەڵ ١١٥ دەکات.","٥. پەڕەکانی SDS بۆ هەموو ماددە کیمیاییەکان ئامادە بکە.","٦. ناو و گوتەی شایەتەکان تۆمار بکە.","٧. گواستنەوەی فەرماندەیی: کاتێک ١١٥ دەگات، فەرماندەیی دەچێتە دەست فەرماندەی ١١٥ و ERT یارمەتی دەدات.","٨. بەڵگەنامە: وێنە، ڤیدیۆ و تۆماری ڕووداو (Incident Log) بۆ لێکۆڵینەوە و بیمە."]},{heading:"٤. کارکردن لەگەڵ تیمی ماددە مەترسیدارەکان (HazMat)",body:"بۆ ڕووداوە کیمیاییەکان، تیمی HazMat پێویستە:",points:["ئاستەکانی ڕاهێنانی HazMat (OSHA 1910.120 و NFPA 470، کە NFPA 472 ی تێدا کۆکراوەتەوە):","• ئاستی هۆشیاری (Awareness): ناسینی مەترسی، دوورکەوتنەوە و ئاگادارکردنەوە — بۆ هەموو کارمەندان.","• ئاستی کارپێکردن (Operations): پاراستنی خەڵک و دەوروبەر بە ڕێگا بەرگرییەکان (Defensive) لە دوورەوە.","• ئاستی تەکنیکی (Technician): ڕاگرتنی دزەکردن لە نزیکەوە (Offensive) بە PPE ی تایبەت.","• ئاستی پسپۆڕ (Specialist): زانیاریی قووڵ لەسەر ماددە دیاریکراوەکان و پشتگیریکردنی تەکنیکییەکان.","سێ ناوچە: ناوچەی گەرم (Hot Zone)، ناوچەی نیمچەگەرم (Warm Zone) و ناوچەی سارد (Cold Zone).","ئاستەکانی PPE ی HazMat: A، B، C، D (A بەرزترین پاراستنە).","پاککردنەوەی پیسبوون (Decontamination) لە ناوچەی نیمچەگەرمدا دەکرێت، پێش چوون بۆ ناوچەی سارد.","کارمەندانی ڕاهێنەنەکراو ناچنە ناوچەی گەرم؛ چاوەڕێی تیمەکانی ١١٥ بن.","پلانی کارگە دەبێت دیاری بکات کە تیمە تایبەتەکانی ماددە مەترسیدارەکان چۆن لە ڕێگەی ١١٥ ەوە داوا دەکرێن."]},{heading:"٥. وەڵامدانەوەی چەند دەزگایەک پێکەوە (Multi-Agency Response)",body:"ڕووداوە گەورەکان پێویستیان بە چەند دەزگایەک دەبێت:",points:["١١٥ بەرگریی شارستانی: کوژاندنەوەی ئاگر، ڕزگارکردن و ماددە مەترسیدارەکان.","١٢٢ ئەمبولانس: چارەسەری پزیشکی و گواستنەوەی بریندارەکان.","١٠٤ پۆلیس: گەمارۆدانی دەوروبەر، هاتوچۆ و لێکۆڵینەوەی یاسایی.","دەزگاکانی ئاسایش: لە کاتی گومانی تەقەمەنی یان تیرۆردا — لە ڕێگەی ١٠٤ ەوە ئاگادار دەکرێنەوە.","وەزارەتی تەندروستی: ئامادەکردنی نەخۆشخانە نزیکەکان.","فەرمانگەی کارەبا: بڕینی کارەبا لە دەوروبەر.","دەزگاکانی ئاو و گاز: بڕینی هێڵەکانی ئاو و گاز.","دەستەی ژینگە: ئەگەر ماددە کیمیاییەکان لە ژینگەدا بڵاو بوونەوە.","ناوەندی کارەکانی تەنگانە (EOC): بۆ ڕووداوە گەورەکان کە چەندین دەزگا تێیدا بەشدار دەبن."]},{heading:"٦. قۆناغەکانی وەڵامدانەوە (٥ قۆناغ)",body:"هەر ڕووداوێک بەم ٥ قۆناغەدا تێدەپەڕێت:",points:["١. ناسینەوە (Detection): هەستەوەر، زەنگی ئاگر یان شایەت.","٢. ئاگادارکردنەوە (Notification): پەیوەندیکردن بە ١١٥ ەوە، و ئاگادارکردنەوەی ERT و کەسی پەیوەندی.","٣. وەڵامدانەوە (Response): ERT کار دەکات تا تیمەکانی ١١٥ دەگەن.","٤. کەمکردنەوەی مەترسی (Mitigation): کوژاندنەوەی ئاگر، ڕزگارکردن و پاککردنەوەی پیسبوون.","٥. گەڕانەوە بۆ باری ئاسایی (Recovery): پاککردنەوە، شیکردنەوە و هەڵسەنگاندنی دوای ڕووداو.","دەبێت هەر قۆناغێک تۆمار بکرێت (Incident Action Plan — IAP).","کاتژمێری زێڕین (Golden Hour): چارەسەری خێرا دوای برینداربوونی سەخت دەرفەتی مانەوە لە ژیاندا زیاد دەکات — بۆیە پەیوەندیکردنی خێرا بە ١٢٢ ەوە گرنگە."]},{heading:"٧. مەشق و ڕاهێنان (Drills & Training)",body:"مەشق بنەمای ئامادەباشییە (خشتەی پێشنیارکراو):",points:["مەشقی سەر مێز (Tabletop Exercise): هەر ٣ مانگ جارێک — سیناریۆ لەسەر مێز.","مەشقی کرداری (Functional Drill): هەر ٦ مانگ جارێک — تەنها تیمی ERT، نەک هەموو بیناکە.","مەشقی تەواو (Full-Scale Drill): ساڵی جارێک — هەموو کارگەکە لەگەڵ ١١٥.","هەڵسەنگاندن: ڕاپۆرتی دوای مەشق (After-Action Report) لە زووترین کاتدا.","ڕاهێنانی ERT: بە بەردەوامی و بەپێی ئەرکەکان، لانیکەم ساڵی جارێک.","ستانداردەکانی شارەزایی: NFPA 1081 (Facility Fire Brigade Member)، OSHA 1910 Subpart L، و ICS-100/200.","مەشقی هاوبەش لەگەڵ ١١٥: ساڵی جارێک بۆ هەماهەنگی."]}],media:[{kind:"video",src:"media/videos/fact_ert_response.mp4",title:"مەشقی وەڵامدانەوەی ERT",description:"مەشقی تەواو لە کارگەیەکی نەوتدا"},{kind:"image",src:"media/images/fact_ics_chart.png",title:"پەیکەری فەرماندەیی ڕووداو (ICS)",description:"پەیکەری فەرماندەیی ڕووداو (ICS)"}],quiz:[{question:"قەبارەی تیمی وەڵامدانەوەی تەنگانە (ERT) لە کارگەدا چۆن دیاری دەکرێت؟",options:[{text:"بە ڕێژەیەکی جێگیر: ١ بۆ هەر ١٠٠ کارمەند",correct:!1},{text:"بەپێی هەڵسەنگاندنی مەترسییەکانی کارگە و ئەرکەکانی تیم",correct:!0},{text:"بە ڕێژەیەکی جێگیر: ١ بۆ هەر ٢٠٠ کارمەند",correct:!1},{text:"بە ڕێژەیەکی جێگیر: ١ بۆ هەر ٢٥ کارمەند",correct:!1}],explanation:"NFPA 600 ڕێژەیەکی جێگیری ئەندامان بەرامبەر ژمارەی کارمەندان دیاری ناکات؛ هەر کارگەیەک بەپێی مەترسی و ئەرکەکانی خۆی قەبارەی تیم دیاری دەکات."},{question:"کاتژمێری زێڕین (Golden Hour) واتای چییە؟",options:[{text:"کاتژمێرێکی تایبەتی کار",correct:!1},{text:"کاتی سەرەتا دوای برینداربوونی سەخت، کە چارەسەری خێرا تێیدا زۆر گرنگە",correct:!0},{text:"کاتی نیوەڕۆ",correct:!1},{text:"گەرمای ڕۆژ",correct:!1}],explanation:"Golden Hour ئەو ماوەیەیە دوای برینداربوونی سەخت کە گەیاندنی خێرای بریندار بۆ چارەسەر دەرفەتی مانەوە لە ژیاندا زیاد دەکات؛ بۆیە یەکسەر پەیوەندی بە ١٢٢ بکە."},{question:"لە سیستەمی ICS دا، کەسی پەیوەندی (Liaison Officer) چی دەکات؟",options:[{text:"ئاگر دەکوژێنێتەوە",correct:!1},{text:"پەیوەندی لەگەڵ دەزگا دەرەکییەکان دەکات",correct:!0},{text:"CPR دەکات",correct:!1},{text:"دەرگاکە دادەخات",correct:!1}],explanation:"کەسی پەیوەندی (Liaison Officer) پەیوەندی لەگەڵ ١١٥، پۆلیس (١٠٤)، ئەمبولانس (١٢٢) و دەزگاکانی تر دەکات."},{question:"ئاستی Operations ی HazMat چی دەکات؟",options:[{text:"تەنها ئاگادارکردنەوە",correct:!1},{text:"بەرگری (Defensive) — ڕێگرتن لە بڵاوبوونەوە لە دوورەوە",correct:!0},{text:"Offensive — ڕاگرتنی دزەکردن لە نزیکەوە",correct:!1},{text:"پسپۆڕی (Specialist)",correct:!1}],explanation:"ئاستی Operations بەرگرییە (Defensive): ڕێگرتن لە بڵاوبوونەوەی ماددەکە لە دوورەوە، نەک کارکردن لە نزیکەوە (Offensive)."},{question:"ناوچەی گەرم (Hot Zone) لە HazMat دا چییە؟",options:[{text:"شوێنێکی سارد و سەلامەت",correct:!1},{text:"ناوچەیەکی بە تەواوی پاک",correct:!1},{text:"مەترسیدارترین ناوچە — تەنها تەکنیکییەکانی HazMat بە PPE ی گونجاو",correct:!0},{text:"ناوچەی کۆبوونەوە",correct:!1}],explanation:"ناوچەی گەرم شوێنی ماددە مەترسیدارەکەیە؛ تەنها تەکنیکییەکانی HazMat بە PPE ی ئاستی A یان B دەچنە ناوی."},{question:"کاتێک تیمەکانی ١١٥ دەگەنە شوێنی ڕووداوەکە، فەرماندەیی دەچێتە دەست کێ؟",options:[{text:"ERT بەردەوام دەبێت",correct:!1},{text:"فەرماندەی ١١٥",correct:!0},{text:"بەڕێوەبەری کارگە",correct:!1},{text:"پۆلیس",correct:!1}],explanation:"گواستنەوەی فەرماندەیی (ICS Transfer): کاتێک ١١٥ دەگات، فەرماندەیی دەچێتە دەست فەرماندەی ١١٥ و ERT یارمەتی دەدات."}]},{id:20,code:"FACT-120",icon:"FlameKindling",accent:"#dc2626",title:"پۆلێنکردنی ئاگر لە کارگەکاندا",subtitle:"Industrial Fire Classes — NFPA 30/484/654",summary:"پۆلێنکردنی تایبەت بۆ کارگەکان: شلەمەنی، گاز، کانزا و تۆزی ئاگرگر",blocks:[{body:"ئەم مۆدیوڵە سیستەمی NFPA بەکاردەهێنێت: A کەرەستەی ڕەق، B شلەمەنی و گازە ئاگرگرەکان، C ئامێرە کارەباییەکان، D کانزاکان، K ڕۆنی چێشتخانە. پۆلەکانی ئاگر لێرەدا بە پیتەکانی NFPA 10 نووسراون وەک سەرچاوەی پرۆژە؛ سیستەمی فەرمیی دهۆک هێشتا پشتڕاست نەکراوەتەوە. هاوتاکانی EN 2: NFPA A = EN A؛ NFPA B (شلە) = EN B؛ NFPA B (گاز) = EN C؛ NFPA C (ئامێری کارەبایی کە کارەبای تێدایە) هیچ پۆلێکی EN ی نییە؛ NFPA D = EN D؛ NFPA K = EN F. ستانداردە تایبەتەکان لە کارگەکاندا: شلەمەنییە ئاگرگرەکان (NFPA 30)، کانزا ئاگرگرەکان (NFPA 484) و تۆزی ئاگرگر (NFPA 654). لە چاپی ٢٠٢٥ ەوە، NFPA 484 و NFPA 654 لە ستانداردی NFPA 660 دا کۆکراونەتەوە."},{heading:"١. پۆلی A — کەرەستە ڕەقە ئاگرگرەکان لە کارگەدا",body:"کەرەستە ڕەقە بڵاوەکان لە کارگەکاندا:",points:["سووتەمەنی: کاغەز، کارتۆن، قوماش، دار، لاستیک، پلاستیک و پالێت (Pallets).","ئەم ماددانە خەڵووز و ئاگری شاراوە بەجێدەهێڵن؛ دوای کوژاندنەوە شوێنەکە بە ئاو سارد بکەرەوە و چاودێری بکە.","لە کارگەکاندا: کۆگاکانی کاغەز و کارتۆن و پالێتە دارینەکان ئاگر بە خێرایی بڵاو دەکەنەوە.","ئاگرکوژێنەرەوە: ئاو، کەف، تۆزی ABC.","پالێتە بەتاڵە کەڵەکەکراوەکان مەترسییەکی گەورەن: بە بەرزی کەڵەکەیان مەکە، و لە دەرەوە یان لە شوێنێکی خاوەن سپرینکلەر هەڵیانبگرە.","ستاندارد: NFPA 13 (سیستەمەکانی سپرینکلەر)، کە پاراستنی کۆگاکانیشی تێدایە.","نموونە لە کارگەکاندا: کۆگا و هێڵەکانی پاکەتکردن (Packaging Lines)."]},{heading:"٢. پۆلی B — شلەمەنییە ئاگرگرەکان لە کارگەدا",body:"یەکێک لە مەترسیدارترین پۆلەکان لە کارگەکاندا:",points:["سووتەمەنی: بەنزین، نەوت، دیزڵ، ئەسیتۆن (Acetone)، تۆلوین (Toluene)، زایلین (Xylene).","خاڵی هەڵگیرسان (Flash Point): بەنزین نزیکەی -٤٣°C، ئەسیتۆن -٢٠°C، دیزڵ ٥٢°C یان زیاتر.","سنوورەکانی تەقینەوە (LEL/UEL): کەمترین و زۆرترین چڕیی هەڵم لە هەوادا کە دەتوانێت ئاگر بگرێت:","• بەنزین: ١٫٤-٧٫٦٪.","• ئەسیتۆن: ٢٫٥-١٢٫٨٪.","• میتانۆڵ (Methanol): ٦-٣٦٪.","ئاگرکوژێنەرەوە: کەف (AFFF یان کەفی بێ فلۆر)، CO₂، تۆزی ABC. بۆ ئەسیتۆن، میتانۆڵ، ئەلکهول و شلە جەمسەرییەکانی تر (polar solvents): CO₂، تۆزی وشک یان کەفی بەرگەگری ئەلکهول (AR foam)؛ کەفی ئاسایی لەسەریان تێکدەچێت.","فیچقەی ئاو بەسەر شلەمەنییەکەدا مەکە — ئاگرەکە بڵاو دەکاتەوە. BLEVE (Boiling Liquid Expanding Vapor Explosion) کاتێک ڕوودەدات کە تانکێکی پەستاندار بە ئاگر گەرم دەبێت.","پۆلەکانی شلەمەنی بەپێی NFPA 30 (Flash Point = خاڵی هەڵگیرسان، Boiling Point = خاڵی کوڵان):","• Class I (Flammable): خاڵی هەڵگیرسان کەمتر لە ٣٧٫٨°C — IA (هەڵگیرسان < ٢٢٫٨°C و کوڵان < ٣٧٫٨°C)، IB (هەڵگیرسان < ٢٢٫٨°C و کوڵان ٣٧٫٨°C یان زیاتر)، IC (هەڵگیرسان ٢٢٫٨ تا < ٣٧٫٨°C).","• Class II (Combustible): خاڵی هەڵگیرسان ٣٧٫٨ تا < ٦٠°C.","• Class III (Combustible): IIIA لە ٦٠ تا < ٩٣°C، و IIIB ٩٣°C یان زیاتر.","دیوارەکانی ڕاگرتن (Diking): بەپێی NFPA 30، قەبارەی شوێنی ڕاگرتن دەبێت کەمتر نەبێت لەو شلەمەنییەی کە دەتوانێت لە گەورەترین تانکی پڕەوە بڕژێت (١٠٠٪)؛ ڕێژەی ١١٠٪ لە هەندێک یاسا و ڕێنماییی تردا داوا دەکرێت (بۆ ئاوی بارانیش).","چڕیی هەڵم (Vapor Density): هەڵمی بەنزین لە هەوا قورسترە (نزیکەی ٣-٤ جار) و لە شوێنە نزمەکاندا کۆ دەبێتەوە."]},{heading:"٣. گازە ئاگرگرەکان — NFPA: پۆلی B، EN 2: پۆلی C",body:"گازەکانی کارگە: ئەسیتیلین، پرۆپان، هایدرۆجین:",points:["سەرچاوە: ئەسیتیلین (Acetylene) بۆ لەحیمکردن، پرۆپان (Propane) بۆ هەندێک فۆرکلیفت، هایدرۆجین (Hydrogen) لە بارگاویکردنی باترییە ئەسیدییەکان (Lead-acid).","ئەم گازانە لە پلەی گەرمیی ئاساییدا گازن و بە ئاسانی ئاگر دەگرن. سنوورەکانی تەقینەوە لە هەوادا: هایدرۆجین ٤-٧٥٪، پرۆپان ٢٫١-٩٫٥٪، ئەسیتیلین لە ٢٫٥٪ و زیاتر. (-٢٥٣°C خاڵی کوڵانی هایدرۆجینە، نەک خاڵی هەڵگیرسان.)","گەرمیی بڵێسەی ئۆکسی-ئەسیتیلین (Oxy-Acetylene) لە ٣٠٠٠°C زیاترە.","ئەسیتیلین لەگەڵ مس (Copper) ماددەیەکی تەقەمەنی دروست دەکات (Copper Acetylide)؛ بۆری و ئامێری مسیی نەگونجاو بەکارمەهێنە.","کوژاندنەوە: یەکەم، ئەگەر بێ مەترسی بوو، ڤاڵڤی گاز دابخە. ئاگری گاز مەکوژێنەرەوە ئەگەر نەتتوانی هاتنی گاز ڕابگریت — گازی دزەکردوو دەتوانێت تەقینەوە دروست بکات.","تیمەکانی ١١٥ پرژاندنی ئاو (Water Spray) لە دوورەوە بۆ ساردکردنەوەی سیلیندەر و تانکەکان بەکاردەهێنن، نەک بۆ کوژاندنەوەی بڵێسەی گاز.","ئامێرەکانی دۆزینەوەی گاز (Gas Detectors) لە کۆگاکانی گازدا: زەنگی ئاگادارکردنەوە دەبێت زۆر پێش گەیشتن بە LEL لێبدات (بە گشتی لە ١٠-٢٠٪ ی LEL).","لە کارگەکاندا: شوێنەکانی لەحیمکردن، شوێنەکانی بارگاویکردنی فۆرکلیفت و ژوورەکانی باتری."]},{heading:"٤. پۆلی D — کانزا ئاگرگرەکان (NFPA 484)",body:"کانزا ئاگرگرەکان — یەکێک لە مەترسیدارترین جۆرەکان:",points:["سووتەمەنی: مەگنیسیۆم، تیتانیۆم، تۆزی ئەلەمنیۆم، سۆدیۆم و لیتیۆمی کانزایی (Lithium Metal).","ئەم کانزایانە بە گەرمییەکی زۆر بەرز دەسووتێن و ڕووناکییەکی زۆر توند دەدەن؛ ڕاستەوخۆ سەیری بڵێسەکە مەکە.","ئاو قەدەغەیە! Mg + H₂O → MgO + H₂ (هایدرۆجین دروست دەبێت و دەتوانێت بتەقێتەوە).","CO₂ قەدەغەیە! 2Mg + CO₂ → 2MgO + C (مەگنیسیۆم لە ناو CO₂ یشدا دەسووتێت).","تەنها ئاگرکوژێنەرەوەکانی پۆلی D، و تەنها ئەوەی ناوی ئەو کانزایە لەسەر لەیبڵەکەی هاتبێت: ماددەکە لە کانزایەکەوە بۆ یەکێکی تر جیاوازە (بۆ نموونە تۆز لەسەر بنەمای کلۆریدی سۆدیۆم (NaCl) یان گرافیت؛ تۆزی مس بۆ لیتیۆم). هەرگیز ئاو، تۆزی ئاسایی یان کەف بەکار مەهێنە. لمی وشک تەنها ئەگەر پلانی ئاگری شوێنەکە یان SDS ی کانزاکە ناوی هێنابێت و تەواو وشک بێت.","نموونە لە کارگەکاندا: تواندنەوەی ئەلەمنیۆم، تاشینی مەگنیسیۆم و باترییەکانی لیتیۆمی کانزایی.","NFPA 484: هەڵگرتن، مامەڵەکردن و پاراستنی کانزا ئاگرگرەکان (ئێستا بەشێکە لە NFPA 660).","تۆزی ئەلەمنیۆم: مەترسیی تەقینەوەی تۆزیشی هەیە (NFPA 654 / 660).","وەڵامدانەوە: یەکسەر پەیوەندی بە ١١٥ بکە و تەنها ئاگرکوژێنەرەوەی پۆلی D بەکاربهێنە کە ناوی ئەو کانزایە لەسەر لەیبڵەکەی هاتبێت. باترییەکانی لیتیۆم-ئایۆن (Li-ion) لیتیۆمی کانزاییان تێدا نییە و بە ئاو سارد دەکرێنەوە."]},{heading:"٥. تۆزی ئاگرگر — تەقینەوەی تۆز (NFPA 654)",body:"مەترسییەکی کوشندە لە کارگەکاندا:",points:["پێنجگۆشەی تۆز (Dust Pentagon): سووتەمەنی (تۆز) + ئۆکسجین + گەرمی + بڵاوبوونەوە لە هەوادا + شوێنی داخراو.","سەرچاوە: ئارد، شەکر، دار، خەڵووز، تۆزی کانزاکان و پلاستیک.","کەمترین پلەی گەرمیی هەڵگیرسان (MIT) بەپێی جۆری تۆزەکە دەگۆڕێت؛ سەیری SDS یان ئەنجامەکانی تاقیکردنەوەی تۆز بکە.","کەمترین چڕیی تەقینەوە (MEC) یش بەپێی جۆری تۆزەکە دەگۆڕێت؛ تۆزی بڵاوبووە لە هەوادا هەمیشە مەترسیدارە.","تەقینەوەی یەکەم (Primary): لە ناو ئامێرێکدا (وەک فلتەر یان ئاش).","تەقینەوەی دووەم (Secondary): تەقینەوەی یەکەم تۆزی سەر زەوی و ڕەف و بۆرییەکان بەرز دەکاتەوە، و تەقینەوەیەکی گەورەتر و کوشندەتر ڕوودەدات.","کەمکردنەوەی مەترسی: سیستەمەکانی کۆکردنەوەی تۆز، دەرگاکانی بەتاڵکردنەوەی تەقینەوە (Explosion Vents) و سیستەمەکانی کوژاندنەوە.","پاکوخاوێنی: چینێکی تۆز بە ئەستووریی ٠٫٨ ملم (1/32 inch) لەسەر زیاتر لە ٥٪ ی ڕووبەری زەوی دەتوانێت مەترسی دروست بکات (NFPA 654 / OSHA).","نموونە: لە ساڵی ٢٠٠٨ لە کارگەی شەکری Imperial Sugar (ئەمریکا)، تەقینەوەی تۆزی شەکر ١٤ کرێکاری کوشت (CSB).","ستاندارد: NFPA 654 (ئێستا NFPA 660) و OSHA 29 CFR 1910.272 (بۆ کۆگاکانی دانەوێڵە)."]},{heading:"٦. قۆناغەکانی گەشەکردنی ئاگر لە کارگەدا",body:"٤ قۆناغی ستاندارد — لە کارگەکاندا ئاگر دەتوانێت خێراتر بێت:",points:["سەرەتا (Incipient): ئاگرێکی بچووک — کەسێکی ڕاهێنراو دەتوانێت بە ئاگرکوژێنەرەوەی دەستیی گونجاو بیکوژێنێتەوە، دوای دانی ئاگادارکردنەوە و پەیوەندیکردن بە ١١٥ەوە، و ڕێگای دەرچوون لە پشتیەوە بێت؛ ئەگەر یەکسەر نەکوژایەوە، دەربچۆ.","گەشەکردن (Growth): ئاگر و دووکەڵ بە خێرایی زیاد دەبن و سپرینکلەرەکان کار دەکەن — دەربچۆ و پەیوەندی بە ١١٥ بکە.","گەشەی تەواو (Fully Developed): دوای Flashover — تەنها تیمەکانی ١١٥.","کەمبوونەوە (Decay): سووتەمەنی کەم دەبێتەوە، بەڵام مەترسیی Backdraft و ڕووخان دەمێنێت.","لە کارگەکاندا، کۆگا بەرزەکان، پالێت و شلەمەنییەکان دەتوانن ئاگر خێراتر لە ماڵەکان بگەیەننە قۆناغی تەواو.","تانکی گاز و شلەمەنیی پەستاندار ئەگەر بە ئاگر گەرم ببن دەتوانن بە BLEVE بتەقنەوە — دەوروبەر بە خێرایی چۆڵ بکە.","پلانی کارگە دەبێت ڕێگای گەیشتنی تیمەکانی ١١٥ و شوێنەکانی ئاوی ئاگرکوژاندنەوە (Hydrants) ئامادە و کراوە بهێڵێتەوە.","چاودێری ئاگر دوای کاری گەرم (Hot Work): لە کاتی کاردا و لانیکەم ١ کاتژمێر دوای تەواوبوون، پاشان چاودێری تا ٣ کاتژمێری تر بەپێی بڕیاری بەرپرسی مۆڵەتەکە (NFPA 51B)."]},{heading:"٧. باری ئاگر (Fire Load) و هەڵسەنگاندنی مەترسی",body:"پشکنینی مەترسی لە کارگەدا:",points:["باری ئاگر (Fire Load Density — MJ/m²): بڕی ئەو وزەیەی کە ماددە ئاگرگرەکان لە هەر مەترێکی چوارگۆشەدا دەتوانن بیدەن. تێکڕاکانی EN 1991-1-2 (Eurocode 1):","• خانوو (Dwelling): نزیکەی ٧٨٠ MJ/m².","• نووسینگە (Office): نزیکەی ٤٢٠ MJ/m².","• کتێبخانە (Library): نزیکەی ١٥٠٠ MJ/m².","• کۆگا و کارگە: بەپێی ماددە هەڵگیراوەکان هەژمار دەکرێت و زۆر جار لەمانە بەرزترە.","هەڵسەنگاندنی مەترسی (Risk Assessment): مەترسی = ئەگەری ڕوودان (Likelihood) × قورسیی ئەنجام (Severity).","• کەم (Low): بە ڕێکارە ئاساییەکان کۆنترۆڵ دەکرێت.","• مامناوەند (Medium): پێویستی بە کۆنترۆڵی زیادە و چاودێری هەیە.","• بەرز (High): پێویستی بە کاری خێرا هەیە پێش بەردەوامبوونی کار.","• زۆر بەرز (Extreme): کار دەوەستێت تا مەترسی کەم دەبێتەوە.","بەرگریی دیوار و بانەکان دژی ئاگر (Fire Resistance Rating) بەپێی جۆر و بەکارهێنانی بینا لە کۆدەکانی بیناسازییەوە دیاری دەکرێت (وەک NFPA 101 و NFPA 5000).","هەڵسەنگاندنی مەترسییەکانی کارگە (وەک HVA) لانیکەم ساڵی جارێک و دوای هەر گۆڕانکارییەکی گەورە نوێ بکەرەوە."]}],media:[{kind:"video",src:"media/videos/fact_dust_explosion.mp4",title:"تەقینەوەی تۆز",description:"نمایشی تەقینەوەی تۆز"},{kind:"image",src:"media/images/fact_fire_classes.png",title:"خشتەی پۆلەکانی ئاگر",description:"پۆلێنکردنی ئاگر لە کارگەکاندا"}],quiz:[{question:"بۆ ئاگری پۆلی D، کام ئاگرکوژێنەرەوە گونجاوە؟",options:[{text:"تۆزی ABC",correct:!1},{text:"ئاو",correct:!1},{text:"ئاگرکوژێنەرەوەی پۆلی D کە ناوی ئەو کانزایە لەسەر لەیبڵەکەی هاتبێت",correct:!0},{text:"CO₂",correct:!1}],explanation:"تەنها ئاگرکوژێنەرەوەی پۆلی D یان ماددەیەک کە ناوی ئەو کانزایەی دەسووتێت لەسەر لەیبڵەکەی هاتبێت گونجاوە؛ ماددەکە لە کانزایەکەوە بۆ یەکێکی تر جیاوازە. ئاو، CO₂ و تۆزی ABC بەکارمەهێنە."},{question:"BLEVE واتای چییە؟",options:[{text:"زەنگی ئاگر",correct:!1},{text:"تەقینەوەی هەڵمی شلەی کوڵاو (Boiling Liquid Expanding Vapor Explosion)",correct:!0},{text:"سیستەمی سپرینکلەر",correct:!1},{text:"پۆلی گاز",correct:!1}],explanation:"BLEVE تەقینەوەی تانکێکی پەستاندارە کە شلەمەنیی تێدایە، کاتێک بە ئاگر گەرم دەبێت و هەڵم بە خێرایی فراوان دەبێت."},{question:"پێنجگۆشەی تۆز (Dust Pentagon) چەند توخمی هەیە؟",options:[{text:"٣",correct:!1},{text:"٤",correct:!1},{text:"٥",correct:!0},{text:"٦",correct:!1}],explanation:"پێنج توخم: سووتەمەنی + ئۆکسجین + گەرمی + بڵاوبوونەوە + شوێنی داخراو."},{question:"ئەسیتیلین لەگەڵ مس (Copper) چی دروست دەکات؟",options:[{text:"هیچ ڕوونادات",correct:!1},{text:"Copper Acetylide — ماددەیەکی تەقەمەنی",correct:!0},{text:"پاککردنەوە",correct:!1},{text:"گەرمییەکی کەم",correct:!1}],explanation:"ئەسیتیلین لەگەڵ مس ماددەیەکی تەقەمەنیی هەستیار (Copper Acetylide) دروست دەکات کە بە لێدان یان گەرمی دەتەقێتەوە."},{question:"تۆزی ئەلەمنیۆم (Aluminum Powder) چ مەترسییەکی هەیە؟",options:[{text:"تەنها پۆلی A",correct:!1},{text:"پۆلی D و تەقینەوەی تۆز",correct:!0},{text:"تەنها گاز",correct:!1},{text:"هیچ مەترسییەکی نییە",correct:!1}],explanation:"تۆزی ئەلەمنیۆم هەم کانزای ئاگرگرە (پۆلی D) و هەم تۆزی ئاگرگرە (NFPA 484 / 654، ئێستا NFPA 660)."},{question:"بەپێی EN 1991-1-2، تێکڕای باری ئاگر لە خانووەکاندا (Dwelling) نزیکەی چەندە؟",options:[{text:"١٠٠ MJ/m²",correct:!1},{text:"٢٣٠ MJ/m²",correct:!1},{text:"٤٢٠ MJ/m²",correct:!1},{text:"٧٨٠ MJ/m²",correct:!0}],explanation:"تێکڕای باری ئاگر لە خانووەکاندا نزیکەی ٧٨٠ MJ/m² ە، و لە نووسینگەکاندا نزیکەی ٤٢٠ MJ/m² (EN 1991-1-2، خشتەی E.4)."}]},{id:21,code:"FACT-121",icon:"ShowerHead",accent:"#2563eb",title:"سیستەمەکانی کوژاندنەوەی ئاگر لە کارگەکاندا",subtitle:"Portable Extinguishers + Fixed Systems (Sprinkler/Foam/CO₂)",summary:"ئاگرکوژێنەرەوە دەستییەکان و سیستەمە جێگیرەکانی کوژاندنەوەی ئاگر لە کارگەکاندا",blocks:[{body:"کارگە پێویستی بە دوو ئاستی کوژاندنەوەی ئاگر هەیە: ١) ئاگرکوژێنەرەوە دەستییەکان (Portable Extinguishers) بۆ ئاگری بچووک لە قۆناغی سەرەتاییدا، ٢) سیستەمە جێگیرەکان (Fixed Suppression Systems) بۆ پاراستنی بەردەوام. بەپێی جۆری مەترسی: سپرینکلەر (NFPA 13)، کەف (NFPA 11 / 16)، CO₂ (NFPA 12)، تۆزی وشک (NFPA 17) و Clean Agent (NFPA 2001). ئەم مۆدیوڵە ئەم سیستەمانە و خشتەی پشکنین ڕوون دەکاتەوە."},{heading:"١. ئاگرکوژێنەرەوە دەستییەکان — هەڵبژاردن لە کارگەدا",body:"٧ جۆری سەرەکی و خشتەی هەڵبژاردن:",points:["تۆزی ABC (Multi-purpose): بڵاوترین جۆر بۆ ڕاڕەو و شوێنە گشتییەکان — A، B، C (نەک D و K).","CO₂: بۆ تابلۆکانی کارەبا و ژوورەکانی سێرڤەر — B، C.","کەف (AFFF / Foam): بۆ کۆگاکانی شلەمەنی و شوێنەکانی دیواری ڕاگرتن — A، B.","Wet Chemical (کیمیایی شل): بۆ چێشتخانە و کافتریای کارگە — K.","Clean Agent: بۆ ژوورەکانی سێرڤەر و کۆنترۆڵ.","پۆلی D (ماددەیەک کە ناوی ئەو کانزایەی لەوێ بەکاردێت لەسەر لەیبڵەکەی هاتبێت): بۆ تاشینی کانزاکان و تواندنەوەی ئەلەمنیۆم.","Water Mist (ئاوی وردی بێ کانزا): بۆ A، و هەندێک مۆدێل بۆ C — بەپێی لیستکردنی ئامێرەکە.","ئاستەکانی مەترسی بەپێی NFPA 10 (کەمترین هەڵسەنگاندنی ئاگرکوژێنەرەوەی پۆلی A):","• مەترسیی کەم (Light Hazard — نووسینگە): 2-A.","• مەترسیی ئاسایی (Ordinary Hazard — کارگەی ئاسایی): 2-A.","• مەترسیی زیاد (Extra Hazard — کارگەی خاوەن سووتەمەنیی زۆر): 4-A.","دووریی گەیشتن (Travel Distance) تا ئاگرکوژێنەرەوە:","• پۆلی A: تا ٢٣ مەتر (٧٥ پێ) لە هەموو ئاستەکاندا.","• پۆلی B: ٩ یان ١٥ مەتر (٣٠ / ٥٠ پێ) بەپێی هەڵسەنگاندنی ئاگرکوژێنەرەوەکە و ئاستی مەترسی."]},{heading:"٢. سیستەمەکانی سپرینکلەر — NFPA 13",body:"گرنگترین سیستەمی جێگیر لە زۆربەی کارگەکاندا:",points:["٤ جۆری سیستەمی سپرینکلەر:","• بۆریی تەڕ (Wet Pipe): بۆرییەکان هەمیشە پڕن لە ئاو — خێراترین وەڵامدانەوە و بڵاوترین جۆر.","• بۆریی وشک (Dry Pipe): بۆرییەکان پڕن لە هەوا یان نایترۆجینی پەستاندار — بۆ ئەو شوێنانەی پلەی گەرمی تێیاندا لە ٤°C دادەبەزێت.","• پێش-کارکردن (Pre-action): ڤاڵڤەکە تەنها دوای ناسینەوەی ئاگر بە دیتێکتەرەکان دەکرێتەوە، پاشان سەری سپرینکلەرەکە بە گەرمی دەکرێتەوە — بۆ شوێنی ئامێرە هەستیارەکان.","• Deluge: سەرەکان کراوەن، و هەموویان پێکەوە ئاو دەپرژێنن — بۆ شوێنە بەرز مەترسییەکان.","پلەی گەرمیی کرانەوە (Activation Temperature) و ڕەنگی گڵۆپە شووشەییەکە:","• ٥٧°C (پرتەقاڵی): پلەی ئاسایی (Ordinary) — ئەو شوێنانەی پلەی گەرمییان نزمە.","• ٦٨°C (سوور): پلەی ئاسایی (Ordinary) — بڵاوترین لە نووسینگە و کارگەکاندا.","• ٧٩°C (زەرد) و ٩٣°C (سەوز): پلەی مامناوەند (Intermediate) — شوێنە گەرمترەکان.","• ١٤١°C (شین): پلەی بەرز (High) — ژوورەکانی بۆیلەر و نزیک ئامێرە گەرمەکان.","ڕووبەری پاراستن بۆ هەر سەرێکی ئاسایی (Standard Spray): تا نزیکەی ٢١ m² (Light)، ١٢ m² (Ordinary) و ٩ m² (Extra Hazard).","چڕیی ئاو (Density): 0.10-0.40 gpm/ft² (نزیکەی ٤-١٦ mm/min) بەپێی ئاستی مەترسی.","NFPA 25: پشکنین و تاقیکردنەوە بە خشتەی هەفتانە، مانگانە، ساڵانە و ٥ ساڵانە.","سپرینکلەرەکان تەنها لە شوێنی ئاگرەکەدا دەکرێنەوە؛ هەموو سەرەکان پێکەوە ناکرێنەوە (جگە لە سیستەمی Deluge)."]},{heading:"٣. سیستەمەکانی کەف — NFPA 11 / 16",body:"بۆ کۆگا گەورەکانی شلەمەنی:",points:["٣ جۆری کەف بەپێی ڕێژەی فراوانبوون (Expansion):","• کەم (Low-Expansion، تا 20:1): ئاگری تانکەکان و ڕژانی شلەمەنی.","• مامناوەند (Medium-Expansion، 20:1 تا 200:1): شوێنەکانی دیواری ڕاگرتن.","• بەرز (High-Expansion، 200:1 تا 1000:1): هەنگارەکانی فڕۆکە و شوێنە گەورە داخراوەکان.","جۆرەکانی ماددەی کەف (Concentrate):","• AFFF: بۆ هایدرۆکاربۆنەکان (بەنزین، دیزڵ).","• AR-AFFF (Alcohol-Resistant): بۆ سۆڵڤێنتە پۆلارەکان (ئەلکهول، ئەسیتۆن).","• Fluoroprotein: بۆ تانکەکانی هەڵگرتن.","• کەفی بێ فلۆر (Fluorine-Free Foam — F3): جێگرەوەی کەفەکانی PFAS.","ڕێژەی بەکارهێنان (Application Rate):","• ڕژانی هایدرۆکاربۆنەکان: لانیکەم نزیکەی ٤٫١ L/min/m² (0.10 gpm/ft²).","• سۆڵڤێنتە پۆلارەکان: بەپێی لیستکردنی بەرهەمهێنەر، بە گشتی بەرزتر.","مەترسیی PFAS: AFFF ماددەی فلۆرینی (PFAS) ی تێدایە کە لە لەش و ژینگەدا کۆ دەبنەوە؛ زۆر وڵات بەرەو کەفی بێ فلۆر (F3) دەچن.","لە کارگەکاندا: کۆمەڵگاکانی تانک، شوێنەکانی بارکردنی تانکەر و پاڵاوگەکان."]},{heading:"٤. سیستەمەکانی CO₂ و Clean Agent — NFPA 12 / 2001",body:"بۆ ژوورەکانی ئامێر و پڕکردنەوەی تەواو (Total Flooding):",points:["پڕکردنەوەی تەواو بە CO₂:","• چڕیی دیزاین: لانیکەم ٣٤٪ (NFPA 12)، و بۆ هەندێک ماددە زیاتر.","• مەترسی: چڕیی کوژاندنەوە بۆ مرۆڤ کوشندەیە — نابێت هیچ کەسێک لە ژوورەکەدا بمێنێتەوە.","• زەنگی پێش-بەردان و ماوەی چاوەڕوانی (Time Delay): دەبێت بەس بێت بۆ چۆڵکردنی ژوورەکە پێش بەردانی گازەکە (NFPA 12).","• بەکارهێنان: ژوورەکانی مۆلیدە، شوێنەکانی تاقیکردنەوەی بزوێنەر و ئامێرەکانی چاپ.","Clean Agent (FK-5-1-12 / HFC-227ea):","• NOAEL: لەو شوێنانەی کەسیان لێیە، چڕیی دیزاین لە ئاستی بێ زیان (NOAEL) تێناپەڕێت (NFPA 2001)؛ لەگەڵ ئەوەشدا ژوورەکە چۆڵ بکە.","• چڕیی دیزاین: بە گشتی نزیکەی ٤-٩٪ بەپێی جۆری ماددەکە.","• بەردان (Discharge): ماددە هالۆکاربۆنییەکان لە ماوەی ١٠ چرکەدا (NFPA 2001).","• بەکارهێنان: ژوورەکانی سێرڤەر، کۆنترۆڵ و سویچ.","• نرخەکەی زۆر لە سیستەمەکانی ئاو بەرزترە.","Halon 1301: بەرهەمهێنانی بەپێی پرۆتۆکۆڵی مۆنتریاڵ لە ١٩٩٤ ەوە لە وڵاتە پێشکەوتووەکاندا ڕاگیراوە، چونکە چینی ئۆزۆن تێکدەدات؛ سیستەمی نوێی پێ دانانرێت.","تاقیکردنەوەی هایدرۆستاتیکیی ئاگرکوژێنەرەوە دەستییەکان (NFPA 10): CO₂ هەر ٥ ساڵ جارێک، Clean Agent هەر ١٢ ساڵ جارێک؛ سیلیندەرەکانی سیستەمە جێگیرەکان بەپێی NFPA 12 / 2001 و یاساکانی سیلیندەر."]},{heading:"٥. سیستەمەکانی تۆزی وشک — NFPA 17",body:"بۆ مەترسییە تایبەتەکان:",points:["سیستەمە ئامادەکراوەکان (Pre-Engineered Systems):","• چێشتخانە بازرگانییەکان: ئێستا بە گشتی سیستەمەکانی Wet Chemical (NFPA 17A) بەکاردەهێنرێن، نەک تۆزی وشک.","• ژوورەکانی ڕەنگکردن (Spray Booths).","• پاراستنی ئامێر و ئۆتۆمبێلە قورسەکان.","• تانکەکانی نوقمکردن (Dip Tanks).","ماددەکان (Agents):","• بیکاربۆناتی سۆدیۆم (Sodium Bicarbonate): B، C.","• بیکاربۆناتی پۆتاسیۆم (Purple-K): B، C — لەسەر ئاگری پۆلی B لە بیکاربۆناتی سۆدیۆم بەهێزترە.","• فۆسفاتی ئەمۆنیۆم (Monoammonium Phosphate): A، B، C.","• کلۆریدی پۆتاسیۆم (Potassium Chloride): B، C.","کرانەوە (Activation): دیتێکتەری گەرمی یان دەسکێکی دەستی (Manual Pull).","دوای بەردان: تۆزەکە لە هەموو شوێنێک بڵاو دەبێتەوە و دەتوانێت زیان بە ئامێرە ئەلیکترۆنییەکان بگەیەنێت؛ پاککردنەوەی قورسە.","ڕووبەری پاراستنی هەر لوولەیەک (Nozzle) بەپێی لیستکردنی سیستەمەکە دیاری دەکرێت."]},{heading:"٦. ناسینەوەی ئاگر — NFPA 72",body:"سیستەمی ناسینەوە — یەکەم هێڵی ئاگادارکردنەوە:",points:["جۆرەکانی دیتێکتەر:","• دووکەڵ: فۆتۆئەلیکتریک (Photoelectric) بۆ ئاگری هێواش (Smoldering)، ئایۆنیزەیشن (Ionization) بۆ ئاگری بڵێسەدار (Flaming).","• گەرمی: پلەی جێگیر (Fixed Temperature، وەک ٥٧°C) یان بەرزبوونەوەی خێرا (Rate-of-Rise).","• بڵێسە (Flame): UV/IR — بڵێسە بە خێرایی دەناسنەوە.","• گاز: دیتێکتەرەکانی LEL و هەستەوەرەکانی CO.","• کێشانی نموونەی هەوا (Air-Sampling): بۆ ژوورەکانی سێرڤەر — هەستیارترین جۆر.","دووری و ڕووبەر:","• دووکەڵ: دووریی نێوان دیتێکتەرەکان نزیکەی ٩ مەتر (30 ft) لەسەر بنمیچی ڕێک (NFPA 72).","• گەرمی: بەپێی دووریی لیستکراوی دیتێکتەرەکە (Listed Spacing).","• بڵێسە: بەپێی گۆشەی بینین و دووریی لیستکراوی ئامێرەکە.","ئاگادارکردنەوە (Alarm Notification):","• دەنگ (Audible): بە گشتی لانیکەم ١٥ dB لە تێکڕای دەنگی شوێنەکە بەرزتر (NFPA 72).","• ڕووناکی (Strobe): بۆ شوێنە پڕ ژاوەژاوەکان و بۆ ئەو کەسانەی کەمیی بیستنیان هەیە.","• ئاگادارکردنەوەی دەنگی (Voice / Mass Notification): بۆ بینا و کارگە گەورەکان.","پشکنین و تاقیکردنەوە: بەپێی خشتەکانی NFPA 72 (زۆرێک لە ئامێرەکان ساڵی جارێک تاقی دەکرێنەوە)."]},{heading:"٧. خشتەی پشکنین و چاکسازی",body:"بەپێی ستانداردەکانی NFPA:",points:["ڕۆژانە / هەفتانە:","• پشکنینی بینراو (پەستانی گەیجەکان، زیان).","• پشکنینی ئەوەی کە هیچ شتێک نەکەوتبێتە بەردەم سپرینکلەرەکان.","• هەڵکردنی پەمپی ئاگر بەبێ کردنەوەی ئاو (No-flow Test): پەمپی دیزڵ هەموو هەفتەیەک، هی کارەبا بە گشتی هەموو مانگێک (NFPA 25).","مانگانە:","• پشکنینی بینراوی ئاگرکوژێنەرەوە دەستییەکان (NFPA 10).","• پشکنینی پانێڵی زەنگی ئاگر و نیشانەکانی هەڵە (Trouble).","• پشکنینی دوگمەکانی زەنگ (Manual Pull Stations) — دیار و نەگیراو بن.","ساڵانە:","• چاکسازیی ساڵانەی ئاگرکوژێنەرەوە دەستییەکان لەلایەن کەسی شارەزاوە (نەک تاقیکردنەوەی هایدرۆستاتیکی).","• پشکنینی سپرینکلەرەکان لەسەر زەوییەوە (NFPA 25).","• نموونەی ماددەی کەف بۆ تاقیکردنەوە.","• تاقیکردنەوەی دیتێکتەر و زەنگەکان (NFPA 72).","هەر چەند ساڵ جارێک:","• تاقیکردنەوەی هایدرۆستاتیکیی ئاگرکوژێنەرەوەکان (تاقیکردنەوەی پەستانی لەشیان، NFPA 10): هەر ٥ ساڵ بۆ ئاو، کەف، Wet Chemical، CO₂ و تۆزی وشکی ستێنلێس ستیل (stainless steel)؛ هەر ١٢ ساڵ بۆ تۆزی وشکی پەستانی هەڵگیراو (stored-pressure) کە لەشی لە پۆڵای ئاسایی (mild steel)، بڕنجی لەحیمکراو (brazed brass) یان ئەلەمنیۆمە، و بۆ Clean Agent. بە جیا، هەر ٦ ساڵ جارێک، ئاگرکوژێنەرەوەکانی تۆزی وشکی پەستانی هەڵگیراو کە پێویستیان بە تاقیکردنەوەی ١٢ ساڵە هەیە، لەلایەن کەسی شارەزاوە بەتاڵ دەکرێنەوە و ناوەوەیان دەپشکنرێت. ڕێساکانی دهۆک هێشتا پشتڕاست نەکراونەتەوە.","• پشکنینی ناوەوەی بۆرییەکانی سپرینکلەر: هەر ٥ ساڵ جارێک (NFPA 25).","• گۆڕین یان تاقیکردنەوەی نموونەی سەرەکانی سپرینکلەر دوای ٥٠ ساڵ (سەرە ئاساییەکان — NFPA 25).","تۆمارکردن: هەموو پشکنین و تاقیکردنەوەکان بنووسە و تۆمارەکان بەپێی ستانداردەکان و داواکاریی دەزگا پەیوەندیدارەکان بپارێزە."]}],media:[{kind:"video",src:"media/videos/fact_sprinkler_demo.mp4",title:"کرانەوەی سپرینکلەر",description:"نمایشی سپرینکلەر"},{kind:"image",src:"media/images/fact_systems_chart.png",title:"خشتەی سیستەمەکانی کوژاندنەوە",description:"سیستەمە جێگیرەکان"}],quiz:[{question:"بۆ زۆربەی کارگەکان، گرنگترین سیستەمی جێگیر کامەیە؟",options:[{text:"ئاگرکوژێنەرەوە دەستییەکان",correct:!1},{text:"سپرینکلەر (NFPA 13)",correct:!0},{text:"تەنها CO₂",correct:!1},{text:"هیچ کامیان",correct:!1,fixed:!0}],explanation:"سپرینکلەرەکان خۆکارانە کار دەکەن و ئاگر لە قۆناغی سەرەتاییدا کۆنترۆڵ دەکەن، تەنانەت کاتێک کەس لە شوێنەکەدا نییە؛ ئاگرکوژێنەرەوە دەستییەکان تەنها بۆ ئاگری بچووکن."},{question:"سیستەمی بۆریی تەڕ (Wet Pipe) بۆ کام شوێن گونجاو نییە؟",options:[{text:"ژوورەکانی ئامێر (ICT)",correct:!1},{text:"نووسینگە",correct:!1},{text:"ئەو شوێنانەی پلەی گەرمی تێیاندا لە ٤°C دادەبەزێت",correct:!0},{text:"کۆگا",correct:!1}],explanation:"لە شوێنە ساردەکاندا ئاو لە ناو بۆرییەکاندا دەیبەستێت؛ سیستەمی بۆریی وشک (Dry Pipe) گونجاوە."},{question:"ئایا سیستەمی نوێ بە Halon 1301 دادەنرێت؟",options:[{text:"بەڵێ",correct:!1},{text:"نەخێر — بەرهەمهێنانی بەپێی پرۆتۆکۆڵی مۆنتریاڵ ڕاگیراوە",correct:!0},{text:"تەنها لە ژوورەکانی ICT",correct:!1},{text:"تەنها لە ژوورەکانی سێرڤەر",correct:!1}],explanation:"Halon 1301 چینی ئۆزۆن تێکدەدات؛ بەرهەمهێنانی لە وڵاتە پێشکەوتووەکاندا لە ١٩٩٤ ەوە ڕاگیراوە."},{question:"بۆچی دەبێت هەموو کەسێک پێش بەردانی سیستەمی CO₂ ی پڕکردنەوەی تەواو لە ژوورەکە بچێتە دەرەوە؟",options:[{text:"پێویست ناکات، CO₂ بێ زیانە",correct:!1},{text:"چونکە چڕیی کوژاندنەوە (٣٤٪ و زیاتر) بۆ مرۆڤ کوشندەیە",correct:!0},{text:"چونکە CO₂ ئاو دەپرژێنێت",correct:!1},{text:"چونکە CO₂ دەنگێکی بەرز دروست دەکات",correct:!1}],explanation:"چڕیی دیزاینی CO₂ لە سیستەمەکانی پڕکردنەوەی تەواودا لانیکەم ٣٤٪ ە (NFPA 12)، و ئەم چڕییە لە ماوەیەکی کورتدا مرۆڤ بێهۆش دەکات و دەیکوژێت؛ بۆیە زەنگی پێش-بەردان و ماوەی چاوەڕوانی هەن."},{question:"ڕووبەری پاراستنی هەر سەرێکی سپرینکلەر (Standard Spray) نزیکەی چەندە؟",options:[{text:"٢-٥ m²",correct:!1},{text:"١٢-٢١ m²",correct:!0},{text:"٥٠ m²",correct:!1},{text:"١٠٠ m²",correct:!1}],explanation:"بەپێی NFPA 13: نزیکەی ٢١ m² بۆ مەترسیی کەم و ١٢ m² بۆ مەترسیی ئاسایی؛ بۆ مەترسیی زیاد کەمترە (نزیکەی ٩ m²)."},{question:"تاقیکردنەوەی هەفتانەی پەمپی ئاگری دیزڵ چییە؟",options:[{text:"تەنها پشکنینی بینراو",correct:!1},{text:"هەڵکردنی پەمپەکە بەبێ کردنەوەی ئاو (Start / No-flow Test)",correct:!0},{text:"تاقیکردنەوەی هایدرۆستاتیکی",correct:!1},{text:"هیچ کامیان",correct:!1,fixed:!0}],explanation:"NFPA 25: پەمپی دیزڵ هەموو هەفتەیەک و پەمپی کارەبا بە گشتی هەموو مانگێک بەبێ کردنەوەی ئاو هەڵدەکرێن و تاقی دەکرێنەوە."}]},{id:22,code:"BUS-122",icon:"Building2",accent:"#0f766e",title:"سەلامەتی لە ئاگر لە دوکان، بازاڕ و مۆڵەکاندا",subtitle:"دەرچوون، کۆگا، کارەبا، گازی LPG و ڕۆڵی کارمەندان لە باری نائاساییدا",summary:"دوکان، بازاڕ و مۆڵەکان پڕن لە کڕیار کە بیناکە ناناسن، لە کاڵای ئاسان ئاگرگر، لە ئامێری کارەبایی و زۆرجار لە سلیندەری گازی LPG. ئەم وانەیە بۆ خاوەن، بەڕێوەبەر و کارمەندانە: چۆن دەرچوونەکان و ئامێرەکانی ئاگر کراوە و بێ بەربەست ڕابگرن، چۆن ڕێگری لە ئاگری کارەبا و گاز بکەن، و هەر کارمەندێک کاتێک ئاگادارکەرەوەی ئاگر لێدەدات چی دەکات. ڕێساکانی مۆڵەت و پشکنینی ناوخۆیی لەلایەن بەرگریی شارستانی و لایەنی مۆڵەتدەرەوە دادەنرێن؛ داواکارییەکانیان جێبەجێ بکەن.",blocks:[{heading:"١. دەرچوون، ڕێگاکانی دەرچوون و کۆگا",body:"کڕیاران بە گشتی هەوڵ دەدەن لەو ڕێگایەوە دەربچن کە پێیدا هاتوون، بۆیە هەموو ڕێگاکانی دەرچوون دەبێت هەمیشە ئامادە بن:",points:["دەرچوون، ڕاڕەو و پلیکانەکان بە تەواوی چۆڵ ڕابگرە: هیچ کاڵا، کارتۆن، عەرەبانە یان مێزی فرۆشتن لەسەر ڕێگا نەبێت، تەنانەت بۆ ماوەیەکی کورتیش.","دەرگاکانی دەرچوون دەبێت هەر کاتێک خەڵک لە ناوەوە بن، یەکسەر لە ناوەوە بکرێنەوە، بەبێ کلیل و بەبێ کۆد؛ پێش کردنەوەی دوکان زنجیر، شیش و قفڵی زیادە لابەرە.","نیشانەکانی دەرچوون دیار ڕابگرە: نابێت کاڵا، پۆستەر و ڕازاندنەوە دەرگای دەرچوون یان نیشانەکەی بشارنەوە.","کاڵای زیادە لە کۆگادا دابنێ، نەک لە ڕاڕەوەکان، ژێر پلیکانە یان ئەو شوێنانەی کڕیار پێیاندا هاتوچۆ دەکەن.","کاڵا، کارتۆن یان کەرەستەی پێچانەوە لە تەنیشت تابلۆی کارەبا، گڵۆپ، سۆبە یان ئامێری چێشتلێنان کەڵەکە مەکە.","لە بازاڕ یان مۆڵدا، لەگەڵ بەڕێوەبەرایەتی لەسەر دەرچوونە هاوبەشەکان، ئاگادارکەرەوەی ئاگر و خاڵی کۆبوونەوە ڕێک بکەوە، و بەشداری لە ڕاهێنانە هاوبەشەکاندا بکە."]},{heading:"٢. کارەبا: بارگرانی و وایەری درێژکەرەوە",body:"پلاکی بارگران و وایەری گەرمبوو لە هۆکارە باوەکانی ئاگرن لە دوکانەکاندا:",points:["پلاک و پلاکی زیادە (Power strip) بارگران مەکە، و ئەو پلاکە زیادانە بەکاربهێنە کە پاراستنیان لە بارگرانی تێدایە.","وایەری درێژکەرەوە (Extension lead) تەنها بۆ کاری کاتییە و هەرگیز جێگەی وایەری جێگیری بینا ناگرێتەوە؛ ئەگەر پێویستت بە پلاکی زیاتر هەبوو، با کارەباچییەکی شارەزا دایانبنێت.","سەلاجە، فریزەر، سۆبە، فڕن و ئامێرە گەورەکانی تر ڕاستەوخۆ بە پلاکی دیوارەوە ببەستە، هەرگیز بە وایەری درێژکەرەوە.","وایەر لە ژێر فەرش و ڕایەخ، بە ناو دەرگاکاندا یان بە سەر ڕاڕەوەکاندا ڕامەکێشە، چونکە لەوانەیە بپلیشێنەوە یان خەڵک پێیانەوە بکەون.","وایەر و فیشی تێکچوو یەکسەر بگۆڕە. بۆنی سووتان، فیشێکی گەرم، پریشک یان بڕەکەرێک (Breaker) کە بەردەوام دەکەوێت، واتە: کارەباکە ببڕە و کارەباچییەکی شارەزا بانگ بکە."]},{heading:"٣. سلیندەری گازی LPG لە دوکان و بازاڕەکاندا",body:"گازی LPG لە هەوا قورسترە: گازی دزەکردوو لە نزیک زەوی و لە شوێنە نزمەکانی وەک ئاوەڕۆ و نهۆمی ژێرزەوی کۆ دەبێتەوە.",points:["لە دوکانەکەدا تەنها کەمترین ژمارەی سلیندەر ڕابگرە کە کارەکەت پێویستی پێیەتی؛ ئەوانی تر لە کۆگایەکی جیا و هەوادار دابنێ، باشترە لە دەرەوە لە هەوای کراوەدا.","هەرگیز سلیندەر لە ژێر ئاستی زەوی، لە نهۆمی ژێرزەوی یان لە نزیک ئاوەڕۆ دامەنێ.","سلیندەرەکان بە ڕاوەستاوی و سەری سەمامەی پارێزراو دابنێ، لە شوێنێک کە دەستی کڕیار پێی نەگات، دوور لە گەرما، ئاگر و شتی ئاگرگر.","هەرگیز سلیندەر لەسەر پلیکانە، لە تەنیشت دەرگای دەرچوون یان لە هەر شوێنێک کە ڕێگای دەرچوون بگرێت دامەنێ.","تەنها تەکنیکارێکی شارەزا ڕێگولەیتەر، لوولە و ئامێرەکان دەبەستێتەوە. هەرگیز بە ئاگر بەدوای دزەی گازدا مەگەڕێ.","ژمارەی ئەو سلیندەرانەی دوکانێک دەتوانێت ڕایانبگرێت و شوێنیان، لەلایەن بەرگریی شارستانی و لایەنی مۆڵەتدەرەوە دیاری دەکرێت."]},{heading:"٤. ئەگەر بۆنی گازت کرد",body:`١. هیچ ئاگرێک دامەگیرسێنە و هیچ گڵۆپ، ئامێر یان مەکینەیەک هەڵمەکە و مەکوژێنەرەوە. لە ناو شوێنەکەدا تەلەفۆن بەکارمەهێنە.
٢. فرۆشتن ڕابگرە و بە ئارامی کڕیار و کارمەندان لە نزیکترین دەرچوونەوە دەربهێنە.
٣. سەمامەی گاز تەنها دابخە ئەگەر لە نزیکت بوو و توانیت پێی بگەیت بەبێ ئەوەی بچیتە ئەو شوێنەی گازی تێدا کۆبووەتەوە و بەبێ هیچ پریشکێک؛ ئەگەر نا، لێی نزیک مەبەوە.
٤. خەڵک لە دەرگاکە دوور بخەرەوە و دوکانە دراوسێکان ئاگادار بکەرەوە.
٥. لە دەرەوە پەیوەندی بە ١١٥ بکە، و مەهێڵە کەس بگەڕێتەوە ژوورەوە تا پسپۆڕان نەڵێن سەلامەتە.`,critical:!0},{heading:"٥. ڕۆڵی کارمەندان کاتێک ئاگادارکەرەوەی ئاگر لێدەدات",body:"هەر کارمەندێک پێش باری نائاسایی ڕۆڵی خۆی دەزانێت. پلانی باری نائاسایی بۆ هەر ئەرکێک لە هەر دەوامێکدا کەسێک دیاری دەکات:",points:["ئاگادارکردنەوە: بە دەنگی بەرز بڵێ «ئاگر!»، ئەگەر دوگمەی ئاگادارکەرەوەی ئاگر (Call point) هەبوو نزیکترینیان دابگرە، و دڵنیابە کە کەسێک لە شوێنێکی سەلامەتەوە پەیوەندی بە ١١٥ دەکات.","ڕێنماییکردنی کڕیاران: فرۆشتن ڕابگرە، بە ئارامی بە کڕیاران بڵێ دەربچن و نزیکترین دەرچوونیان نیشان بدە، نەک تەنها دەرگای سەرەکی.","پشکنین: تەوالێت، ژووری تاقیکردنەوەی جل، کۆگا و نووسینگەکان لە ڕێگای دەرچووندا بپشکنە، تەنها ئەگەر سەلامەت بوو، و دەرگاکان لە دوای خۆتەوە دابخە.","یارمەتیدان: یارمەتی ئەوانە بدە کە پێویستیان پێیەتی، وەک بەتەمەنان، منداڵی بێ هاوەڵ و کەسانی خاوەن پێداویستیی تایبەت. هەرگیز ئاسانسۆر بەکارمەهێنە.","لە خاڵی کۆبوونەوە: کارمەندان بژمێرە، هەر کەسێکی ون ڕابگەیەنە، و بە ئاگرکوژەکان بڵێ لەوانەیە خەڵک لە کوێ مابن و دەربارەی سلیندەری گاز و مەترسییەکانی تر.","کەس ناگەڕێتەوە ژوورەوە تا بەرگریی شارستانی نەڵێت سەلامەتە."]},{heading:"٦. دەرهێنانی قەرەباڵغی بە سەلامەتی",body:"لە دوکان یان مۆڵێکی قەرەباڵغدا، شێوەی ڕێنماییکردنی کارمەندان دیاری دەکات کە هەمووان چەند بە خێرایی دەردەچن:",points:["بە ئارامی قسە بکە و ڕێنمایی کورت و ڕوون بدە، وەک: «لەم دەرچوونەوە دەربچن. بە پێ بڕۆن، ڕامەکەن.»","هەموو دەرچوونە بەردەستەکان بەکاربهێنە، و ئەگەر دەرچوونێک قەرەباڵغ بوو یان دووکەڵ گرتی، خەڵک بەرەو دەرچوونێکی تر ڕێنمایی بکە.","مەهێڵە خەڵک بۆ پارەدان، کۆکردنەوەی کاڵا یان گەڕانەوە بۆ ژوورەوە بوەستن.","ژمارەی خەڵکی ناوەوە لە سنووری دیاریکراوی بیناکەدا ڕابگرە، بە تایبەتی لە جەژن و ڕۆژانی داشکاندندا.","لە مۆڵدا، ڕێنماییەکانی تیمی باری نائاسایی مۆڵەکە و ڕاگەیاندنەکان جێبەجێ بکە، و بە دوورییەکی باش لە بیناکە بڕۆ بۆ خاڵی کۆبوونەوە."]},{heading:"٧. ئامێرەکانی ئاگر، جانتای فریاکەوتنی سەرەتایی و AED",body:"ئامێرەکان تەنها ژیان ڕزگار دەکەن ئەگەر خەڵک بیانبینن، پێیان بگەن و بتوانن بەکاریان بهێنن:",points:["ئاگرکوژێنەرەوە، دوگمەکانی ئاگادارکەرەوەی ئاگر و بەتانیی ئاگر دیار، لە شوێنی خۆیان و بێ بەربەست ڕابگرە؛ هەموو ڕۆژێک بپشکنە کە هیچ شتێک لە بەردەمیاندا نییە.","ئاگرکوژێنەرەوە تەنها بەکاربهێنە ئەگەر ڕاهێنانت کردبێت، ئاگرەکە بچووک و لە سەرەتادا بێت، لەیبڵەکە نیشانی بدات کە بۆ ئەم ئاگرە گونجاوە، خەڵک ئاگادار کرابنەوە، پەیوەندی بە ١١٥ کرابێت و ڕێگای دەرچوونت لە پشتتەوە بێت. ئەگەر نا، دەربچۆ و دەرگاکە دابخە.","هەر ئاگرکوژێنەرەوەیەک هەموو مانگێک پێویستی بە پشکنینێکی چاوی هەیە (لە شوێنی خۆیدا، سنجاقی سەلامەتی و مۆر ساغ، پێوەری پەستان لە ناوچەی سەوزدا، بێ زیان) و بە خزمەتگوزاری لەلایەن کەسێکی شارەزاوە؛ خشتەی ناوخۆیی لەلایەن بەرگریی شارستانییەوە دادەنرێت.","جانتایەکی فریاکەوتنی سەرەتایی تەواو لە شوێنێک دابنێ کە کارمەندان بە خێرایی پێی بگەن، و بزانە کێ لە هەر دەوامێکدا ڕاهێنانی فریاکەوتنی سەرەتایی کردووە.","ئەگەر دوکانەکە یان مۆڵەکە ئامێری شۆکی دڵ (AED)ی هەبوو، هەموو کارمەندان دەزانن لە کوێیە. ئەگەر کەسێک کەوت و بە ئاسایی هەناسەی نەدا: پەیوەندی بە ١٢٢ بکە، پەستانی سنگ (CPR) دەست پێ بکە و یەکسەر کەسێک بنێرە بۆ هێنانی AED."]}],media:[{kind:"image",src:"media/images/w8_shop_evacuation.webp",title:"دەرهێنانی کڕیاران لە دوکان",description:"کارمەندێک کڕیاران بەرەو نزیکترین دەرچوون دەبات و هاوکارەکەی کۆگاکە دەپشکنێت"}],quiz:[{question:"کۆگاکە پڕە و بارێکی نوێی کاڵا گەیشت. کارتۆنە زیادەکان دەتوانرێت لە کوێ دابنرێن؟",options:[{text:"لە ڕاڕەوی دەرچوونی ئاگردا، تەنها تا کۆتایی ڕۆژی کار",correct:!1},{text:"لە ژێر پلیکانەکاندا، تا ئەو کاتەی کڕیار نەیانبینن",correct:!1},{text:"لە کۆگایەکی تر یان شوێنێکی دوور لە دەرچوون و ڕاڕەوەکان",correct:!0},{text:"لە بەردەم ئاگرکوژێنەرەوەکەدا، چونکە شوێنی بەتاڵی لێیە و نزیکە",correct:!1}],explanation:"دەرچوون، ڕاڕەو و پلیکانەکان دەبێت هەمیشە چۆڵ بن، تەنانەت بۆ ماوەیەکی کورتیش، و نابێت هیچ شتێک ئامێرەکانی ئاگر بگرێت. کاڵای زیادە دەچێتە کۆگایەک دوور لە دەرچوون و ڕاڕەوەکان."},{question:"سەلاجەیەکی نوێی نمایشکردن پێویستی بە کارەبایە. ڕێگای سەلامەتی بەستنەوەی کامەیە؟",options:[{text:"بەو پلاکە زیادەیەوە ببەستە کە گڵۆپ و سندوقی پارەی پێوە بەستراوە",correct:!1},{text:"ڕاستەوخۆ بە پلاکی دیوارەوە؛ ئەگەر پێویست بوو کارەباچی پلاک زیاد دەکات",correct:!0},{text:"وایەری درێژکەرەوە لە ژێر فەرشەکەوە ڕابکێشە بۆ ئەوەی کەس پێیەوە نەکەوێت",correct:!1},{text:"دوو وایەری درێژکەرەوە پێکەوە ببەستە بۆ گەیشتن بە پلاکی لای دەرگاکە",correct:!1}],explanation:"ئامێرە گەورەکان ڕاستەوخۆ بە پلاکی دیوارەوە دەبەسترێن. وایەری درێژکەرەوە کاتییە و بە ئاسانی بارگران دەبێت، و وایەری ژێر فەرش لەوانەیە بپلیشێتەوە و گەرم ببێت."},{question:"کارمەندان بۆنێکی بەهێزی گاز لە نزیک سلیندەرەکانی دوکان دەکەن، و سەمامەکە لە ناوەڕاستی بۆنەکەدایە. چی دروستە؟",options:[{text:"بڕۆ بۆ لای سەمامەکە، دایبخە و پانکەکە هەڵبکە بۆ دەرکردنی گازەکە",correct:!1},{text:"گڵۆپەکان هەڵبکە بۆ دۆزینەوەی دزەکە و لوولەکە بە چەرخ تاقی بکەرەوە",correct:!1},{text:"لە ناو دوکانەکەوە پەیوەندی بە کۆمپانیای گاز بکە لە کاتی گەڕان بەدوای دزەکەدا",correct:!1},{text:"لە سەمامەکە دوور بکەوەرەوە، هەمووان دەربهێنە و لە دەرەوە پەیوەندی بە ١١٥ بکە",correct:!0}],explanation:"سەمامە تەنها دادەخرێت ئەگەر بەبێ چوونە ناو گازەکە و بەبێ هیچ پریشکێک بتوانیت پێی بگەیت. لێرەدا ناتوانیت، بۆیە کەس لێی نزیک نابێتەوە: بێ سویچ، بێ تەلەفۆن لە ناوەوە، هەمووان دەردەچن و لە دەرەوە پەیوەندی بە ١١٥ دەکرێت."},{question:"ئاگادارکەرەوەی ئاگر لە دوکانێکی قەرەباڵغدا لێدەدات. ئەو کارمەندەی بەرپرسی تەوالێت و کۆگاکانە چی دەکات؟",options:[{text:"ئەگەر سەلامەت بوو لە ڕێگادا دەیانپشکنێت و لە خاڵی کۆبوونەوە ڕایدەگەیەنێت",correct:!0},{text:"لای سندوقی پارە دەمێنێتەوە بۆ تەواوکردنی هەموو فرۆشتنەکان پێش دەرچوون",correct:!1},{text:"کۆگاکان قفڵ دەکات بۆ ئەوەی کەس لە کاتی ئاگرەکەدا هیچ کاڵایەک نەبات",correct:!1},{text:"دوای ژماردن بە تەنها دەگەڕێتەوە ناو بیناکە بۆ گەڕان بەدوای کەسانی ون",correct:!1}],explanation:"پشکنینی تەوالێت و کۆگاکان لە ڕێگای دەرچووندا، تەنها ئەگەر سەلامەت بوو، دڵنیا دەکاتەوە کە کەس بەجێ نەماوە. ئەنجامەکە لە خاڵی کۆبوونەوە ڕادەگەیەنرێت؛ کەس ناگەڕێتەوە ژوورەوە."},{question:"لە کاتی دەرهێناندا، کڕیاران لە دەرگای سەرەکی قەرەباڵغ دەبن و دەرچوونێکی تر چۆڵە. کارمەندان چی دەکەن؟",options:[{text:"بە هەمووان دەڵێن لە ناو دوکانەکەدا چاوەڕێ بکەن تا دەرگای سەرەکی چۆڵ دەبێت",correct:!1},{text:"بە ئارامی و بە ڕێنمایی کورت و ڕوون خەڵک بەرەو دەرچوونە چۆڵەکە دەبەن",correct:!0},{text:"ئاسانسۆرەکان دەکەنەوە بۆ ئەوەی خەڵکی زیاتر پێکەوە لە نهۆمەکە دەربچن",correct:!1},{text:"داوا لە کڕیاران دەکەن بە خێرایی پارە بدەن بۆ ئەوەی ڕیزەکە خێراتر بجووڵێت",correct:!1}],explanation:"خەڵک بە گشتی لەو ڕێگایەوە دەردەچن کە پێیدا هاتوون. کارمەندان هەموو دەرچوونە بەردەستەکان بەکاردەهێنن و بە ئارامی خەڵک بەرەو دەرچوونێکی چۆڵ دەبەن؛ ئاسانسۆر هەرگیز لە کاتی ئاگردا بەکارناهێنرێت."}]},{id:23,code:"BUS-123",icon:"CookingPot",accent:"#c2410c",title:"سەلامەتی لە ئاگر لە ڕێستوران و چێشتخانە بازرگانییەکاندا",subtitle:"ئاگری ڕۆن و چەوری، سیستەمی دووکەڵکێش، گاز و ڕاهێنانی کارمەندان",summary:"چێشتخانەی بازرگانی گەرما، ڕۆن، چەوری و گاز لە شوێنێکی تەسکدا پێکەوە کۆ دەکاتەوە، و ئاگرێک لە تاوەیەک یان فرایەرێکدا دەتوانێت لە چەند چرکەیەکدا بگاتە دووکەڵکێش (Hood) و بۆرییەکەی. ئەم وانەیە بۆ خاوەن، بەڕێوەبەر، ئاشپەز و کارمەندانی خزمەتگوزارییە: چۆن مامەڵە لەگەڵ ئاگری ڕۆن بکەن، سیستەمی کوژاندنەوەی ئاگری دووکەڵکێش چی دەکات، چۆن بە سەلامەتی گاز بەکاربهێنن، بۆچی دەبێت چەوری پاک بکرێتەوە و چۆن کڕیاران دەربهێنن. داواکارییەکانی بەرگریی شارستانی و لایەنی مۆڵەتدەر جێبەجێ بکەن.",blocks:[{heading:"١. ئاگری ڕۆن و چەوری: هەرگیز ئاو نا",body:"ڕۆن و چەوریی گڕگرتوو پێویستی بە مامەڵەیەکی تایبەت هەیە:",points:["هەرگیز ئاو مەکە سەر ڕۆن یان چەوریی گڕگرتوو: ئاوەکە یەکسەر دەبێتە هەڵم و ڕۆنی گڕگرتوو وەک تۆپێکی ئاگر فڕێ دەدات.","تاوە یان فرایەری گڕگرتوو هەڵمەگرە و مەیجووڵێنە.","ئاگرێکی بچووک لە تاوەدا: تەنها ئەگەر بە سەلامەتی پێی بگەیت، گەرما یان گاز لەسەر ئامێرەکە ببڕە، پاشان سەرپۆشێکی کانزایی بە سەر تاوەکەدا بکێشە یان بەتانیی ئاگری بدە بەسەردا، و لای مەبە تا سارد دەبێتەوە.","ئاگرکوژێنەرەوەی تۆزی ABC یان کەف بۆ فرایەر (Deep fryer) گونجاو نییە: ڕۆنەکە گەرم دەمێنێتەوە و دەتوانێت دووبارە گڕ بگرێتەوە.","ئەگەر ئاگرەکە بچووک نەبوو، گەیشتە دووکەڵکێش یان یەکسەر نەکوژایەوە: دەربچۆ، دەرگاکە دابخە و پەیوەندی بە ١١٥ بکە."],critical:!0},{heading:"٢. ئاگرکوژێنەرەوەی کیمیایی شل (پۆلی K / پۆلی F)",body:"پۆلەکانی ئاگر لێرەدا بە پیتەکانی NFPA 10 نووسراون وەک سەرچاوەی پرۆژە؛ سیستەمی فەرمیی دهۆک هێشتا پشتڕاست نەکراوەتەوە. هاوتاکانی EN 2: NFPA A = EN A؛ NFPA B (شلە) = EN B؛ NFPA B (گاز) = EN C؛ NFPA C (ئامێری کارەبایی کە کارەبای تێدایە) هیچ پۆلێکی EN ی نییە؛ NFPA D = EN D؛ NFPA K = EN F. بۆیە پۆلی K (NFPA) و پۆلی F (EN 2) یەک پۆلن: ڕۆن و چەوریی چێشتلێنان.",points:["ئاگرکوژێنەرەوەی کیمیایی شل (Wet Chemical) بۆ ڕۆن و چەوریی چێشتلێنان دروستکراوە: چینێکی وەک سابوون لەسەر ڕۆنەکە دروست دەکات کە هەوا دەبڕێت و ڕۆنەکە سارد دەکاتەوە.","ئەگەر چێشتخانەکە سیستەمی کوژاندنەوەی دووکەڵکێشی هەبوو، یەکەمجار سیستەمەکە کارپێبکە (خۆکارانە یان بە دەسکی کارپێکردنی دەستی)، و دوای ئەوە ئاگرکوژێنەرەوەکە بەکاربهێنە. نیشانەیەک لە تەنیشت ئاگرکوژێنەرەوەکە ئەمە دەڵێت.","پێش باری نائاسایی لەیبڵەکە بخوێنەرەوە: پۆل، مەودای کارکردن و چۆنیەتیی بەکارهێنان. هەندێک ئاگرکوژێنەرەوەی کیمیایی شل بە ڕێگایەکی جیاواز لە PASS کاریان پێدەکرێت؛ لەیبڵ و ڕێنماییەکانی کۆمپانیای دروستکەر جێبەجێ بکە.","تەنها بەکاری بهێنە ئەگەر ڕاهێنانت کردبێت، ئاگرەکە بچووک بێت، ئاگادارکەرەوەی ئاگر لێدرابێت و ڕێگای دەرچوونت لە پشتتەوە بێت.","ڕەنگی ئاگرکوژێنەرەوە پۆلەکەی نییە: هەمیشە لەیبڵەکە بخوێنەرەوە."]},{heading:"٣. سیستەمی کوژاندنەوەی ئاگری دووکەڵکێش",body:"زۆرێک لە چێشتخانە بازرگانییەکان سیستەمێکی جێگیری کوژاندنەوەی ئاگریان لە دووکەڵکێشدا هەیە لەسەر فرایەر، ئامێری برژاندن و تەباخەکان. کارمەندان خزمەتی ناکەن، بەڵام دەبێت هەمووان بزانن چۆن کار دەکات:",points:["کاتێک ئاگرێک لە ژێر دووکەڵکێشەکەدا سیستەمەکە گەرم دەکات، خۆی کار دەکات و ماددەیەکی کوژاندنەوە لە سەرە پرژێنەکانەوە (Nozzles) دەپرژێنێتە سەر ڕووی چێشتلێنان و ناو دووکەڵکێش و بۆرییەکەی.","کاتێک کار دەکات، گاز یان کارەبای ئامێرەکانی چێشتلێنانی ژێر دووکەڵکێشەکەش دەبڕێت. دواتر تەنها کەسێکی شارەزا دەیانگەڕێنێتەوە.","ئەگەر خۆی کاری نەکرد، دەسکی کارپێکردنی دەستی (Pull station) بەکاربهێنە. ئەو لەسەر ڕێگای دەرچوونە لە چێشتخانەکە، دەبێت هەموو ئاشپەزێک بزانێت لە کوێیە، و نابێت هیچ شتێک ڕێگای لێ بگرێت.","فلتەرەکانی دووکەڵکێش پاک و لە شوێنی خۆیاندا ڕابگرە. سەرە پرژێنەکان پاک ڕابگرە، و هەرگیز دایان مەپۆشە، مەیانچەمێنەوە و مەیانجووڵێنە.","ئامێرەکانی چێشتلێنانی ژێر دووکەڵکێش مەجووڵێنە، زیادیان مەکە و مەیانگۆڕە بەبێ ئەوەی دامەزرێنەری سیستەمەکە بیپشکنێت: سەرە پرژێنەکان بەرەو ئامێرە دیاریکراوەکان ئاراستە کراون.","کۆمپانیایەکی شارەزا بە ڕێکوپێکی سیستەمەکە دەپشکنێت و خزمەتی دەکات و کارتی خزمەتگوزاری پێوە دەکات؛ ماوەکەی لەلایەن بەرگریی شارستانی و لایەنی مۆڵەتدەرەوە دادەنرێت."]},{heading:"٤. سلیندەر، مانیفۆڵد و بۆرییەکانی گاز",body:"گاز لە چێشتخانەدا تەنها کاتێک سەلامەتە کە بە دروستی دانرابێت و بەکاربهێنرێت:",points:["سلیندەرەکانی گاز و مانیفۆڵدەکەیان (Manifold، ئەو بۆرییەی چەند سلیندەرێک پێکەوە دەبەستێتەوە) لە دەرەوەی چێشتخانە ڕابگرە، لە شوێنێکی هەوادار، بە ڕاوەستاوی و پارێزراو لە گەرما و لە دەستکاری؛ هەرگیز لە نهۆمی ژێرزەوی یان لە ژێر ئاستی زەوی نا.","تەنها تەکنیکارێکی شارەزای گاز بۆری، ڕێگولەیتەر و ئامێرەکان دادەنێت، دەیانبەستێتەوە، چاکیان دەکات و خزمەتیان دەکات. کارمەندان تەنها ئەگەر ڕاهێنانیان کردبێت سلیندەر دەگۆڕن.","ڕاهێنان بە کارمەندان بکە تا هەموو ڕۆژێک بەدوای کەموکوڕیی ئاشکرادا بگەڕێن، وەک لوولە یان پەیوەندییەکی تێکچوو، گڕێک کە دەکوژێتەوە و هەڵنامێنێت، یان بۆنی گاز، و ڕایبگەیەنن و ئامێرەکە بەکارنەهێنن.","ئەگەر گازەکە بە پانکەی ڕاکێشانەوە بەسترابێتەوە (Interlock)، کاتێک پانکەکە دەوەستێت گازەکەش دەبڕدرێت. هەرگیز ئەم بەستنەوەیە تێمەپەڕێنە و لەکاری مەخە.","هەموو ئاشپەزێک دەزانێت سەمامەی گازی چێشتخانە لە کوێیە، و تەنها بەو شێوەیە بەکاری دەهێنێت کە ڕێسای بۆنی گاز لە خوارەوە ڕێگەی پێدەدات.","هەرگیز بە ئاگر بەدوای دزەی گازدا مەگەڕێ."]},{heading:"٥. ئەگەر بۆنی گازت لە چێشتخانەدا کرد",body:`١. هیچ ئاگرێک دامەگیرسێنە و هیچ گڵۆپ، پانکە یان ئامێرێک هەڵمەکە و مەکوژێنەرەوە. لە ناو شوێنەکەدا تەلەفۆن بەکارمەهێنە.
٢. سەمامەی گاز تەنها دابخە ئەگەر لە نزیکت بوو و توانیت پێی بگەیت بەبێ ئەوەی بچیتە ئەو شوێنەی گازی تێدا کۆبووەتەوە و بەبێ هیچ پریشکێک؛ ئەگەر نا، لێی نزیک مەبەوە.
٣. بە ئارامی کارمەندان و کڕیاران دەربهێنە و دراوسێکان ئاگادار بکەرەوە.
٤. لە دەرەوە پەیوەندی بە ١١٥ بکە، و مەگەڕێوە ژوورەوە تا پسپۆڕان نەڵێن سەلامەتە.`,critical:!0},{heading:"٦. چەوری: پاککردنەوەی دووکەڵکێش، فلتەر و بۆری",body:"ئەو چەورییەی لە دووکەڵکێش، فلتەر و بۆریی ڕاکێشاندا کۆ دەبێتەوە سووتەمەنییە و چاوەڕێی گڕێکە:",points:["گڕی سوورکردنەوە، برژاندن یان فلامبێ (Flambé) دەتوانن چەوریی کۆبووەوە دابگیرسێنن، و ئاگرێک لە بۆرییەکەدا دەتوانێت بە ناو بیناکەدا بڵاو ببێتەوە.","فلتەر، ڕووی دووکەڵکێش، دیوار، زەوی و ئامێرەکان بەپێی خشتەیەکی دیاریکراو پاک بکەرەوە، بۆ ئەوەی چەوری کۆ نەبێتەوە.","با کۆمپانیایەکی شارەزا بۆریی ڕاکێشان بە ڕێکوپێکی پاک بکاتەوە و تۆمارەکە بپارێزە. چەند جار دەبێت بەپێی جۆر و بڕی چێشتلێنانە؛ داواکارییەکە لەلایەن بەرگریی شارستانی و لایەنی مۆڵەتدەرەوە دادەنرێت.","فرایەر تەنها دوای ساردبوونەوەی ڕۆنەکە بەتاڵ و پاک بکەرەوە، و هەرگیز فرایەر مەجووڵێنە کاتێک ڕۆنەکەی گەرمە.","کارتۆن، پەڕۆ، کاغەز و قاپی ڕۆن دوور لە ئامێرەکانی چێشتلێنان و گەرما ڕابگرە."]},{heading:"٧. ڕاهێنانی کارمەندان و دەرهێنانی کڕیاران",body:"هەموو کەسێک لە ڕێستوران لە یەکەم ڕۆژی کارەوە پلانەکە دەزانێت:",points:["پلانی باری نائاسایی دیاری دەکات کێ ئاگادارکەرەوەی ئاگر لێدەدات، کێ پەیوەندی بە ١١٥ دەکات، کێ گاز دەبڕێت ئەگەر سەلامەت بوو، کێ ڕێنمایی کڕیاران دەکات و کێ لە خاڵی کۆبوونەوە کارمەندان دەژمێرێت.","کارمەندانی خزمەتگوزاری بە ئارامی بە کڕیاران دەڵێن لە نزیکترین دەرچوونەوە دەربچن، و ناهێڵن بۆ پارەدان یان کۆکردنەوەی کەلوپەلەکانیان بوەستن.","تەوالێت، هۆڵەکانی نانخواردن و کۆگاکان لە ڕێگای دەرچووندا بپشکنە، تەنها ئەگەر سەلامەت بوو، و دەرگاکان لە دوای خۆتەوە دابخە.","دەرگای پشتەوە و دەرچوونی چێشتخانە چۆڵ ڕابگرە، و هەرگیز دەرگاکانی دەرچوون قفڵ مەکە کاتێک کارمەند یان کڕیار لە ناوەوەن.","لە یەکەم ڕۆژدا، دەرچوونەکان، دەسکی کارپێکردنی دەستی، ئاگرکوژێنەرەوە، بەتانیی ئاگر و سەمامەی گاز نیشانی هەر کارمەندێکی نوێ بدە، و بە ڕاهێنان پلانەکە تاقی بکەنەوە.","لە خاڵی کۆبوونەوە، بە ئاگرکوژەکان بڵێ ئایا سیستەمی دووکەڵکێش کاری کردووە، ئایا گاز بڕاوە و ئایا کەس ون بووە."]}],media:[{kind:"image",src:"media/images/w8_kitchen_grease_fire.webp",title:"ئاگری ڕۆن لە چێشتخانەیەکی بازرگانیدا",description:"ئاشپەزێک سەرپۆشێکی کانزایی بە سەر تاوەیەکی گڕگرتوودا دەکێشێت؛ دەسکی کارپێکردنی دەستی و ئاگرکوژێنەرەوەی کیمیایی شل لە نزیک دەرچوون دیارن"}],quiz:[{question:"ئاگرێکی بچووک لە تاوەیەکدا لەسەر تەباخ هەڵدەبێت. کاری دروست چییە؟",options:[{text:"پەرداخێک ئاو بکە سەر تاوەکە بۆ ئەوەی ڕۆنەکە بە خێرایی سارد ببێتەوە",correct:!1},{text:"تاوەکە هەڵبگرە و ببە دەرەوە بۆ ئەوەی ئاگرەکە لە چێشتخانە دەربچێت",correct:!1},{text:"ئەگەر سەلامەت بوو گەرماکە ببڕە و سەرپۆشێکی کانزایی بخە سەر تاوەکە",correct:!0},{text:"ئاگرکوژێنەرەوەی تۆزی ABC ی نووسینگەکە بهێنە و بیپرژێنە سەر تاوەکە",correct:!1}],explanation:"دانانی سەرپۆش لەسەر تاوەکە هەوا دەبڕێت، و بڕینی گەرما ڕێگری لە زیاتر گەرمبوونی ڕۆنەکە دەکات. ئاو ڕۆنی گڕگرتوو وەک تۆپێکی ئاگر فڕێ دەدات، جووڵاندنی تاوەکە ئاگرەکە بڵاو دەکاتەوە، و تۆزی ABC بۆ ڕۆنی چێشتلێنان دروست نەکراوە."},{question:"ئاگرێک لە ژێر دووکەڵکێشدا ناکوژێتەوە. چێشتخانەکە سیستەمی دووکەڵکێش و ئاگرکوژێنەرەوەی کیمیایی شلی هەیە. چی یەکەم دێت؟",options:[{text:"سیستەمی دووکەڵکێش بە دەسکی دەستی کارپێبکە، پاشان ئاگرکوژێنەرەوەکە",correct:!0},{text:"یەکەمجار ئاگرکوژێنەرەوەکە بەکاربهێنە و سیستەمەکە بۆ ئاگرێکی گەورەتر بهێڵەوە",correct:!1},{text:"پانکەی ڕاکێشان بوەستێنە و فلتەرەکان دەربهێنە بۆ ئەوەی دووکەڵ دەربچێت",correct:!1},{text:"چاوەڕێ بکە تا سیستەمەکە خۆی کار دەکات پێش ئەوەی هیچ شتێک بکەیت",correct:!1}],explanation:"سیستەمی دووکەڵکێش گاز یان کارەبا دەبڕێت و ڕووی چێشتلێنان، دووکەڵکێش و بۆرییەکە بە ماددەی کوژاندنەوە دادەپۆشێت. ئاگرکوژێنەرەوەی کیمیایی شل بۆ بەکارهێنان دوای کارپێکردنی سیستەمەکە دروستکراوە، وەک نیشانەی تەنیشتی دەڵێت."},{question:"بۆچی نابێت ئامێرەکانی چێشتلێنانی ژێر دووکەڵکێش بەبێ دامەزرێنەری سیستەمەکە بجووڵێنرێن یان بگۆڕدرێن؟",options:[{text:"ئامێری قورستر دەتوانن کاشیی زەویی ژێر دووکەڵکێشەکە بشکێنن و تێکی بدەن",correct:!1},{text:"سەرە پرژێنەکان بۆ ئامێری دیاریکراون و لەوانەیە ئامێری نوێ نەگرنەوە",correct:!0},{text:"جووڵاندنیان دەنگی چێشتخانەکە بۆ ئاشپەز و کڕیاران زیاد دەکات",correct:!1},{text:"ئامێری نوێ هەمیشە سیستەمی ئاگری تایبەتی خۆیان لەگەڵدایە",correct:!1}],explanation:"سیستەمەکە ئەو ئامێرانە دەپارێزێت کە بۆیان دیزاین کراوە. ئەگەر ئامێرێک جووڵێنرا یان گۆڕدرا، دامەزرێنەر دەبێت بپشکنێت ئایا سەرە پرژێنەکان هێشتا دەیگرنەوە."},{question:"سلیندەرەکانی گازی LPG و مانیفۆڵدی ڕێستورانێک دەبێت لە کوێ بن؟",options:[{text:"لە نهۆمی ژێرزەوی، چونکە سارد دەمێننەوە و دوورن لە ڕێگای کارمەندان",correct:!1},{text:"لە ناو چێشتخانەکە لە ژێر تەباخەکە، نزیک ئەو گڕانەی گازیان پێدەدەن",correct:!1},{text:"لە کۆگای هۆڵی نانخواردن، لە پشت کورسییە لەسەریەک دانراوەکان",correct:!1},{text:"لە دەرەوە لە شوێنێکی هەوادار، بە ڕاوەستاوی و پارێزراو لە گەرما",correct:!0}],explanation:"گازی LPG لە هەوا قورسترە و لە شوێنە نزمەکانی وەک نهۆمی ژێرزەوی کۆ دەبێتەوە. سلیندەرەکان لە دەرەوە لە شوێنێکی هەوادار، بە ڕاوەستاوی و دوور لە گەرما دادەنرێن، و تەکنیکارێکی شارەزا پەیوەندییەکان دەبەستێت."},{question:"بۆچی پاککردنەوەی چەوری لە دووکەڵکێش، فلتەر و بۆری کارێکی سەلامەتی لە ئاگرە؟",options:[{text:"چەوریی کۆبووەوە دەتوانێت بە گڕی چێشتلێنان بسووتێت و لە بۆریدا بڵاو ببێتەوە",correct:!0},{text:"چەوری تەنها بۆنی خواردن دەگۆڕێت و هیچ مەترسییەکی ئاگر زیاد ناکات",correct:!1},{text:"بۆریی پاک وا دەکات سیستەمی دووکەڵکێش زۆرجار و بەبێ ئاگر بە هەڵە کار بکات",correct:!1},{text:"چینێکی چەوری کانزای بۆرییەکە لە گەرمای زۆری چێشتلێنان دەپارێزێت",correct:!1}],explanation:"گڕی سوورکردنەوە، برژاندن یان فلامبێ دەتوانن چەوریی ناو دووکەڵکێش و بۆری دابگیرسێنن، و ئاگرێک لە بۆرییەکەدا دەتوانێت بە ناو بیناکەدا بڵاو ببێتەوە. پاککردنەوەی ڕێکوپێک ئەم سووتەمەنییە لادەبات."}]},{id:24,code:"BUS-124",icon:"Building",accent:"#6d28d9",title:"سەلامەتی لە ئاگر لە هۆتێل و شوێنەکانی مانەوەی میوان",subtitle:"ئاگادارکەرەوەی شەو، زانیاریی میوانان، ڕۆڵی کارمەندان و ئەو میوانانەی پێویستیان بە یارمەتییە",summary:"لە هۆتێلدا، میوانان لە بینایەکدا دەخەون کە نایناسن، و هەندێکیان ناتوانن بەبێ یارمەتی دەربچن. بۆیە ئاگری شەو گەورەترین مەترسییە. ئەم وانەیە بۆ خاوەن، بەڕێوەبەر، کارمەندانی پێشوازی و کارمەندانی شەوە: دەبێت چی بە میوانان بوترێت، ڕێسای دەرگای ژوور، هەر کارمەندێک بە شەو چی دەکات، چۆن یارمەتی میوانانی خاوەن پێداویستیی تایبەت بدرێت، و چۆن ئاگادارکەرەوەی دووکەڵ و دەرگای بەرگری ئاگر هەمووان دەپارێزن. داواکارییەکانی بەرگریی شارستانی و لایەنی مۆڵەتدەر جێبەجێ بکەن.",blocks:[{heading:"١. بۆچی شەو گەورەترین مەترسییە",body:"پلانی ئاگری هۆتێل دەبێت لە خراپترین کاتیشدا کار بکات:",points:["میوانی خەوتوو بە هێواشی بەئاگا دێن و لەوانەیە سەریان لێ بشێوێت، و بیناکە و دەرچوونەکانی نایناسن.","دوای ئەوەی ئاگادارکەرەوە لێدەدات، لەوانەیە تەنها چەند خولەکێک بۆ دەرچوونی سەلامەت هەبێت.","دووکەڵ بە ڕاڕەوەکاندا بڵاو دەبێتەوە و بە پلیکانەکاندا بەرز دەبێتەوە؛ دەرگای داخراو بڵاوبوونەوەی دووکەڵ، گەرما و ئاگر خاو دەکاتەوە.","بە شەو کەمترین کارمەند لەسەر کارن، بۆیە پلانەکە دەبێت تەنها لەگەڵ تیمی شەو کار بکات، و دەبێت کارمەندی پێویست هەبن بۆ یارمەتیدانی ئەو میوانانەی ناتوانن خۆیان دەربچن."]},{heading:"٢. ئاگادارکەرەوە، هەستەوەری دووکەڵ و دەرگای بەرگری ئاگر",body:"ئەمانە میوانان لە کاتی خەوتندا دەپارێزن، بە مەرجێک کار بکەن:",points:["لە هەر ژوورێکی میواندا هەستەوەری دووکەڵ و ئاگادارکەرەوەیەک هەیە کە دەنگی بەس بەرزە بۆ بەئاگاهێنانەوەی میوانێکی خەوتوو.","ئەگەر هەبوو، ژوورێک کە ئاگادارکەرەوەی ڕووناکیی تروسکەدار یان پارچەی لەرزۆکی (Vibrating pad) هەبێت پێشکەشی ئەو میوانانە بکە کە کەڕن یان بیستنیان لاوازە.","دەرگاکانی بەرگری ئاگر (Fire door) لە ڕاڕەو و پلیکانەکاندا خۆیان دادەخرێن. هەرگیز بە پاڵپشت یان بە بەستنەوە کراوەیان مەهێڵەوە، و دەرگایەک کە بە تەواوی دانەخرێت یەکسەر ڕابگەیەنە.","سیستەمی سپرینکلەر لە هەر ژوورێکی میواندا، لەو شوێنانەی دانراوە، پاراستنی زیاتر دەدات.","هەموو ڕۆژێک بپشکنە کە ڕێگاکانی دەرچوون چۆڵن، دەرگاکانی دەرچوون دەکرێنەوە و ڕووناکیی باری نائاسایی کار دەکات؛ ماوەکانی تاقیکردنەوە و خزمەتگوزاری لەلایەن بەرگریی شارستانییەوە دادەنرێن."]},{heading:"٣. هەر میوانێک دەبێت چی بزانێت",body:"لە کاتی تۆمارکردنی هاتندا، زانیاریی ئاگر بدە بە هەر میوانێک:",points:["پلانی دەرچوون لەسەر ڕووی ناوەوەی دەرگای ژوورەکە نیشان دەدات ژوورەکە لە کوێیە و ڕێگاکان بەرەو نزیکترین دەرچوونەکان.","بە میوانان بڵێ دەنگی ئاگادارکەرەوەی ئاگر چۆنە و دوو نزیکترین دەرچوون لە کوێن، و پێشنیار بکە دەرگاکانی نێوان ژوورەکەیان و دەرچوونەکە بژمێرن؛ ئەمە لە تاریکی یان لە دووکەڵدا یارمەتیدەرە.","کلیلی ژوورەکە لە تەنیشت جێگاکەت دابنێ و کاتێک دەردەچیت لەگەڵ خۆتی ببە.","کاتێک ئاگادارکەرەوە لێدەدات: یەکسەر دەربچۆ، دەرگاکان لە دوای خۆتەوە دابخە و پلیکانە بەکاربهێنە، هەرگیز ئاسانسۆر نا.","دەرگاکانی دەرچوون لەسەر ڕێگاکانی دەرچوون هەمیشە لە ناوەوە بەبێ کلیل دەکرێنەوە."]},{heading:"٤. ڕێسای دەرگای ژوور",body:"ئەم ڕێسایە فێری کارمەندان بکە و لەسەر ئاگاداریی ئاگری هەموو ژوورێک بینووسە:",points:["پێش کردنەوەی دەرگای ژوورەکە، بە پشتی دەستت دەرگاکە و دەسکەکەی تاقی بکەرەوە. ئەگەر گەرم بوو، یان دووکەڵ لە دەورییەوە دەهات، داخراوی بهێڵەوە.","ئەگەر دەرگاکە سارد بوو، بە هێواشی بیکەرەوە و ئامادە بە یەکسەر دایبخەیتەوە ئەگەر لە دەرەوە دووکەڵ یان ئاگر هەبوو.","ئەگەر ڕاڕەوەکە چۆڵ بوو، دەربچۆ، دەرگاکە لە دوای خۆتەوە دابخە و بڕۆ بۆ نزیکترین دەرچوون؛ ئەگەر دووکەڵ هەبوو، خۆت نزم بکەرەوە.","ئەگەر هەموو ڕێگاکان گیرابوون: لە ژوورەکەدا بمێنەوە و دەرگاکە داخراو بهێڵەوە، کەلێنەکانی دەوری دەرگا و کونەکانی هەوا بە خاولی یان جێگا بگرە، پانکە و ساردکەرەوە بکوژێنەرەوە، پەیوەندی بە ١١٥ بکە و ژمارەی ژوورەکە بڵێ، و لە بەردەم پەنجەرەکە ئاماژە بدە.","خۆت لە نهۆمە بەرزەکانەوە فڕێ مەدە؛ چاوەڕێی ئاگرکوژەکان بکە."]},{heading:"٥. ڕۆڵی کارمەندان بە شەو",body:"پلانی شەو دیاری دەکات کێ چی دەکات، تەنانەت ئەگەر تەنها یەک یان دوو کارمەند لەسەر کار بن:",points:["پێشوازی ئاگادارکەرەوەکە پشتڕاست دەکاتەوە، یەکسەر پەیوەندی بە ١١٥ دەکات و ناونیشان، شوێنی ئاگرەکە و ژمارەی میوانانی ناو هۆتێلەکە دەڵێت.","پێشوازی لیستی ژوورە پڕەکان و لیستی ئەو میوانانەی پێویستیان بە یارمەتییە دەباتە خاڵی کۆبوونەوە.","کارمەندان لە ڕێگای دەرچووندا میوانان ئاگادار دەکەنەوە و بەرەو دەرچوونەکان دەیانبەن، و ژوور، تەوالێت و ڕاڕەوەکان تەنها لەو شوێنانە دەپشکنن کە سەلامەتن؛ هەرگیز ناچنە ناو دووکەڵ و دەرگای گەرم ناکەنەوە.","لە خاڵی کۆبوونەوە، لیستی ژوورە پڕەکان لەگەڵ ئامادەبووان بەراورد بکە.","کاتێک ئاگرکوژەکان دەگەن، پێشوازییان بکە و پێیان بڵێ کام ژوورانە لەوانەیە هێشتا میوانیان تێدا بێت، ئەو میوانانەی پێویستیان بە یارمەتییە لە کوێ چاوەڕێ دەکەن و هەر مەترسییەکی تایبەت، وەک گاز.","کەس ناگەڕێتەوە ژوورەوە تا بەرگریی شارستانی نەڵێت سەلامەتە."]},{heading:"٦. میوانانی خاوەن پێداویستیی تایبەت",body:"پێش ئەو شەوەی پێویستیان پێی دەبێت، پلانیان بۆ دابنێ:",points:["لە کاتی تۆمارکردنی هاتندا، بە ڕێزەوە و بە جیا لە خەڵکی تر لە میوانان بپرسە ئایا لە باری نائاساییدا پێویستیان بە یارمەتی دەبێت بۆ دەرچوون، و لیستێکی ناو و ژمارەی ژوورەکانیان لە پێشوازی ڕابگرە.","ئەگەر توانرا، ژوورێک لە نهۆمێکی نزم و نزیک لە دەرچوونێک بدە بەم میوانانە.","هەرگیز لە ئاگردا ئاسانسۆری ئاسایی بەکارمەهێنە. ئەو میوانەی ناتوانێت پلیکانە بەکاربهێنێت، بە ناو دەرگاکانی بەرگری ئاگردا لەسەر هەمان نهۆم لە ئاگرەکە دوور دەخرێتەوە، یان لەگەڵ کارمەندێک لە شوێنی پەنای تەنیشت پلیکانەی پارێزراو چاوەڕێ دەکات، وەک پلانی هۆتێلەکە دەڵێت.","هەرگیز میوانێک بە تەنها لە شوێنی پەنا جێمەهێڵە، و یەکسەر و بە وردی بە ئاگرکوژەکان بڵێ لە کوێ چاوەڕێ دەکات.","نابێت پلانەکە پشت بە ئاگرکوژەکان ببەستێت بۆ ڕزگارکردنی ئەو میوانانەی چاوەڕێ دەکەن: دەبێت کارمەندی ڕاهێنراوی پێویست هەبن بۆ یارمەتیدانیان."]},{heading:"٧. فێرکردن و ڕاهێنان",body:"کارمەندان بە شەو تەنها ئەوە دەتوانن بکەن کە ڕاهێنانیان لەسەر کردووە:",points:["پێش یەکەم دەوامی شەو، هەر کارمەندێکی نوێ فێر بکە: ئاگادارکەرەوە، دەرچوونەکان، دەرگاکانی بەرگری ئاگر، لیستەکانی ژوور و ڕۆڵی خۆی.","ڕاهێنان ئەنجام بدە، لەوانەش لەو کاتانەی کەمترین کارمەند لەسەر کارن، و وا ڕاهێنان بکەن وەک ئەوەی دەرچوونێک یان پلیکانەیەک گیرابێت.","پلانی باری نائاسایی و لیستەکانی ژوور لە پێشوازی لەبەردەستدا ڕابگرە، و لیستەکان لە هەر تۆمارکردنێکی هاتن و ڕۆیشتندا نوێ بکەرەوە.","چەند جار ڕاهێنان دەکرێت و چ فێرکردنێک پێویستە، لەلایەن بەرگریی شارستانی و لایەنی مۆڵەتدەرەوە دیاری دەکرێن."]}],media:[{kind:"image",src:"media/images/w8_hotel_night_evacuation.webp",title:"دەرهێنانی میوانان بە شەو لە هۆتێل",description:"کارمەندێکی شەو بە چرایەکی دەستی میوانان بە ناو ڕاڕەوەکەدا بەرەو پلیکانەی دەرچوون دەبات، و دەرگایەکی بەرگری ئاگر لە پشتیانەوە داخراوە"}],quiz:[{question:"پلانی دەرچوون لەسەر ڕووی ناوەوەی دەرگای ژووری میوان دەبێت چی نیشان بدات؟",options:[{text:"ژوورەکە لە کوێیە و ڕێگاکان بەرەو دوو نزیکترین دەرچوون",correct:!0},{text:"تەنها ژمارەی تەلەفۆنی هۆتێل و کاتی ڕۆیشتن لە هۆتێل",correct:!1},{text:"ڕێگای ئاسانسۆر و ڕێگای دەرگای سەرەکی بە تەنها",correct:!1},{text:"شوێنی ڕێستورانی هۆتێل و شوێنی وەستاندنی ئۆتۆمبێل",correct:!1}],explanation:"پلانەکەی سەر دەرگا شوێنی ژوورەکە و ڕێگاکان بەرەو دەرچوونەکان نیشان دەدات، بۆ ئەوەی میوان بە خێرایی و تەنانەت لە تاریکیشدا ڕێگای خۆی بدۆزێتەوە. ئاسانسۆر لە ئاگردا بەکارناهێنرێت."},{question:"ئاگادارکەرەوە بە شەو لێدەدات. میوانێک هەست دەکات دەسکی دەرگای ژوورەکەی گەرمە. دەبێت چی بکات؟",options:[{text:"دەرگاکە بە خێرایی بکاتەوە و بە ناو ڕاڕەوەکەدا بەرەو نزیکترین پلیکانە ڕابکات",correct:!1},{text:"دەرگاکە کەمێک بکاتەوە بۆ ئەوەی سەیری ڕاڕەوەکە بکات و پاشان بڕیار بدات",correct:!1},{text:"دەرگاکە داخراو بهێڵێتەوە، کەلێنەکان بگرێت، پەیوەندی بە ١١٥ بکات و ئاماژە بدات",correct:!0},{text:"بە ئاسانسۆر دابەزێت، چونکە لەوانەیە ڕاڕەوەکە پڕ بێت لە دووکەڵ",correct:!1}],explanation:"دەسکی گەرم واتە ئاگر یان دووکەڵی گەرم لە پشت دەرگاکەیە. دەرگای داخراو میوانەکە دەپارێزێت: کەلێن و کونەکانی هەوا بگرە، پەیوەندی بە ١١٥ بکە، ژمارەی ژوورەکە بڵێ و لە بەردەم پەنجەرەکە ئاماژە بدە."},{question:"لە کاتی دەرهێنانی شەودا، کام ئەرک هی پێشوازییە؟",options:[{text:"لای مێزەکە دەمێنێتەوە بۆ وەڵامدانەوەی تەلەفۆنی میوانان تا ئاگرەکە دەکوژێتەوە",correct:!1},{text:"پەیوەندی بە ١١٥ دەکات و لیستی ژوورە پڕەکان دەباتە خاڵی کۆبوونەوە",correct:!0},{text:"دەچێتە ناو هەموو ژوورەکان، لەوانەش ژووری پڕ لە دووکەڵ، بۆ گەڕان",correct:!1},{text:"پێش دەرچوون لە بیناکە جانتای میوانان کۆ دەکاتەوە",correct:!1}],explanation:"پێشوازی یەکسەر پەیوەندی بە ١١٥ دەکات و لیستەکانی ژوور دەبات بۆ ئەوەی لە خاڵی کۆبوونەوە ژماردن بکرێت و ئاگرکوژەکان بزانن کام ژوورانە لەوانەیە هێشتا میوانیان تێدا بێت. کەس ناچێتە ناو دووکەڵ."},{question:"میوانێک کە کورسیی چەرخدار بەکاردەهێنێت لە نهۆمی سێیەمدایە کاتێک ئاگادارکەرەوە لێدەدات. چی دروستە؟",options:[{text:"کارمەندێک بە ئاسانسۆری ئاسایی دایدەبەزێنێت، چونکە لە پلیکانە خێراترە",correct:!1},{text:"کارمەندان بە تەنها لە شوێنی پەنا جێیدەهێڵن و لە دەرەوە چاوەڕێی ئاگرکوژەکان دەکەن",correct:!1},{text:"کارمەندان پێی دەڵێن لە ژوورەکەی بمێنێتەوە تا ئاگادارکەرەوەکە خۆی دەوەستێت",correct:!1},{text:"کارمەندێک دەیباتە شوێنی پەنا، لەگەڵی دەمێنێتەوە و ئاگرکوژەکان ئاگادار دەکاتەوە",correct:!0}],explanation:"ئاسانسۆری ئاسایی لە ئاگردا بەکارناهێنرێت. میوانەکە لە ئاگرەکە دوور دەخرێتەوە یان لەگەڵ کارمەندێک لە شوێنی پەنا چاوەڕێ دەکات، هەرگیز بە تەنها جێناهێڵدرێت، و ئاگرکوژەکان یەکسەر دەزانن لە کوێیە."},{question:"بۆچی نابێت دەرگاکانی بەرگری ئاگر لە ڕاڕەوەکانی هۆتێلدا بە پاڵپشت کراوە بهێڵرێنەوە؟",options:[{text:"دەرگای کراوە بە شەو هەوای سارد لە پلیکانەکانەوە دەهێنێتە ناو ڕاڕەوی میوانان",correct:!1},{text:"دەرگای داخراو دووکەڵ، گەرما و ئاگر خاو دەکاتەوە و ڕێگای دەرچوون دەپارێزێت",correct:!0},{text:"دەرگای کراوە وا دەکات میوانان دەنگی ئاگادارکەرەوە زۆر بەرز لە ژوورەکانیاندا ببیستن",correct:!1},{text:"دەرگای بەرگری ئاگر قورسە و پاڵپشت بە تێپەڕبوونی کات لەولاکانی تێک دەدات",correct:!1}],explanation:"دەرگای بەرگری ئاگر تەنها کاتێک دەپارێزێت کە داخراو بێت: بڵاوبوونەوەی دووکەڵ، گەرما و ئاگر خاو دەکاتەوە و ڕێگای دەرچوون بۆ میوانان سەلامەت ڕادەگرێت. دەرگایەک کە بە پاڵپشت کراوە بێت ئەم پاراستنە نادات."}]},{id:25,code:"BUS-125",icon:"Fuel",accent:"#b45309",title:"سەلامەتیی بەنزینخانەکان",subtitle:"Ignition Control, Static, Spills, Emergency Stop & LPG",summary:"بەنزینخانەکان بڕێکی زۆر لە شلە و گازە ئاگرگرەکان هەڵدەگرن و دەیفرۆشن. ئەم مۆدیولە بە کارمەندان، سەرپەرشتیاران و بەڕێوەبەران نیشان دەدات چۆن سەرچاوەکانی هەڵگیرسان و کارەبای ستاتیکی کۆنترۆڵ بکەن، چۆن مامەڵە لەگەڵ ڕژانی سووتەمەنی بکەن، چۆن دوگمەی وەستاندنی تەنگانە بەکاربهێنن، چۆن غازی LPG بە سەلامەتی پڕ بکەنەوە و چی بکەن ئەگەر ئاگر لە لای پەمپ هەڵگیرسا.",blocks:[{body:"بەنزین تەنانەت لە هەوای ساردیشدا هەڵمی ئاگرگر دەردەدات (خاڵی هەڵگیرسانی نزیکەی -٤٣°C یە)، و هەڵمەکەی لە هەوا قورسترە: بە سەر زەویدا بڵاو دەبێتەوە و لە شوێنە نزمەکانی وەک ئاوەڕۆ، چاڵ و نهۆمی ژێرزەویدا کۆ دەبێتەوە. پریشکێک، ئاگرێک، جگەرەیەک یان بزوێنەرێکی کارا دەتوانێت هەڵیبگیرسێنێت. یاساکانی مۆڵەتدان، دیزاین و ئامێرەکانی بەنزینخانەکان لە لایەن بەرگریی شارستانی و دەزگای مۆڵەتدانەوە دادەنرێن: داواکارییەکانیان جێبەجێ بکە. ئەم مۆدیولە ڕوونی دەکاتەوە کە هەر کارمەند، سەرپەرشتیار و بەڕێوەبەرێک دەبێت چی بکات."},{heading:"١. کۆنترۆڵکردنی سەرچاوەکانی هەڵگیرسان لە لای پەمپەکان",body:"پێش پڕکردنەوە و لە کاتی پڕکردنەوەدا، کارمەند دڵنیا دەبێتەوە کە:",points:["بزوێنەری ئۆتۆمبێلەکە لە لای پەمپ کوژێنراوەتەوە.","کەس لە نزیک پەمپەکان جگەرە ناکێشێت و چەخماخە یان ئاگری کراوە بەکارناهێنێت، و نیشانەکانی «جگەرەکێشان قەدەغەیە» و «بزوێنەر بکوژێنەرەوە» لە نزیک پەمپەکان دانراون.","کۆنترۆڵ بەردەوامە: هەموو ئۆتۆمبێلێک و هەموو کەسێک لە لای پەمپەکان دەبینیت، و پەمپ تەنها کاتێک دادەگیرسێنیت کە هیچ مەترسییەک نەبێت.","پڕی ناکەیتەوە ئەگەر بزوێنەر کار بکات، ئەگەر کەسێک لە نزیکەوە جگەرە بکێشێت یان ئەگەر دەبەکە پەسەندکراو نەبێت؛ ئەگەر کڕیار ڕازی نەبوو، بانگی سەرپەرشتیار بکە.","مۆبایل: یاسای بەنزینخانەکەی خۆت جێبەجێ بکە (هەندێک ڕێنمایی داوا دەکەن مۆبایل و ڕادیۆ لە لای پەمپەکان بەکارنەهێنرێن)، و سەرنجت لەسەر سەرچاوە سەرەکییەکانی هەڵگیرسان بێت: جگەرە، ئاگر، بزوێنەری کارا و کارەبای ستاتیکی.","گۆڕەپانی پەمپەکان پاک ڕادەگیرێت، بەبێ پەڕۆ، کارتۆن یان ماددەی ئاگرگری تر لە نزیک پەمپەکان."]},{heading:"٢. کارەبای ستاتیکی و دەبەی سووتەمەنی",body:"پریشکێکی کارەبای ستاتیکی لە سەری لوولەی پەمپ (nozzle) دەتوانێت هەڵمی سووتەمەنی هەڵبگیرسێنێت:",points:["باشترە کڕیاران لە کاتی پڕکردنەوەدا لە دەرەوەی ئۆتۆمبێل بمێننەوە: خلیسکان لەسەر کورسی کارەبای ستاتیکی کۆ دەکاتەوە. ئەگەر پێویست بوو بگەڕێنەوە ناو ئۆتۆمبێل، پێش ئەوەی دووبارە دەست لە سەری لوولەکە بدەن، دەست لە پارچەیەکی کانزایی ئۆتۆمبێلەکە بدەن، دوور لە شوێنی پڕکردنەوە.","دەبەی سووتەمەنی تەنها کاتێک پڕ بکەرەوە کە لەسەر زەوی بێت؛ هەرگیز لە ناو سندوقی دواوە، لەسەر کورسی یان لە پشتی پیکابدا پڕی مەکەرەوە.","پێش کردنەوەی دەبەکە، سەری لوولەکە لە دەبەکە بدە، و لە کاتی پڕکردنەوەدا سەری لوولەکە بە دەمی دەبەکەوە بهێڵەوە.","تەنها دەبەی گونجاو و پەسەندکراوی سووتەمەنی پڕ بکەرەوە، هەرگیز بوتڵ، سەتڵ یان قوتووی خواردن نا؛ کام دەبە و کام قەبارە ڕێگەپێدراوە، دەزگای مۆڵەتدان دیاری دەکات.","دەبەکە بە باشی دابخە؛ دەبەی سووتەمەنی و سلیندەری غاز هەرگیز لە بەشی سەرنشینانی ئۆتۆمبێلدا ناگوازرێنەوە."]},{heading:"٣. ڕژانی سووتەمەنی",body:"کارمەندانی ڕاهێنراو دەتوانن مامەڵە لەگەڵ ڕژانێکی بچووک بکەن، بۆ نموونە لە پڕکردنەوەی زیادەوە؛ ڕژانێکی گەورە تەنگانەیە:",points:["١. ڕژانەکە ڕابگرە: دەستی لوولەکە بەربدە یان پەمپەکە ڕابگرە؛ ئەگەر نەوەستا، دوگمەی وەستاندنی تەنگانە دابگرە.","٢. خەڵک و ئۆتۆمبێلەکان دوور بخەرەوە؛ کەس لە نزیکەوە بزوێنەر داناگیرسێنێت، جگەرە ناکێشێت و هیچ ئامێرێکی کارەبایی هەڵناکات.","٣. بە دەستکێشەوە، ڕژانەکە بە لم یان ماددەی هەڵمژەر (absorbent) ی ناو کیتی ڕژان دابپۆشە؛ بە ناو سووتەمەنییەکەدا مەڕۆ.","٤. سووتەمەنییەکە بە ئاو مەشۆ: ئاو دەیباتە ناو ئاوەڕۆکان، کە هەڵمەکەی تێیدا کۆ دەبێتەوە و دەتوانێت بتەقێتەوە.","٥. ماددە تەڕبووەکە لە قوتوویەکی کانزایی داخراودا کۆ بکەرەوە: هێشتا ئاگرگرە.","یەکسەر پەیوەندی بە ١١٥ بکە ئەگەر سووتەمەنی گەیشتە ئاوەڕۆ یان شەقام، ئەگەر بۆنی سووتەمەنی لە ناو باڵەخانەیەکدا هات، ئەگەر ڕژانەکە گەورە بوو یان ئەگەر ئاگری گرت."]},{heading:"٤. دوگمەی وەستاندنی تەنگانە",body:"دوگمەی وەستاندنی تەنگانە (Emergency Stop) کارەبای هەموو پەمپەکان پێکەوە دەبڕێت. شوێنی دانانی و ماوەی تاقیکردنەوەی لە لایەن بەرگریی شارستانی و دەزگای مۆڵەتدانەوە دیاری دەکرێن:",points:["هەموو کارمەندێک دەزانێت هەر دوگمەیەکی وەستاندنی تەنگانە لە کوێیە، لە ناوەوە لە لای کاشێر و لە دەرەوە لە گۆڕەپانی پەمپەکان، و ڕاهێنانی لەسەر داگرتنی کردووە.","دایبگرە بۆ هەر ڕژانێک کە ناتوانیت ڕایبگریت، هەر ئاگرێک، هەر دزەیەکی غاز لە شوێنی LPG و هەر ئۆتۆمبێلێک کە بەر پەمپێک بکەوێت.","بە دیار و بە نیشانەیەکی ڕوون بیهێڵەوە، و هەرگیز بە کاڵا، ڕەفەی نمایش یان ئۆتۆمبێلی وەستاو دایمەپۆشە.","پلانی تەنگانەی بەنزینخانەکە نەخشەیەکی شوێنی تێدایە کە تانکەکان، پەمپەکان، دوگمەکانی وەستاندنی تەنگانە، ئاگرکوژێنەرەوەکان، کیتی ڕژان و خاڵی کۆبوونەوە نیشان دەدات.","هەموو کارمەندێک ناونیشانی وردی بەنزینخانەکە دەزانێت و دەزانێت چۆن شوێنەکەی بۆ ١١٥ ڕوون بکاتەوە."]},{heading:"٥. پڕکردنەوەی غازی ئۆتۆمبێل (LPG)",body:"غازی LPG وەک شلەیەکی ژێر پەستان هەڵدەگیرێت. کاتێک دزە دەکات، هەورێکی غاز دروست دەکات کە لە هەوا قورسترە و دەتوانێت لە شوێنێکی دوور لە دزەکە هەڵبگیرسێت. لە پرۆفایلی سەرچاوەی پرۆژەدا ئاگری LPG پۆلی B ی NFPA یە (غاز)؛ لە سیستەمی EN 2 دا پۆلی C یە.",points:["تەنها کارمەندانی ڕاهێنراو غازی LPG پڕ دەکەنەوە؛ کڕیاران خۆیان پڕی ناکەنەوە، مەگەر دەزگای مۆڵەتدان ڕێگەی دابێت.","کارمەند بە درێژایی پڕکردنەوەکە لە لای ئۆتۆمبێلەکە دەمێنێتەوە، تا ئامێرەکە دەکوژێنرێتەوە و ڤاڵڤەکان دادەخرێن.","بزوێنەرەکان کوژاونەتەوە، و کەس لە نزیک شوێنی پڕکردنەوە جگەرە ناکێشێت و ئاگر بەکارناهێنێت.","دەستکێش و پارێزەری چاو بەکاربهێنە: LPG ی شل پێست بە سەرما دەسووتێنێت.","پێش بەستنەوە ڤاڵڤی پڕکردنەوەی ئۆتۆمبێلەکە بپشکنە؛ ئەگەر غاز لە بەستەرەکەوە دزەی کرد، پڕکردنەوە ڕابگرە.","ئەگەر غاز بەردەوام دزەی کرد یان ئاگری گرت: دوگمەی وەستاندنی تەنگانە دابگرە، خەڵک دوور بخەرەوە و پەیوەندی بە ١١٥ بکە. ڤاڵڤی غاز تەنها دابخە ئەگەر بە سەلامەتی پێی بگەیت؛ هەرگیز ئاگری غاز مەکوژێنەرەوە ئەگەر ناتوانیت غازەکە ڕابگریت."]},{heading:"٦. ئاگر لە لای پەمپ",body:"ئەگەر ئۆتۆمبێلێک یان پەمپێک ئاگری گرت:",points:["یەکسەر دوگمەی وەستاندنی تەنگانە دابگرە و زەنگی ئاگر لێبدە.","بە شۆفێرەکە بڵێ سەری لوولەکە لە ناو ئۆتۆمبێلەکەدا بهێڵێتەوە و دوور بکەوێتەوە؛ هەمووان لە ئۆتۆمبێلەکان دەربهێنە و لە پەمپەکان دووریان بخەرەوە.","پەیوەندی بە ١١٥ بکە (و ١٢٢ ئەگەر کەسێک بریندار بوو) و یەکەمجار ناو و ناونیشانی بەنزینخانەکە بڵێ.","هەمووان لانیکەم ٣٠ مەتر (١٠٠ پێ) لە ئۆتۆمبێلە ئاگرگرتووەکە دوور ڕابگرە، و مەهێڵە ئۆتۆمبێلی تر بێنە ناو بەنزینخانەکە.","کاپۆت یان سندوقی دواوەی ئۆتۆمبێلێکی ئاگرگرتوو مەکەرەوە: هەوای تازە ئاگرەکە گەورەتر دەکات.","کارمەندێکی ڕاهێنراو دەتوانێت ئاگرکوژێنەرەوە بەکاربهێنێت تەنها لەسەر ئاگرێکی بچووک کە تازە دەستی پێکردووە، بە ئاگرکوژێنەرەوەیەک کە لەیبڵەکەی سووتەمەنیی شل دەگرێتەوە (پۆلی B؛ NFPA B ی شلەکان = EN B)، کاتێک ڕێگای دەرچوون لە پشتیەوە بێت و ئاگادارکردنەوە درابێت. لەو دوورییەوە دەست پێ بکە کە لەسەر لەیبڵەکە نووسراوە؛ ئەگەر ئاگرەکە یەکسەر نەکوژایەوە، دوور بکەوەرەوە.","ئەم هەنگاوانە لە ڕاهێنانی ڕێکوپێکدا لەگەڵ هەموو کارمەندان دووبارە بکەرەوە، و هەر ڕاهێنانێک تۆمار بکە."],critical:!0}],media:[{kind:"image",src:"media/images/w8_fuel_station_safety.webp",title:"پڕکردنەوەی سەلامەت لە لای پەمپ",description:"بزوێنەر کوژاوە، دەبە لەسەر زەوی، دوگمەی وەستاندنی تەنگانە و ئاگرکوژێنەرەوە ئامادە"}],quiz:[{question:"کڕیارێک لە کاتی پڕکردنەوەدا گەڕاوەتەوە ناو ئۆتۆمبێلەکە و ئێستا دەگەڕێتەوە لای پەمپ. پێش ئەوەی دەست لە سەری لوولەکە بدات، دەبێت چی بکات؟",options:[{text:"دەست لە کانزای ئۆتۆمبێلەکە بدات، دوور لە شوێنی پڕکردنەوە",correct:!0},{text:"دەستی لوولەکە بە پەڕۆیەکی وشک پاک بکاتەوە",correct:!1},{text:"سەری لوولەکە بە خێرایی دەربهێنێت و پەمپ دووبارە دابگیرسێنێت",correct:!1},{text:"لە ناو ئۆتۆمبێلدا بمێنێتەوە تا پەمپەکە خۆی دەوەستێت",correct:!1}],explanation:"خلیسکان لەسەر کورسی کارەبای ستاتیکی کۆ دەکاتەوە. دەستدان لە کانزا دوور لە شوێنی پڕکردنەوە ئەو کارەبایە بەتاڵ دەکاتەوە پێش ئەوەی دەست بگاتە سەری لوولەکە، کە پریشکێک دەتوانێت هەڵمەکەی لێ هەڵبگیرسێنێت."},{question:"سووتەمەنی لە لوولەیەکەوە کە داناخرێت دەڕژێتە سەر زەویی بەنزینخانەکە. یەکەم کار چییە؟",options:[{text:"سووتەمەنییەکە بە ئاو بەرەو ئاوەڕۆکان بشۆ",correct:!1},{text:"ڕژانەکە بە پەمپ یان بە دوگمەی تەنگانە ڕابگرە",correct:!0},{text:"ئۆتۆمبێلەکە داگیرسێنە و لە ڕژانەکە دووری بخەرەوە",correct:!1},{text:"ماددەی هەڵمژەر لە دەوری بڕێژە بەڵام پەمپەکە ڕامەگرە",correct:!1}],explanation:"یەکەمجار سەرچاوەی ڕژانەکە ڕابگرە، پاشان سەرچاوەکانی هەڵگیرسان و خەڵک دوور بخەرەوە و ڕژانەکە بە ماددەی هەڵمژەر کۆنترۆڵ بکە. ئاو سووتەمەنی دەباتە ناو ئاوەڕۆکان، کە هەڵمی تێدا کۆ دەبێتەوە، و داگیرساندنی بزوێنەرێک دەتوانێت هەڵمەکە هەڵبگیرسێنێت."},{question:"کاتێک دەبەیەکی سووتەمەنی پڕ دەکرێتەوە، دەبێت لە کوێ بێت؟",options:[{text:"لە پشتی پیکابێکدا، ئامادە بۆ ڕۆیشتن",correct:!1},{text:"لەسەر کورسیی دواوە، سەرنشینێک ڕایدەگرێت",correct:!1},{text:"لەسەر زەوی، و سەری لوولەکە بە دەبەکەوە",correct:!0},{text:"لە سندوقی دواوەدا، و دەرگاکەی بە تەواوی کراوە",correct:!1}],explanation:"لە ناو ئۆتۆمبێلدا، ڕایەخ یان ڕووپۆشی پلاستیکیی پیکاب دەبەکە لە زەوی جیا دەکەنەوە، بۆیە کارەبای ستاتیکیی ڕژانی سووتەمەنی ناتوانێت دەربچێت و دەتوانێت لە سەری لوولەکەدا پریشک بدات (NIOSH). لەسەر زەوی و کاتێک سەری لوولەکە بە دەبەکەوەیە، کارەباکە بە سەلامەتی دەچێتە زەوی."},{question:"لە کاتی پڕکردنەوەی LPG دا، غاز لە بەستەرەکەوە دزە دەکات. کارمەند دەبێت چی بکات؟",options:[{text:"پڕکردنەوە ڕابگرێت، ڤاڵڤەکان دابخات و خەڵک و بزوێنەرەکان دوور بخاتەوە",correct:!0},{text:"پڕکردنەوەکە بە خێرایی تەواو بکات و دواتر بەستەرەکە توند بکات",correct:!1},{text:"بە ئاگرکوژێنەرەوەی CO₂ لە دزەکە بدات بۆ ساردکردنەوەی بەستەرەکە",correct:!1},{text:"داوا لە شۆفێر بکات بزوێنەر داگیرسێنێت و یەکسەر بڕوات",correct:!1}],explanation:"LPG ی دزەکردوو هەورێکی غاز دروست دەکات کە دەتوانێت هەڵبگیرسێت. پڕکردنەوە ڕابگرە، ئەگەر بە سەلامەتی پێی دەگەیت غازەکە دابخە و سەرچاوەکانی هەڵگیرسان دوور ڕابگرە؛ ئەگەر دزەکە نەوەستا، دوگمەی وەستاندنی تەنگانە دابگرە و پەیوەندی بە ١١٥ بکە."},{question:"ئۆتۆمبێلێک لە لای پەمپ ئاگری گرت. کام کار دروستە؟",options:[{text:"پێش هەموو شتێک سەری لوولەکە لە ئۆتۆمبێلەکە دەربهێنە",correct:!1},{text:"کاپۆتەکە بکەرەوە تا ئاگرەکە ببینرێت و پێی بگەیت",correct:!1},{text:"بە لوولەی ئاو ئاو بکە سەر سووتەمەنییە گڕگرتووەکە",correct:!1},{text:"دوگمەی تەنگانە دابگرە، شوێنەکە چۆڵ بکە و پەیوەندی بە ١١٥ بکە",correct:!0}],explanation:"دوگمەی وەستاندنی تەنگانە سووتەمەنیی هەموو پەمپەکان دەبڕێت. سەری لوولەکە لە شوێنی خۆی بهێڵەوە، کاپۆتەکە داخراو بهێڵەوە و هەمووان بە باشی دوور بخەرەوە؛ ئاو سووتەمەنیی گڕگرتوو بڵاو دەکاتەوە."}]},{id:26,code:"IND-126",icon:"Package",accent:"#0f766e",title:"سەلامەتیی کۆگاکان لە ئاگر",subtitle:"Stacking, Clearances, Sprinklers, Battery Charging & Security",summary:"لە کۆگادا، ئاگر دەتوانێت لە چەند خولەکێکدا بە کۆمەڵێک کاڵادا تا بان سەربکەوێت. ئەم مۆدیولە بە کارمەندان، سەرپەرشتیاران و بەڕێوەبەران نیشان دەدات چۆن کاڵا بە سەلامەتی کەڵەکە و هەڵبگرن، سپرینکلەرەکان کارا ڕابگرن، پاتریی فۆرکلیفتەکان شەحن بکەن، مامەڵە لەگەڵ پاتریی لیتیۆم-ئایۆن و کاڵای مەترسیدار بکەن و باڵەخانەکە بە شەو بپارێزن.",blocks:[{body:"لە کاڵای کەڵەکەکراو و ڕەفە بەرزەکاندا، ئاگر بە خێرایی بەرەو سەری کەڵەکەکە سەردەکەوێت و پاشان بە لایەکاندا بۆ هەموو ئاستەکان بڵاو دەبێتەوە؛ لە تاقیکردنەوەکاندا لەسەر قوتووی سەر ڕەفەی ١٠ مەتر بەرز، ئاگر زۆرجار لە ماوەی دوو خولەکدا گەیشتە سەری ڕەفەکان (ڕێبەری حکومەتی بەریتانیا بۆ سەلامەتیی کارگە و کۆگاکان لە ئاگر). باری ئاگری (Fire Load) کۆگا بەپێی ئەو کاڵایانەیە کە تێیدا هەڵدەگیرێن، و زۆرجار لە هی ماڵ و نووسینگە بەرزترە. ئەم یاسایانەی خوارەوە ڕێکاری باشی گشتین؛ هەر باڵەخانەیەک دەبێت پێش هەموو شتێک داواکارییەکانی بەرگریی شارستانی و دەزگای مۆڵەتدان جێبەجێ بکات."},{heading:"١. کەڵەکەکردن و بۆشایی",body:"کاڵای هەڵگیراو دەبێت جێگیر بێت و ڕێگە لە خەڵک، سپرینکلەرەکان و تیمەکانی ئاگرکوژاندنەوە نەگرێت:",points:["کاڵا بە شێوەیەکی جێگیر کەڵەکە بکە: بە پاڵپشت، بە یەکەوە بەستراو و بە بەرزییەکی سنووردار، تا نەخلیسکێت و نەڕووخێت.","زیاتر لە پێویست کەڵەکە مەکە: هەر شوێنێکی هەڵگرتن زۆرترین بڕی نووسراوی هەیە.","لانیکەم ١ مەتر بۆشایی لە نێوان سەری کاڵاکان و بان، کاریتەکانی بان یان گڵۆپەکاندا بهێڵەوە (ڕێنماییی HSE ی بەریتانیا).","لە ژێر سەری سپرینکلەرەکاندا، ئەو بۆشاییە بهێڵەوە کە دیزاینی سپرینکلەرەکە دیاری دەکات؛ کەمترین ڕێژەی گشتی بەپێی OSHA ٤٥ سانتیمەترە (١٨ ئینج)، و هەندێک جۆری سپرینکلەر زیاتریان پێویستە.","هەرگیز مەهێڵە ڕەفە و کاڵا سەری سپرینکلەرەکان دابپۆشن.","کاڵای ئاگرگر لەسەر ئامێری کارەبایی، گڵۆپ یان سۆبە کەڵەکە مەکە، تەنانەت ئەگەر کوژاوەش بن.","پالێتی بەتاڵ، ماددەی پاکێتکردن و پاشماوە لە شوێنێکی دیاریکراو دوور لە باڵەخانە، دەرچوون و پەنجەرەکان، یان لە شوێنێکی خاوەن سپرینکلەر هەڵبگرە."]},{heading:"٢. ڕاڕەو، دەرچوون و دەرگای ئاگر",body:"ڕێگای کراوە ڕێگە دەدات خەڵک دەربچن و تیمەکانی ١١٥ بگەنە ئاگرەکە:",points:["ڕاڕەو و تێپەڕگەکان کراوە و ساغ ڕابگرە؛ ڕاڕەوە هەمیشەییەکان لەسەر زەوی نیشانە کراون.","هەرگیز کاڵا لە ڕێگاکانی دەرچوون یان لە بەردەم دەرچوون، دەرگای ئاگر، پەردەی ئاسنینی ئاگر (fire shutters)، ئاگرکوژێنەرەوە یان دوگمەکانی زەنگی ئاگر دامەنێ.","بۆشاییەک لە نێوان کاڵاکان و دیوارە ناوەکییەکاندا بهێڵەوە تا تیمەکانی ئاگرکوژاندنەوە بگەنە ئاگرەکە (ڕێنماییی بەریتانیا: ٠٫٥ مەتر).","دەرچوونەکانی ئاگر دەبێت لە ناوەوە بەبێ کلیل بکرێنەوە هەر کاتێک کەسێک لە باڵەخانەکەدا بێت.","تەنها شۆفێرانی ڕاهێنراو و مۆڵەتدار فۆرکلیفت لێدەخوڕن، و پیادەکان لە ڕاڕەوە نیشانەکراوەکاندا دەڕۆن."]},{heading:"٣. سپرینکلەر: کارای ڕابگرە",body:"سپرینکلەرەکان ئاگر بە شێوەیەکی ئۆتۆماتیکی کۆنترۆڵ دەکەن، تەنانەت بە شەو کاتێک کەس نییە، بەڵام تەنها ئەگەر هیچ شتێک ڕێگەیان لێ نەگرێت:",points:["هەرگیز هیچ شتێک بە سەری سپرینکلەرەکان یان بۆرییەکانیانەوە هەڵمەواسە، و هەرگیز ڕەنگیان مەکە، دایانمەپۆشە و لێیان مەدە؛ هەر سەرێکی زیانلێکەوتوو یان دزەکردوو یەکسەر ڕابگەیەنە.","ڤاڵڤەکانی کۆنترۆڵی سپرینکلەر بە تەواوی کراوە دەمێننەوە. تەنها کەسێکی مۆڵەتدار دەتوانێت یەکێکیان دابخات، بەپێی ڕێکاری شوێنەکە بۆ ڕاگرتنی پاراستن لە ئاگر، و لەگەڵ چاودێریی زیادەی ئاگر تا دووبارە دەکرێتەوە.","ئەگەر ڤاڵڤێکی داخراو یان سەرێکی داپۆشراوت بینی، یەکسەر بە سەرپەرشتیار بڵێ: لەوانەیە ئەو شوێنە بێ پاراستن بێت.","سپرینکلەرەکان تەنها لەو شوێنەدا دەکرێنەوە کە گەرمیی ئاگرەکە پێیان دەگات، بۆیە ئاگرێک لە ژێر سەرێکی داپۆشراودا دەتوانێت بێ ئەوەی ببینرێت گەورە ببێت.","پشکنین، تاقیکردنەوە و چاککردنەوە بەپێی NFPA 25 و داواکارییەکانی بەرگریی شارستانی دەکرێن؛ تۆمارەکان بپارێزە.","هەندێک بەرهەم بە هیچ شێوەیەک نابێت لە شوێنی خاوەن سپرینکلەر هەڵبگیرێن؛ پەڕەی زانیاریی سەلامەتی (SDS) ئەمە دیاری دەکات."]},{heading:"٤. شەحنکردنی پاتریی فۆرکلیفت",body:"کاتێک پاتریی ئەسیدی (lead-acid) شەحن دەکرێت، غازی هایدرۆجین دەردەدات کە غازێکی زۆر ئاگرگرە؛ ئەگەر کۆ ببێتەوە و پریشکێک یان ئاگرێک پێی بگات، دەتوانێت بتەقێتەوە:",points:["تەنها لە شوێنی دیاریکراوی شەحنکردن شەحن بکە: شوێنێک بە هەواگۆڕکێی باش (بە هەواگۆڕکێ لە بەرزی سەرووی پاترییەکان)، دوور لە کاڵای هەڵگیراو و سەرچاوەکانی هەڵگیرسان.","لە شوێنی شەحنکردندا نە جگەرە، نە ئاگر، نە کاری گەرم و نە مۆبایل.","پێش بەستنەوە یان جیاکردنەوەی پاترییەکە، شەحنکەرەکە بکوژێنەرەوە، تا پریشک دروست نەبێت.","ئامێر و شتی کانزایی تر لەسەر پاترییەکان دامەنێ، و پێش کارکردن لەسەریان کاتژمێر، ئەڵقە و شتی کانزایی تر لە خۆت دابکەنە.","لە کاتی شەحنکردندا سەرپۆشی پاترییەکە بکەرەوە، و ئامێرەکانی پاراستن کە بۆ ئەم کارە دیاریکراون بەکاربهێنە (دەستکێش، بەروانکە و پارێزەری چاو دژی ئەسید).","سلیندەرەکانی غازی (LPG) فۆرکلیفتە غازییەکان لە دەرەوە بگۆڕە، دوور لە سەرچاوەکانی هەڵگیرسان.","تەنها کارمەندانی ڕاهێنراو پاتری دەگۆڕن یان شەحن دەکەن."]},{heading:"٥. پاتریی لیتیۆم-ئایۆن",body:"پاتریی لیتیۆم-ئایۆنی زیانلێکەوتوو، زۆر گەرمبوو یان بە هەڵە شەحنکراو دەتوانێت ئاگر بگرێت یان بتەقێتەوە، و گەرمیی خانەیەکی تێکچوو دەتوانێت بگاتە خانەی تەنیشتی (thermal runaway):",points:["ڕێنماییەکانی کۆمپانیای بەرهەمهێنەر بۆ هەڵگرتن، بەکارهێنان و شەحنکردن جێبەجێ بکە، و تەنها ئەو شەحنکەرە بەکاربهێنە کە بۆ ئەو پاترییە دروستکراوە.","پاتری و ئامێرەکان لە شوێنی وشک و فێنک، دوور لە سۆبە و سەرچاوەکانی تری گەرمی هەڵبگرە، و کاتێک پڕ بوون لە شەحن جیایان بکەرەوە.","بگەڕێ بۆ نیشانەکانی مەترسی: هەڵئاوسان یان درز، دەنگی فیشکە، دزەکردن، بەرزبوونەوەی گەرمی یان دووکەڵ. پاترییەک کە هەر یەکێک لەم نیشانانەی هەبێت یەکسەر لە کار دەخرێت.","ئەگەر دەستلێدانی سەلامەت بێت، بیبە بۆ شوێنی دیاریکراو دوور لە ماددە ئاگرگرەکان، بۆ نموونە قوتوویەکی کانزایی بەرگری ئاگر لەگەڵ لم، و بە ڕێگای پەسەندکراو بۆ لەناوبردن بینێرە.","ئەگەر پاترییەکە دووکەڵ دەدات یان دەسووتێت، هەڵیمەگرە: خەڵکی تر ئاگادار بکە، زەنگی ئاگر لێبدە، دەربچۆ و پەیوەندی بە ١١٥ بکە. خانەکانی لیتیۆم-ئایۆن لیتیۆمی کانزایی تێدا نییە و بە ئاوێکی زۆر سارد دەکرێنەوە؛ ئاگر لە پاترییە هەڵگیراوەکاندا کاری تیمەکانی ١١٥ ە.","ئاگری پاتری دەتوانێت دوای کوژانەوە دووبارە هەڵبگیرسێتەوە؛ بە تیمەکانی ١١٥ بڵێ پاترییەکان لە کوێ هەڵگیراون."],critical:!0},{heading:"٦. پاکوخاوێنی و کاڵای مەترسیدار",body:"پاشماوەی کەمتر واتە سووتەمەنیی کەمتر بۆ ئاگر، و هەڵگرتنی دروست ڕووداوێکی بچووک بە بچووکی دەهێڵێتەوە:",points:["شوێنەکانی هەڵگرتن لە ماددەی پاکێتکردنی پەرشوبڵاو و پاشماوە پاک ڕابگرە؛ پاشماوە لە قوتووی گونجاودا کۆ بکەرەوە و بە ڕێکوپێکی لایببە.","لە شوێنەکانی هەڵگرتندا جگەرەکێشان قەدەغەیە.","پێش هەڵگرتنی هەر بەرهەمێکی مەترسیدار، لەیبڵ و پەڕەی زانیاریی سەلامەتی (SDS) ی بخوێنەرەوە؛ بەشی ٧ ی SDS مەرجەکانی هەڵگرتن و ئەو ماددانەی پێکەوە ناگونجێن دیاری دەکات.","ماددە نەگونجاوەکان لە یەکتر جیا بهێڵەوە: ئەگەر پێکەوە هەڵبگیرێن، دەتوانن ئاگرەکە خێراتر گەورە بکەن یان دووکەڵی ژەهراوی بڵاو بکەنەوە.","دەبە و قوتووی زیانلێکەوتوو یان دزەکردوو مەخەرە ناو کۆگاوە؛ لە سینییەک یان حەوزێکی ڕاگرتن (bund) دا دایانبنێ و ڕێنماییەکانی دابینکەر جێبەجێ بکە.","تۆمارێکی نوێی کاڵا مەترسیدارەکان و شوێنەکانیان بپارێزە، لە شوێنێکدا کە لە تەنگانەدا بتوانیت بیدەیتە تیمەکانی ١١٥."]},{heading:"٧. پاراستنی شەو و زەنگی ئاگر",body:"ئاگرێک کە کاتێک باڵەخانەکە داخراوە دەست پێ دەکات دەتوانێت بێ ئەوەی ببینرێت گەورە ببێت، و باڵەخانە چۆڵەکان ئامانجی ئاگرتێبەردانی بە ئەنقەست (arson) ن:",points:["دەرەوەی باڵەخانەکە بە باشی ڕووناک بکەرەوە و سنووری شوێنەکە پارێزراو بهێڵەوە؛ دەرگا، پەنجەرە و کونەکانی بان دابخە بەبێ ئەوەی ڕێگاکانی دەرچوون دابخەیت.","قوتووە گەورەکانی پاشماوە لە پاڵ دیواری باڵەخانەکە دامەنێ؛ سەتڵەکانی پاشماوە لە شوێنێکی پەرژینکراو و قوفڵدراو دوور لە باڵەخانەکە هەڵبگرە.","شلە و گازە ئاگرگرەکان قوفڵ بکە تا کەسانی دزەکەر نەتوانن بەکاریان بهێنن.","زەنگی ئاگر و زەنگی دزی چاودێری دەکرێن، و کەسێک یەکسەر وەڵامی هەر زەنگێک دەداتەوە.","پاسەوانەکان دەزانن چۆن زەنگی ئاگر لێبدەن، چۆن بە ناونیشانی ورد پەیوەندی بە ١١٥ بکەن و چۆن لە بەردەم دەرگا لەگەڵ کلیل و نەخشەی شوێنەکە پێشوازی لە تیمەکانی ١١٥ بکەن.","ئەو کەسانەی بە شێوەیەکی گوماناوی دەجووڵێن و هەر ئاگرێکی بچووکی بێ هۆکاری ڕوون ڕابگەیەنە؛ لەوانەیە نیشانەی ئاگرتێبەردانی بە ئەنقەست بن.","هەڵسەنگاندنی مەترسییەکانی ئاگر لانیکەم ساڵی جارێک و دوای هەر گۆڕانکارییەکی گەورە لەوەی هەڵیدەگریت یان چۆن هەڵیدەگریت نوێ بکەرەوە."]}],media:[{kind:"image",src:"media/images/w8_warehouse_fire_safety.webp",title:"کۆگایەکی ڕێکخراو و سەلامەت لە ئاگر",description:"ڕاڕەوی کراوە، بۆشایی لە ژێر سپرینکلەرەکان و شوێنێکی جیا بۆ شەحنکردن"}],quiz:[{question:"بەپێی ڕێنماییی HSE ی بەریتانیا، چەند بۆشایی دەبێت لە نێوان سەری کاڵای هەڵگیراو و بان، کاریتەکان یان گڵۆپەکاندا بهێڵرێتەوە؟",options:[{text:"لانیکەم ١ مەتر",correct:!0},{text:"لانیکەم ١٠ سانتیمەتر",correct:!1},{text:"لانیکەم ٢٥ سانتیمەتر",correct:!1},{text:"هیچ، ئەگەر کەڵەکەکە جێگیر بێت",correct:!1}],explanation:"ڕێنماییی HSE بۆ کۆگاکان لانیکەم ١ مەتر لە نێوان سەری کاڵاکان و بان، کاریتەکانی بان یان گڵۆپەکاندا داوا دەکات؛ لە ژێر سپرینکلەرەکاندا ئەو بۆشاییە جێبەجێ دەکرێت کە دیزاینی سپرینکلەرەکە دیاری دەکات (کەمترین ڕێژەی گشتی بەپێی OSHA ٤٥ سانتیمەترە)."},{question:"لە کاتی شەحنکردنی پاتریی فۆرکلیفتدا، کام ڕێکار دروستە؟",options:[{text:"لە نێوان ڕەفەکاندا شەحنی بکە تا فۆرکلیفتەکە بۆ دەوامی دواتر ئامادە بێت",correct:!1},{text:"پاترییەکە جیا بکەرەوە کاتێک شەحنکەرەکە هێشتا داگیرساوە",correct:!1},{text:"شوێنی شەحنکردنی خاوەن هەواگۆڕکێ بەکاربهێنە، بێ جگەرە و ئاگر",correct:!0},{text:"ئامێری کانزایی لەسەر پاترییەکە دابنێ تا نزیک بن",correct:!1}],explanation:"شەحنکردن غازی هایدرۆجین دەردەدات. شوێنێکی دیاریکراوی خاوەن هەواگۆڕکێ و بێ سەرچاوەی هەڵگیرسان ناهێڵێت ئەو غازە کۆ ببێتەوە و هەڵبگیرسێت؛ کوژاندنەوەی شەحنکەر پێش جیاکردنەوە و دوورخستنەوەی ئامێری کانزایی لە پاتری ڕێگە لە پریشک دەگرن."},{question:"لە کاتی ژماردنی کاڵاکاندا، ڤاڵڤێکی کۆنترۆڵی سپرینکلەرت بە داخراوی بینی. چی دەکەیت؟",options:[{text:"یەکسەر بە سەرپەرشتیار ڕایدەگەیەنم تا بە سەلامەتی بکرێتەوە",correct:!0},{text:"بە داخراوی دەیهێڵمەوە، چونکە زەنگی ئاگر ئاگادارمان دەکاتەوە",correct:!1},{text:"نیوەی دەکەمەوە تا پەستانی ئاو لە بۆرییەکاندا نزم بمێنێتەوە",correct:!1},{text:"نیشانەیەکی لێ دادەنێم و لە پشکنینی مانگی داهاتوودا دەیپشکنم",correct:!1}],explanation:"ڤاڵڤێکی کۆنترۆڵی داخراو دەتوانێت شوێنێکی تەواو بێ پاراستنی سپرینکلەر بهێڵێتەوە. دەبێت یەکسەر ڕابگەیەنرێت و لە لایەن کەسێکی مۆڵەتدارەوە بەپێی ڕێکاری شوێنەکە بکرێتەوە."},{question:"پاترییەکی لیتیۆم-ئایۆنی هەڵگیراو هەڵئاوساوە و گەرم دەبێت. کاری دروست چییە؟",options:[{text:"لە کاری بخە؛ ئەگەر دووکەڵی دا، زەنگ لێبدە و پەیوەندی بە ١١٥ بکە",correct:!0},{text:"دووبارە بیخەرە سەر شەحن تا خانەکان هاوسەنگ ببن و سارد ببنەوە",correct:!1},{text:"لە کارتۆندا بیپێچە و لەسەر ڕەفەکە بیهێڵەوە تا دەبرێت",correct:!1},{text:"جارێک بە CO₂ لێی بدە و بیگەڕێنەرەوە سەر ڕەفەکە",correct:!1}],explanation:"هەڵئاوسان و گەرمی نیشانەی تێکچوونی پاترین. پاترییەکە لە کار بخە و ئەگەر دەستلێدانی سەلامەت بوو، دوور لە ماددە ئاگرگرەکان جیای بکەرەوە؛ ئەگەر دووکەڵی دا یان سووتا، دەستی لێ مەدە: زەنگ لێبدە، دەربچۆ و پەیوەندی بە ١١٥ بکە."},{question:"کام ڕێکار باشترین پاراستن بە کۆگایەکی داخراو دەدات دژی ئاگرتێبەردانی بە ئەنقەست؟",options:[{text:"قوتووە گەورەکانی پاشماوە لە پاڵ دیوار تا پاسەوان بیانبینێت",correct:!1},{text:"کوژاندنەوەی زەنگ بە شەو تا زەنگی هەڵە نەبێت",correct:!1},{text:"پاشماوە دوور لە باڵەخانە و زەنگێکی چاودێریکراو",correct:!0},{text:"هێشتنەوەی شلە ئاگرگرەکان لە لای دەرگا بۆ گەیاندنی بەیانی",correct:!1}],explanation:"ئاگرتێبەرەکان زۆرجار پاشماوە و شلە ئاگرگرەکانی ناو شوێنەکە بەکاردەهێنن. دوورخستنەوەی قوتووەکانی پاشماوە لە باڵەخانە، قوفڵکردنی ماددە ئاگرگرەکان و زەنگێک کە چاودێری دەکرێت و وەڵامی دەدرێتەوە مەترسییەکە کەم دەکەنەوە (ڕێبەری حکومەتی بەریتانیا)."}]},{id:27,code:"IND-127",icon:"HardHat",accent:"#ca8a04",title:"سەلامەتیی شوێنی بیناسازی",subtitle:"Fire Plan, Hot Work, Temporary Electrics, Cylinders, Excavations & UXO",summary:"ئەو باڵەخانانەی لە قۆناغی دروستکردندان زۆرجار هێشتا سپرینکلەر یان زەنگی ئاگری کارایان نییە، بەڵام پڕن لە سەرچاوەی هەڵگیرسان و ماددەی ئاگرگر. ئەم مۆدیولە بە کرێکاران، سەرپەرشتیاران و بەڕێوەبەران نیشان دەدات چۆن پلان بۆ ئاگر دابنێن؛ کاری گەرم، کارەبای کاتی و سلیندەری سووتەمەنی و غاز کۆنترۆڵ بکەن؛ مەترسی لە لای داربەست و چاڵە هەڵکەندراوەکان بناسن؛ فریاکەوتنی سەرەتایی پێشکەش بکەن؛ و چی بکەن کاتێک لە کاتی هەڵکەندندا شتێکی گوماناوی دەدۆزرێتەوە.",blocks:[{body:"بەپێی NFPA، هۆکارە سەرەکییەکانی ئاگر لە باڵەخانە ژێر دروستکردنەکاندا ئامێرەکانی چێشتلێنان، ئامێرەکانی دابەشکردنی کارەبا و ڕووناکی، و ئامێرەکانی گەرمکردنەوەن. لەوانەیە سپرینکلەر، دیتێکتەری دووکەڵ و زەنگی ئاگر هێشتا کار نەکەن، و شوێنە کراوەکان کەسانی بێ مۆڵەت و ئاگرتێبەردانی بە ئەنقەست ڕادەکێشن. یاسا، مۆڵەت و ڕێپێدانەکانی شوێنەکانی بیناسازی لە لایەن بەرگریی شارستانی و دەزگای مۆڵەتدانەوە دادەنرێن: داواکارییەکانیان جێبەجێ بکە. ئەم مۆدیولە یاسا بنەڕەتییەکان بۆ هەموو کەسێک لە شوێنەکەدا دەخاتەڕوو."},{heading:"١. پلانی ئاگری شوێنەکە و خاڵی کۆبوونەوە",body:"پێش دەستپێکردنی کار، بەڵێندەری سەرەکی کە کۆنترۆڵی شوێنەکەی بە دەستە پلانی ئاگر ئامادە دەکات:",points:["هەڵسەنگاندنێکی مەترسییەکانی ئاگر و پلانێکی نووسراوی تەنگانە، کە پێش دەستپێکردنی کار ئامادەیە و لەگەڵ بەرزبوونەوەی باڵەخانەکە نوێ دەکرێتەوە.","کەسێکی دیاریکراو ڕێگرتن لە ئاگر لە شوێنەکەدا بەڕێوە دەبات (لە NFPA 241 دا: بەڕێوەبەری بەرنامەی ڕێگرتن لە ئاگر).","ڕێگای دەرچوون لە هەموو شوێنێکی کار، کراوە و نیشانەکراو، و هەرگیز قوفڵ ناکرێن کاتێک خەڵک لە شوێنەکەدان؛ هەرکوێ بکرێت، دوو ڕێگا بە دوو ئاراستەی جیاواز.","زەنگێکی ئاگر کە هەمووان لە سەرووی دەنگی شوێنەکەوە گوێیان لێ بێت، و نیشانەی ڕێنماییەکانی ئاگر لە خاڵەکانی ئاگر، دەروازەکانی شوێنەکە و شوێنەکانی خواردن.","خاڵەکانی ئاگر لەگەڵ ئاگرکوژێنەرەوەی گونجاو، و کەسانی دیاریکراو کە ڕاهێنانیان لەسەر بەکارهێنانیان کردووە.","خاڵێکی کۆبوونەوە کە هەمووان تێیدا دەژمێردرێن، بە ژماردنی کەسەکان یان بە گەڕان بە ناو شوێنەکەدا.","ڕاهێنانی دەرچوون بۆ تاقیکردنەوەی پلان و ڕاهێنان؛ هەر کرێکارێکی نوێ و هەر میوانێک لە سەرەتاوە فێری پلانەکە دەبێت."]},{heading:"٢. کاری گەرم: مۆڵەت و چاودێری ئاگر",body:"لەحیمکردن، بڕین، هاڕین (grinding) و کار بە ئاگر زۆرێک لە ئاگرەکانی شوێنی بیناسازی هەڵدەگیرسێنن. ئەگەر ڕێگایەکی تر کارەکە دەکات، ئەوە بەکاربهێنە؛ ئەگەر نا:",points:["تەنها بە مۆڵەتی کاری گەرم (Hot Work Permit) کار بکە کە لە لایەن ئەو کەسەوە درابێت کە دەسەڵاتی پەسەندکردنی هەیە.","ماددە ئاگرگرەکان لە ١١ مەتر (٣٥ پێ) ی دەوری کارەکە لابە، یان بە بەتانی یان پەردەی بەرگری ئاگر بیانپارێزە، یان کارەکە بگوازەرەوە بۆ شوێنێکی سەلامەت.","ئاگرکوژێنەرەوەیەکی گونجاو لە شوێنی کارەکە ئامادە بهێڵەوە.","چاودێری ئاگر (Fire Watch) لە کاتی کار و لە کاتی پشوودا، و لانیکەم ١ کاتژمێر دوای تەواوبوونی کار دەمێنێتەوە؛ بەرپرسی مۆڵەتەکە دەتوانێت چاودێرییەکی درێژتر داوا بکات (NFPA 51B).","کاری گەرم بە شێوەیەک پلان بکە کە زۆر پێش کۆتایی ڕۆژی کار تەواو بێت، تا پشکنینەکان پێش داخستنی شوێنەکە بکرێن (HSE ی بەریتانیا: ٢ کاتژمێر پێشتر)."]},{heading:"٣. کارەبای کاتی",body:"تەلی کارەبای کاتی لە شوێنەکەدا ئاگر و کارەبالێدان دروست دەکات کاتێک بارێکی زیادەی لەسەر بێت، زیانی پێ گەیشتبێت یان لە لایەن کەسانی نەشارەزاوە گۆڕابێت:",points:["دامەزراندنە کاتییەکان تەنها لە لایەن کارەباچییەکی شارەزاوە دیزاین، دامەزراندن، گۆڕین و پشکنین دەکرێن؛ کەسی تر هیچیان بۆ زیاد ناکات و نایانگۆڕێت.","ئەو پلاکانەی کرێکاران بەکاریان دەهێنن بە ئامێری پاراستن لە دزەی کارەبا (RCD) دەپارێزرێن، کە کاتێک کارەبا بەرەو زەوی دزە دەکات بە خێرایی کارەبا دەبڕێت؛ دوگمەی تاقیکردنەوەکەی بە ڕێکوپێکی دابگرە. RCD مەترسی کەم دەکاتەوە بەڵام جێگەی دامەزراندنێکی سەلامەت ناگرێتەوە.","بارێکی زیادە مەخەرە سەر پلاک و پلاکی فرەڕێگا، تەلی درێژکەرەوە مەخەرە ناو یەکتر، و پێش بەکارهێنان تەلە پێچراوەکان بە تەواوی بکەرەوە.","بۆ تەلی درێژکەرەوە تەلی نەرمی گونجاو بەکاربهێنە، بەرز لە زەوی؛ تەل و ئامێری زیانلێکەوتوو لە کار بخە و بە شریتی عەزل مەیانپێچە.","تەلی کاتی یان تابلۆی دابەشکردنی کارەبا لە ڕێگاکانی دەرچووندا دامەنێ، و پاشماوە لە تابلۆکانی کارەبا دوور بخەرەوە."]},{heading:"٤. سووتەمەنی و سلیندەری غاز لە شوێنەکەدا",body:"سووتەمەنی، LPG، ئەسیتیلین و ئۆکسجین بڕێکی زۆر وزەی هەڵگیراو دەهێننە شوێنەکە:",points:["تەنها کەمترین بڕی پێویست لە شوێنەکەدا بهێڵەوە، لە کۆگایەکی پارێزراو و خاوەن هەواگۆڕکێی باشدا، دوور لە ماددە ئاگرگرەکان و شوێنەکانی کار، و هەرگیز لە ناو ئەو باڵەخانەیەدا نا کە دروست دەکرێت.","بۆ سووتەمەنی تەنها دەبەی پەسەندکراو بەکاربهێنە، و هەرگیز سووتەمەنی لە دەرچوون، پلیکانە یان ڕاڕەوەکاندا هەڵمەگرە.","ئامێرەکان لە شوێنێکی دیاریکراودا سووتەمەنی بکە، کاتێک بزوێنەرەکان کوژاونەتەوە، بێ جگەرە و ئاگرکوژێنەرەوەیەک لە نزیکەوە بێت.","سلیندەری غاز بە ڕاستی و بەستراوەیی ڕابگرە تا نەکەوێت، سەرپۆشی ڤاڵڤەکەی لەسەر بێت کاتێک بەکارنایەت، و دوور لە پریشک، پاشماوەی گەرمی لەحیم و ئاگر.","سلیندەری ئۆکسجین لە سلیندەری غازی سووتەمەنی جیا هەڵبگرە: لانیکەم ٦ مەتر (٢٠ پێ) لە نێوانیاندا، یان لە پشت دیوارێکی بەرگری ئاگر (OSHA).","لە کۆتایی ڕۆژدا سووتەمەنی و سلیندەرەکان قوفڵ بکە تا کەسانی دزەکەر نەتوانن بەکاریان بهێنن.","ئەگەر سلیندەرێک دزەی کرد یان ئاگری گرت: ڤاڵڤەکە تەنها دابخە ئەگەر بە سەلامەتی پێی بگەیت؛ هەرگیز ئاگری غاز مەکوژێنەرەوە ئەگەر ناتوانیت غازەکە ڕابگریت؛ هەمووان دوور بخەرەوە و پەیوەندی بە ١١٥ بکە."]},{heading:"٥. داربەست و چاڵی هەڵکەندراو: مەترسی بناسە و ڕابوەستە",body:"کەوتنەخوارەوە لە بەرزی و ڕووخانی خەندەق کرێکارانی بیناسازی دەکوژن. دیزاینکردنی داربەست و پاڵپشتی خەندەق کاری پسپۆڕانی شارەزایە؛ هەموو کەسێک لە شوێنەکەدا دەبێت مەترسی بناسێت و ڕابوەستێت:",points:["داربەست تەنها دوای ئەوە بەکاربهێنە کە کەسێکی شارەزا پێش دەوام پشکنیبێتی؛ هەرگیز داربەستێکی زیانلێکەوتوو، ناتەواو یان بێ ڕێلی پاراستن بەکارمەهێنە، و هەرگیز خۆت مەیگۆڕە.","کارکردن لە بەرزیی ١٫٨ مەتر (٦ پێ) یان زیاتر لە ئاستێکی نزمتر، یان لە نزیک لێوارێکی کراوە یان کونێک، پێویستی بە پاراستن لە کەوتنەخوارەوە هەیە: ڕێلی پاراستن، سەرپۆش یان هارنەسێکی بەستراو بە خاڵێکی بەستنەوەی پتەوەوە.","هەرگیز مەچۆ ناو خەندەقێکی بێ پاراستن. بەپێی OSHA، ئەو چاڵانەی قووڵییان ١٫٥ مەتر (٥ پێ) یان زیاترە پێویستیان بە سیستەمێکی پاراستن هەیە کە بۆ ئەو شوێنە دیزاین کرابێت، مەگەر لە بەردێکی پتەودا هەڵکەندرابن.","کۆمە خۆڵ، کەرەستە و ئامێرەکان لانیکەم ٠٫٦ مەتر (٢ پێ) لە لێوارەکە دوور ڕابگرە.","کەسێکی شارەزا هەموو ڕۆژێک و دوای باران چاڵە هەڵکەندراوەکان دەپشکنێت.","لە کاتی نیشانەکانی ڕووخان (درز لە زەویدا، دیواری هەڵئاوساو، ئاوی دزەکردوو بۆ ناوەوە، خۆڵی کەوتوو): یەکسەر دەربچۆ، مەهێڵە کەسانی تر بچنە ناوەوە و بە سەرپەرشتیار بڵێ؛ کار تەنها کاتێک دەست پێدەکاتەوە کە مەترسییەکە کۆنترۆڵ کرابێت."]},{heading:"٦. گەیشتنی ١١٥ و فریاکەوتنی سەرەتایی",body:"لە کاتی ئاگر یان برینداربووندا، هەر خولەکێک گرنگە:",points:["دەروازەی شوێنەکە، دەرگاکان و ڕێگاکانی گەیشتن بۆ ئۆتۆمبێلەکانی ئاگرکوژێنەوەی ١١٥ و ئەمبولانسەکان کراوە ڕابگرە؛ ئۆتۆمبێلیان لێ ڕامەگرە و کەرەستەیان لێ دامەنێ.","هایدرانتەکانی ئاگر، شوێنەکانی ئاو و ئامێرەکانی ئاگرکوژاندنەوە بە دیار و ئاسان بۆ گەیشتن بهێڵەوە.","شوێنە گەورەکان پێش دەستپێکردنی کار و هەر کاتێک ڕێگاکانی گەیشتن یان مەترسییەکان دەگۆڕێن پەیوەندی بە بەرگریی شارستانییەوە دەکەن، و پاکێتێکی زانیاری (نەخشەی شوێن، مەترسییەکان، سووتەمەنی، غاز و پاترییە هەڵگیراوەکان) بۆ تیمەکانی ١١٥ ئامادە دەهێڵنەوە.","کەسێکی ڕاهێنراو لەسەر فریاکەوتنی سەرەتایی و جانتایەکی پڕی فریاکەوتنی سەرەتایی لە شوێنەکەدا هەن.","ناونیشانی شوێنەکە، ڕێنمایی گەیشتن و ژمارەکانی ١١٥ و ١٢٢ لە لای تەلەفۆنەکان، لە نووسینگەی شوێنەکە و لە دەروازەکە هەڵبواسە.","دوای کەوتنەخوارەوە لە بەرزی، کەسی بریندار مەجووڵێنە، مەگەر شوێنەکە ناسەلامەت بێت یان پێویستی بە CPR هەبێت؛ پەیوەندی بە ١٢٢ بکە."]},{heading:"٧. شتێکی گوماناوی لە کاتی هەڵکەندندا",body:"تەقەمەنیی کۆنی نەتەقیو دەتوانرێت لە کاتی هەڵکەندندا بدۆزرێتەوە، تەنانەت لەو شوێنانەش کە بە سەلامەت دادەنرێن، و دەتوانێت بتەقێتەوە ئەگەر بجووڵێنرێت یان لێی بدرێت. ئەگەر ئامێرێک، کرێکارێک یان ئامرازێک شتێکی گوماناوی دەرخست:",points:["یەکسەر ئامێرەکە و کارەکە ڕابگرە.","هەرگیز دەست لەو شتە مەدە، مەیجووڵێنە، هەڵیمەگرە، لە دەوری هەڵمەکەنە و دەری مەهێنە، و هەرگیز مەیخەرە ناو سەتڵی ئامێرەکە یان ئۆتۆمبێلێکەوە.","هەمووان لەو شوێنە دەربهێنە، و مەهێڵە خەڵک و ئامێر بچنە ناوییەوە.","پێش بەکارهێنانی مۆبایل یان ڕادیۆ زۆر دوور بکەوەرەوە (لانیکەم ٥٠ مەتر، UNMAS)، پاشان پەیوەندی بە ١١٥ بکە و ڕێنماییەکانی بەرگریی شارستانی جێبەجێ بکە.","لە شوێنێکی سەلامەتەوە، شوێنی ئەو شتە لەبیر مەکە و بە تیمەکانی ١١٥ بڵێ؛ کار تەنها کاتێک دەست پێدەکاتەوە کە لایەنە پەیوەندیدارەکان بڵێن شوێنەکە سەلامەتە."],critical:!0}],media:[{kind:"image",src:"media/images/w8_construction_site_fire_safety.webp",title:"شوێنێکی بیناسازیی ئامادە بۆ ئاگر",description:"مۆڵەتی کاری گەرم لەگەڵ چاودێری ئاگر، سلیندەری بەستراو و ڕێگای گەیشتنی کراوە"}],quiz:[{question:"بەپێی NFPA 51B، دوای تەواوبوونی کاری گەرم چاودێری ئاگر دەبێت چەند لە شوێنەکەدا بمێنێتەوە؟",options:[{text:"لانیکەم ١ کاتژمێر، یان زیاتر ئەگەر مۆڵەتەکە داوای بکات",correct:!0},{text:"تا لەحیمکەرەکە ئامێرەکانی کۆ دەکاتەوە و شوێنەکە جێدەهێڵێت",correct:!1},{text:"نزیکەی ١٠ خولەک، ئەگەر تا ئەو کاتە دووکەڵ نەبینرا",correct:!1},{text:"هیچ چاودێرییەک پێویست نییە کاتێک ئاگرکوژێنەرەوەیەک لە نزیکە",correct:!1}],explanation:"پریشک دەتوانێت لە شوێنە شاراوەکاندا بمێنێتەوە و دوای ماوەیەک ئاگر هەڵبگیرسێنێت. NFPA 51B چاودێری ئاگر لانیکەم ١ کاتژمێر دوای کارەکە داوا دەکات، و بەرپرسی مۆڵەتەکە دەتوانێت چاودێرییەکی درێژتر داوا بکات."},{question:"تەلێکی درێژکەرەوە لە شوێنەکەدا عەزلەکەی زیانی پێ گەیشتووە. دەبێت چی بکرێت؟",options:[{text:"لە کاری بخە و بیدە کەسێکی شارەزا تا بیگۆڕێت",correct:!0},{text:"شوێنە زیانلێکەوتووەکە بە شریتی عەزل بپێچە و کارەکە بەردەوام بکە",correct:!1},{text:"بیخەرە ناو تەلێکی ترەوە تا هەر یەکەیان کارەبای کەمتر هەڵبگرێت",correct:!1},{text:"تەنها بۆ ئامێری دەستیی بچووک بەکاری بهێنە تا کارەکە تەواو دەبێت",correct:!1}],explanation:"تەلی زیانلێکەوتوو کارەبالێدان و ئاگر دروست دەکات. لە کار دەخرێت و لە لایەن کەسێکی شارەزاوە بە دروستی دەگۆڕدرێت یان چاک دەکرێتەوە، هەرگیز بە شریت ناپێچرێت (HSE ی بەریتانیا)؛ RCD مەترسی کەم دەکاتەوە بەڵام تەلێکی زیانلێکەوتوو سەلامەت ناکات."},{question:"درز لە زەویدا دەردەکەوێت و خۆڵ دەکەوێتە ناو خەندەقێک کە هاوکارێک تێیدا کار دەکات. چی دروستە؟",options:[{text:"هەمووان دەربهێنە، مەهێڵە کەس بچێتە ناوەوە و بە سەرپەرشتیار بڵێ",correct:!0},{text:"بەشی ماوە بە خێرایی تەواو بکە پێش ئەوەی دیوارەکە بجووڵێت",correct:!1},{text:"بچۆ ناوەوە و دیوارەکە بە تەختەی داری زیادە ڕابگرە",correct:!1},{text:"هەڵکەنەرەکە لەسەر لێوارەکە ڕابگرە تا قورسییەکەی خۆڵەکە ڕابگرێت",correct:!1}],explanation:"درز و خۆڵی کەوتوو نیشانەی ڕووخانن. کرێکاران یەکسەر دەردەچن و لە دەرەوە دەمێننەوە تا کەسێکی شارەزا خەندەقەکە سەلامەت دەکات؛ ئامێرێکی قورس لەسەر لێوار ڕووخان زیاتر دەکات."},{question:"هەڵکەنەرێک شتێکی ژەنگاوی دەردەهێنێت کە لە گوللە تۆپ دەچێت. کاری دروست چییە؟",options:[{text:"بە هێواشی بە سەتڵی ئامێرەکە هەڵیبگرە و لە لایەک دایبنێ",correct:!1},{text:"خۆڵەکەی لەسەر پاک بکەرەوە تا بزانیت ڕاستەقینەیە یان نا",correct:!1},{text:"کار ڕابگرە، شوێنەکە چۆڵ بکە و لە دوورەوە پەیوەندی بە ١١٥ بکە",correct:!0},{text:"بیبە بۆ نووسینگەی شوێنەکە تا پۆلیس دەگات",correct:!1}],explanation:"تەقەمەنی دەتوانێت بتەقێتەوە کاتێک دەجووڵێنرێت یان لێی دەدرێت. یەکسەر ڕابوەستە، هەمووان دوور بخەرەوە، هەرگیز مەیجووڵێنە و لە شوێنێکی دوورەوە پەیوەندی بە ١١٥ بکە، و لە نزیک ئەو شتە مۆبایل یان ڕادیۆ بەکارمەهێنە (UNMAS)."},{question:"کام ڕێکخستن بۆ سلیندەری غاز لە شوێنی بیناسازیدا دروستە؟",options:[{text:"لەسەر لای خۆی دانراو تا نەکەوێت",correct:!1},{text:"لەسەر پلیکانەکان، چونکە فێنکترین شوێنی شوێنەکەیە",correct:!1},{text:"ئۆکسجین و ئەسیتیلین پێکەوە لە یەک کۆگادا بە زنجیر بەستراو",correct:!1},{text:"بە ڕاستی و بەستراوەیی، سەرپۆش لەسەر، دوور لە پریشک و گەرمی",correct:!0}],explanation:"سلیندەرەکان بە ڕاستی و بەستراوەیی و بە سەرپۆشی ڤاڵڤەوە هەڵدەگیرێن، دوور لە پریشک و گەرمی، و ئۆکسجین لە غازی سووتەمەنی جیا هەڵدەگیرێت (OSHA 1926.350). پلیکانەکان ڕێگای دەرچوونن و دەبێت لە سووتەمەنی و سلیندەر چۆڵ بن."}]},{id:28,code:"BUS-128",icon:"FireExtinguisher",accent:"#b91c1c",title:"بەتانیی ئاگر، ئاگرکوژێنەرەوەی سەر تایە و ئاگرکوژێنەرەوەی ئۆتۆمبێل",subtitle:"کەی و چۆن بە سەلامەتی بەکاریان بهێنیت، و بۆچی ئاگری پاتریی لیتیۆم-ئایۆن پێویستی بە وریاییەکی تایبەت هەیە",summary:"جگە لە ئاگرکوژێنەرەوەی دەستی، شوێنەکانی کار بەتانیی ئاگر، ئاگرکوژێنەرەوەی گەورەی سەر تایە و ئاگرکوژێنەرەوەی ناو ئۆتۆمبێل بەکاردەهێنن. هەر یەکەیان سنووری خۆی هەیە. ئەم وانەیە ڕوونی دەکاتەوە کەی و چۆن بە سەلامەتی بەکاریان بهێنیت، و چی بکەیت کاتێک پاترییەکی لیتیۆم-ئایۆن زۆر گەرم دەبێت یان ئاگر دەگرێت.",blocks:[{body:`هەر ئامێرێکی ئاگرکوژێنەوە کارێک و سنوورێکی هەیە. هەمان پشکنینی «بەڵێ یان نا» بۆ هەموویان بەکاردێت: ئاگرەکە بچووک و تازە دەستی پێکردووە، ئامێرەکە بۆ ئەو ئاگرە گونجاوە، ڕێگای دەرچوون لە پشتتەوەیە، ئاگادارکردنەوە دراوە و پەیوەندی بە ١١٥ کراوە، و تۆ ڕاهێنراویت. ئەگەر هەر وەڵامێک «نا» بوو، دەرچۆ. ئەوەی کام ستانداردی ئاگرکوژێنەرەوە لە دهۆک جێبەجێ دەکرێت (NFPA 10 یان EN 3) و کێ دەتوانێت خزمەتگوزاریی ئاگرکوژێنەرەوە بکات هێشتا پشتڕاست نەکراونەتەوە؛ داواکارییەکانی بەرگریی شارستانی و لایەنی مۆڵەتدەر جێبەجێ بکە.

پۆلەکانی ئاگر لێرەدا بە پیتەکانی NFPA 10 نووسراون وەک سەرچاوەی پرۆژە؛ سیستەمی فەرمیی دهۆک هێشتا پشتڕاست نەکراوەتەوە. هاوتاکانی EN 2: NFPA A = EN A؛ NFPA B (شلە) = EN B؛ NFPA B (گاز) = EN C؛ NFPA C (ئامێری کارەبایی کە کارەبای تێدایە) هیچ پۆلێکی EN ی نییە؛ NFPA D = EN D؛ NFPA K = EN F.`},{heading:"١. بەتانیی ئاگر: ئاگری تاوەیەکی بچووک",body:"بەتانیی ئاگر پارچە قوماشێکی بەرگەگری ئاگرە لە پاکەتێکدا کە بە خێرایی دەردەهێنرێت. بە بڕینی هەوا ئاگری بچووکی ناو تاوە یان مەنجەڵ دەکوژێنێتەوە:",points:["لە نزیک دەرگای چێشتخانە دایبنێ، نەک لە تەنیشت تەباخەکە، تا بتوانیت پێی بگەیت و هێشتا دەربچیت.","دەسکە قوماشییەکانی (tabs) بە توندی بۆ خوارەوە ڕابکێشە تا بەتانییەکە دەربچێت.","لە بەردەمی خۆتدا بیگرە و لێوارەکانی بەسەر دەستەکانتدا بپێچە، تا دەست و دەموچاوت بپارێزرێن.","بە هێواشی بیخە سەر تاوەکە؛ فڕێی مەدە. دڵنیابە کە هەموو تاوەکە دادەپۆشێت.","گەرمییەکە تەنها بکوژێنەرەوە ئەگەر بە سەلامەتی بگەیتە سویچەکەی.","بەتانییەکە لە شوێنی خۆی بهێڵەوە و تاوەکە مەجووڵێنە. بەتانییەکە هەڵمەگرە بۆ ئەوەی بزانیت ئاگرەکە کوژاوەتەوە یان نا، تا هەموو شتێک بە تەواوی سارد دەبێتەوە.","پەیوەندی بە ١١٥ بکە تەنانەت ئەگەر ئاگرەکە کوژاوە دەربکەوێت؛ ئەگەر یەکسەر نەکوژایەوە، دەرچۆ و دەرگاکە دابخە. هەرگیز ئاو مەکە سەر ڕۆنی سووتاو."]},{heading:"٢. بەتانیی ئاگر: ئاگر لە جلوبەرگدا",body:"ئەگەر ئاگر لە جلوبەرگی کەسێک گیرا:",points:["ئەو کەسە دەوەستێت، خۆی دەدات بە زەویدا، دەموچاوی بە دەستەکانی دادەپۆشێت و خۆی دەگلێنێتەوە تا گڕەکە دەکوژێتەوە.","ئەگەر بەتانیی ئاگر هەبوو، لە دەوری گڕەکە و ئەو کەسە بیپێچە و یارمەتی بدە تا خۆی بدات بە زەویدا و خۆی بگلێنێتەوە.","دەستەکانی خۆت بە لێوارەکانی بەتانییەکە بپارێزە.","پاشان سووتانەکە بە ئاوی فێنکی ڕەوان بۆ ماوەی ٢٠ خولەک سارد بکەرەوە، بڵقەکان مەتەقێنە و پەیوەندی بە ١٢٢ بکە.","بەتانیی ئاگر یەک جار بەکاردەهێنرێت و پاشان دەگۆڕدرێت. ئەوە بکڕە کە لەیبڵەکەی نیشانی دەدات کام ستاندارد جێبەجێ دەکات، بۆ نموونە EN 1869؛ بەتانییەک بەبێ نیشانەی ستاندارد لەوانەیە کار نەکات. کام ستاندارد لێرە پەسەند دەکرێت هێشتا پشتڕاست نەکراوەتەوە."]},{heading:"٣. ئاگرکوژێنەرەوەی سەر تایە",body:"ئاگرکوژێنەرەوەی سەر تایە زۆر زیاتر لە ئاگرکوژێنەرەوەی دەستی ماددە هەڵدەگرێت، لەسەر عەرەبانەیەک بە لوولەیەکی درێژ. شوێنی وەک کۆگای سووتەمەنی، وەرشەی چاککردنەوە و شوێنی بارکردن دەپارێزن:",points:["تەنها ئەو کارمەندانەی لەسەر ئەو مۆدێلە ڕاهێنراون بەکاری دەهێنن: کۆنترۆڵەکان، ڕیزبەندیی هەنگاوەکان و دووری لە مۆدێلێکەوە بۆ یەکێکی تر جیاوازن، بۆیە لەیبڵەکە جێبەجێ بکە.","هەر کاتێک توانرا دوو بە دوو کار بکەن: کەسێک عەرەبانەکە و ڤاڵڤەکە وەک لەیبڵەکە نیشانی دەدات کۆنترۆڵ دەکات، ئەوی تر لوولە و سەری لوولەکە دەگرێت. هەندێک مۆدێل بۆ یەک کەسی ڕاهێنراو دروستکراون.","ئامێرەکە ببە بۆ شوێنێک لە ناو ئەو دوورییەی لەسەر لەیبڵەکەیە، ڕێگای دەرچوون لە پشتتەوە بێت، و هەنگاوەکانی لەیبڵەکە بە ڕیز جێبەجێ بکە.","پشکنینی «بەڵێ یان نا» هەمان پشکنینە: ئاگرکوژێنەرەوەی سەر تایە ئاگرێکی گەورە بۆ کوژاندنەوە سەلامەت ناکات.","دوای هەر بەکارهێنانێک، لەلایەن تەکنیکارێکی شارەزاوە پڕ دەکرێتەوە."]},{heading:"٤. ئاگرکوژێنەرەوەی ئۆتۆمبێل",body:"بارهەڵگر، فۆرکلیفت، پاس و ئۆتۆمبێلی کۆمپانیا زۆرجار ئاگرکوژێنەرەوەیەکی بچووکیان پێیە، بەڵام زۆربەی ئاگری ئۆتۆمبێل بۆ ئەوە نین کە شۆفێر بیکوژێنێتەوە:",points:["بە زووترین کات کە سەلامەت بێت لە قەراغ ڕێگا بوەستە، بزوێنەرەکە بکوژێنەرەوە، هەمووان دەربهێنە و زۆر لە ئۆتۆمبێلەکە و لە هاتوچۆ دوور بکەونەوە، لانیکەم ٣٠ مەتر (١٠٠ پێ).","پەیوەندی بە ١١٥ بکە (و بە ١٢٢ ئەگەر کەسێک بریندار بوو) و ئۆتۆمبێلەکانی تر ئاگادار بکەرەوە؛ هەرگیز بۆ کەلوپەلەکانت مەگەڕێوە.","هەرگیز کاپۆت یان سندووقی دواوە مەکەرەوە ئەگەر پێت وابوو ئاگرەکە لە ناوەوەیە: هەوای تازە ئاگرەکە گڕ دەدات.","ئاگرکوژێنەرەوەی ئۆتۆمبێل تەنها لەسەر ئاگرێکی بچووکی تازە دەستپێکردوو بەکاربهێنە، تەنها ئەگەر ڕاهێنراو بیت، هەمووان دەرچووبن و ڕێگای گەڕانەوەت کراوە بێت. بۆ ئاگری ناو بزوێنەر، کاپۆتەکە داخراو بهێڵەوە؛ هەندێک دەزگای ئاگرکوژێنەوە ڕێنمایی دەکەن کە لە ڕێگەی تۆڕی پێشەوە (grille) یان کەلێنی لێواری کاپۆتەکەوە ئاڕاستەی بکەیت.","ئەگەر لە گوماندا بوویت، لە ئاگرەکە نزیک مەبەوە. هەرگیز ئاو مەکە سەر ئاگری بزوێنەر.","فۆرکلیفت و ئۆتۆمبێلەکانی تری کارەبایی: ئەگەر پاترییەکە لە ئاگرەکەدا بوو، وەک ئاگری پاتری مامەڵەی لەگەڵ بکە (بەشی ٥)."]},{heading:"٥. ئاگری پاتریی لیتیۆم-ئایۆن",body:"پاتریی لیتیۆم-ئایۆن لە مۆبایل، لاپتۆپ، ئامێری کارەبایی دەستی، پاسکیلی کارەبایی، فۆرکلیفت و سیستەمی هەڵگرتنی کارەبادا هەن. کاتێک زیانیان پێدەگات، زیاد لە پێویست شەحن دەکرێن یان تێکدەچن، دەتوانن زۆر گەرم ببن، گازی ژەهراوی بەربدەن، ئاگر بگرن یان بتەقنەوە:",points:["نیشانەکانی مەترسی: بۆنێکی سەیر، گەرمی، ئاوسان یان گۆڕانی شێوە یان ڕەنگ، دەنگی تەقینەوە یان دووکەڵ. یەکسەر بەکارهێنان یان شەحنکردنی ڕابگرە.","ئەگەر سەلامەت بوو، پلەگەکە دەربهێنە و لە هەر شتێک کە دەسووتێت دووری بخەرەوە.","ئەگەر ئاگری گرتبوو: هەمووان دەربهێنە، دەرگاکە دابخە و لە دەرەوە پەیوەندی بە ١١٥ بکە؛ بڵێ کە ئاگری پاترییە.","دووکەڵەکە هەڵمەمژە: پاتریی زیانلێکەوتوو دەتوانێت گازێکی ژەهراوی بەربدات کە لەوانەیە نەبینرێت.","ساردکردنەوە بە ئاوی زۆر ڕێگای پێشنیارکراوە، بەڵام تەنها کەسانی ڕاهێنراو بە ئامێری گونجاو دەیکەن؛ تۆزی ABC ی ئاسایی و CO₂ ئاگرەکە بە تەواوی ناوەستێنن.","پاتریی لیتیۆم-ئایۆن پۆلی D نییە: ماددەکانی پۆلی D تەنها بۆ پاتریی لیتیۆمی کانزایی و کانزا گڕگرەکانن.","ڕێگری: تەنها شەحنەری کۆمپانیای بەرهەمهێنەر یان ئەوەی ئەو پەسەندی دەکات بەکاربهێنە، لەسەر ڕووبەرێکی ڕەق، دوور لە شتی گڕگر و دوور لە دەرچەکان شەحن بکە، و پاترییە زیانلێکەوتووەکان لە بەکارهێنان دەربهێنە."],critical:!0},{heading:"٦. پشکنین و خزمەتگوزاری",body:"هەموو ئەم ئامێرانە ئامادە ڕابگرە:",points:["لە پشکنینی چاویی ڕێکوپێکدا، بەتانییەکانی ئاگریش بپشکنە: لە شوێنی خۆیان، بە ئاسانی دەگەیەندرێنێ، پاکەتەکە ساغ و دەسکەکانی بە ئازادی شۆڕ.","ئاگرکوژێنەرەوەی سەر تایە و ئۆتۆمبێل هەمان پشکنینی چاوییان وەک ئاگرکوژێنەرەوەکانی تر بۆ دەکرێت: لە شوێنی خۆیان، سنجاق و مۆر ساغ، پەستانپێو لە ناوچەی سەوزدا ئەگەر هەبێت، بێ زیان.","دوای هەر بەکارهێنانێک پڕکردنەوە؛ چاککردنەوەی ساڵانە و تاقیکردنەوەکانی پەستان لەلایەن تەکنیکارێکی شارەزاوە دەکرێن. یاسا ناوچەییەکانی خزمەتگوزاری و ئەوەی کێ دەتوانێت خزمەتگوزاریی ئاگرکوژێنەرەوە بکات هێشتا پشتڕاست نەکراونەتەوە.","بەتانیی ئاگری بەکارهاتوو بگۆڕە و یەکسەر ڕاپۆرتی هەر ئاگرکوژێنەرەوەیەکی بەکارهاتوو بدە."]}],media:[{kind:"image",src:"media/images/w8_fire_blanket_pan.webp",title:"بەکارهێنانی بەتانیی ئاگر لەسەر ئاگری تاوەیەکی بچووک",description:"کرێکارێک لە چێشتخانەی کارمەندان بەتانیی ئاگر لە بەردەمی خۆی دەگرێت، دەستەکانی لە پشت قوماشەکەوە پارێزراون، و بە هێواشی دەیخاتە سەر تاوەیەکی سووتاو؛ دەرگای پشتی کراوەیە."}],quiz:[{question:"تاوەیەکی بچووکی ڕۆن لەسەر تەباخەکە ئاگری گرت. بەتانیی ئاگرت لایە. ڕێگای دروست چییە؟",options:[{text:"دەستەکانت بە لێوارەکانی بپارێزە، بە هێواشی بیخە سەر تاوەکە و لەوێ بیهێڵەوە",correct:!0},{text:"لە لای تری چێشتخانەکەوە بەتانییەکە فڕێ بدە سەر تاوەکە تا دوور بمێنیتەوە",correct:!1},{text:"تاوەکە داپۆشە، پاشان دوای خولەکێک بەتانییەکە هەڵبگرە بزانیت ئاگرەکە کوژاوەتەوە",correct:!1},{text:"یەکەم جار پەرداخێک ئاو بکە سەر تاوەکە، پاشان بە بەتانییەکە دایپۆشە",correct:!1}],explanation:"بەتانییەکە بە هێواشی بخە سەر تاوەکە و دەستەکانت لە پشتیەوە پارێزراو بن، ئەگەر بە سەلامەتی توانیت گەرمییەکە بکوژێنەرەوە، بیهێڵەوە تا هەموو شتێک سارد دەبێتەوە و پەیوەندی بە ١١٥ بکە. هەرگیز ئاو لەسەر ڕۆنی سووتاو نا."},{question:"ئاگر لە جلوبەرگی هاوکارێکت گیرا. چی دەکەیت؟",options:[{text:"ڕایدەگرم، خۆی دەدات بە زەویدا و خۆی دەگلێنێتەوە، و ئەگەر هەبوو بەتانی لە دەوری گڕەکە دەپێچم",correct:!0},{text:"پێی دەڵێم بە خێرایی بەرەو نزیکترین بۆریی ئاو ڕابکات تا ئاوەکە گڕی سەر لەشی بکوژێنێتەوە",correct:!1},{text:"ئاگرکوژێنەرەوەی CO₂ ڕاستەوخۆ و لە نزیکەوە بەرەو دەموچاو و سنگی بەردەدەم تا گڕەکە دەکوژێتەوە",correct:!1},{text:"بە دەستی ڕووتی خۆم و هەتا بتوانم بە خێرایی جلە سووتاوەکانی لە لەشی دادەکەنم",correct:!1}],explanation:"وەستان، خۆدان بە زەویدا و خۆگلاندنەوە گڕەکە دەکوژێننەوە، و بەتانیی ئاگر کە لە دەوری گڕەکە پێچرابێت یارمەتی دەدات؛ دەستەکانت بە لێوارەکانی بپارێزە. پاشان سووتانەکە بە ئاوی فێنکی ڕەوان بۆ ماوەی ٢٠ خولەک سارد بکەرەوە و پەیوەندی بە ١٢٢ بکە."},{question:"کێ دەبێت ئاگرکوژێنەرەوەی سەر تایە بەکاربهێنێت؟",options:[{text:"کارمەندانی ڕاهێنراو لەسەر ئەو مۆدێلە، بەپێی لەیبڵەکە، باشتر دوو بە دوو",correct:!0},{text:"هەر کارمەندێک کە کاتی لێدانی زەنگەکە نزیکترین کەس بێت لە ئاگرەکە",correct:!1},{text:"تەنها پاسەوانی دەروازە، چونکە ئەو ئاگرکوژێنەرەوانە لە نزیک دەروازەی سەرەکی دادەنرێن",correct:!1},{text:"هەر کەسێک کە لانیکەم جارێک ئاگرکوژێنەرەوەیەکی دەستیی بچووکی لە ماڵەوە بەکارهێنابێت",correct:!1}],explanation:"ئاگرکوژێنەرەوەی سەر تایە لە مۆدێلێکەوە بۆ یەکێکی تر جیاوازە. تەنها کارمەندانی ڕاهێنراو لەسەر ئەو مۆدێلە بەکاری دەهێنن، بەپێی لەیبڵەکە، باشتر دوو بە دوو، و تەنها دوای هەمان پشکنینی «بەڵێ یان نا»."},{question:"دووکەڵ لە ژێر کاپۆتی بارهەڵگرێکی کۆمپانیاوە دەردەچێت. کاری دروست چییە؟",options:[{text:"بوەستە، بزوێنەرەکە بکوژێنەرەوە، هەمووان دەربهێنە و دوور بخەرەوە، پەیوەندی بە ١١٥ بکە و کاپۆتەکە مەکەرەوە",correct:!0},{text:"کاپۆتەکە بە تەواوی بکەرەوە تا بتوانیت ئاگرکوژێنەرەوەکە ڕاستەوخۆ بەرەو بزوێنەرەکە بگریت",correct:!1},{text:"بەردەوام لێبخوڕە تا نزیکترین وەرشە بۆ ئەوەی وەستایەک سەیری بکات",correct:!1},{text:"ئاوی بوتڵێک لە ڕێگەی کەلێنی ژێر کاپۆتەکەوە بکە سەر بزوێنەرەکە",correct:!1}],explanation:"کردنەوەی کاپۆت هەوای تازە دەدات بە ئاگرەکە و گڕی دەدات. هەمووان دەربهێنە و لانیکەم ٣٠ مەتر (١٠٠ پێ) دوور بکەوەرەوە، پەیوەندی بە ١١٥ بکە، و هەرگیز ئاو مەکە سەر ئاگری بزوێنەر."},{question:"پاتریی ئامێرێکی کارەبایی دەستی لەسەر ڕەفی شەحنکردن ئاوساوە و دووکەڵی لێ دەردەچێت. چی دەکەیت؟",options:[{text:"ئەگەر سەلامەت بوو پلەگەکە دەردەهێنم و دووری دەخەمەوە؛ ئەگەر ئاگری گرت، دەردەچم و پەیوەندی بە ١١٥ دەکەم",correct:!0},{text:"بە تۆزی پۆلی D دایدەپۆشم، چونکە پاتریی لیتیۆم-ئایۆن ئاگری کانزایە",correct:!1},{text:"دەیخەمە ناو دۆڵابێکی کانزایی و دەرگاکەی توند دادەخەم تا دووکەڵەکە لە ناوەوە بمێنێتەوە",correct:!1},{text:"بەردەوام شەحنی دەکەم، چونکە ئاوسانەکە کاتێک پاترییەکە بە تەواوی پڕ دەبێت کەم دەبێتەوە",correct:!1}],explanation:"ئاوسان و دووکەڵ نیشانەی مەترسین. ئەگەر سەلامەت بوو، پلەگەکە دەربهێنە و لە شتی گڕگر دووری بخەرەوە؛ ئەگەر ئاگری گرت، هەمووان دەربهێنە، دەرگاکە دابخە و پەیوەندی بە ١١٥ بکە. پاتریی لیتیۆم-ئایۆن پۆلی D نییە."}]}],t={lessons:e};export{t as default,e as lessons};
